const uid=()=>globalThis.crypto?.randomUUID?globalThis.crypto.randomUUID():Date.now().toString(36)+Math.random().toString(36).slice(2); const iso=d=>{const x=new Date(d);return `${x.getFullYear()}-${String(x.getMonth()+1).padStart(2,'0')}-${String(x.getDate()).padStart(2,'0')}`};
let db=null;let dataRevision=null;let saveTimer=null;let saveQueue=Promise.resolve();let activeConversationId='';let page='dashboard';let activityFilter='all';let appSpace='teacher';let authUser=null;let authReady=false;let studentId=null;let studentWorkFilter='todo';let scheduleView='week';let selectedWeek=startWeek(new Date());let modalState={};let lessonDraft=null;let lessonMediaTarget=null;let lessonDay=iso(new Date());let lessonTab='done';
