async function api(path,opt={}){const r=await fetch(path,opt);if(r.ok&&(path==='/api/data'||path==='/api/save')){const rev=r.headers.get('X-MaClasse-Revision');if(rev)dataRevision=rev}if(!r.ok){let detail=await r.text();try{const parsed=JSON.parse(detail);if(parsed.code==='REVISION_CONFLICT'||parsed.code==='REVISION_REQUIRED')detail='Les données ont changé sur le serveur. Recharge la page avant de continuer pour éviter d’écraser le travail d’un autre utilisateur.';else detail=parsed.error||detail}catch{}throw Error(detail)}return r.json()}
async function load(){let offline=false,mustChange=false;try{const session=await api('/api/auth/session');mustChange=!!(session.authenticated&&session.user?.mustChangePassword);authUser=session.authenticated&&!mustChange?session.user:null;if(authUser)db=await api('/api/data');else db=blank()}catch(e){offline=true;db=blank();authUser=null};normalize();authReady=true;render();if(mustChange)openInitialPasswordModal();if(offline)toast('Impossible de joindre le serveur MaClasse. Vérifie qu’il est lancé.')}
function save(silent=false){clearTimeout(saveTimer);saveTimer=setTimeout(()=>{const snapshot=JSON.stringify(db);saveQueue=saveQueue.catch(()=>{}).then(()=>api('/api/save',{method:'POST',headers:{'Content-Type':'application/json','If-Match':dataRevision||''},body:snapshot})).then(()=>{document.querySelectorAll('[data-bulletin-save]').forEach(el=>{if(el.textContent==='Enregistrement…')el.textContent='Enregistré'});if(!silent)toast('Enregistré')}).catch(e=>{console.error('MaClasse save failed',e);if(!silent)toast(e.message||'Erreur de sauvegarde');document.querySelectorAll('[data-bulletin-save]').forEach(el=>{if(el.textContent==='Enregistrement…')el.textContent='Échec — réessayer'})})},180)}
function nowLabel(){return new Date().toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'})}function cls(id){return db.classes.find(x=>x.id===id)}function student(id){return (Array.isArray(db?.students)?db.students:[]).find(x=>x&&x.id===id)}function subject(id){return db.subjects.find(x=>x.id===id)}function initials(s){return s?(((s.first||'?')[0]+(s.last||'?')[0]).toUpperCase()):'É'}function fmtDate(x){if(!x)return '—';return new Date(x+'T12:00:00').toLocaleDateString('fr-FR')}function time(v){return String(v||'').slice(0,5)}function messageTime(v){if(!v)return '—';const d=new Date(v);return Number.isNaN(d.getTime())?'—':d.toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'})}function messageDateTime(v){if(!v)return '—';const d=new Date(v);return Number.isNaN(d.getTime())?'—':d.toLocaleDateString('fr-FR',{day:'2-digit',month:'2-digit'})+' · '+messageTime(v)}function monday(d){let x=new Date(d);let n=x.getDay();x.setDate(x.getDate()-(n===0?6:n-1));x.setHours(0,0,0,0);return x}function startWeek(d){return monday(d)}function weekDates(){return DAYS.map((_,i)=>{let d=new Date(selectedWeek);d.setDate(d.getDate()+i);return d})}function weekKey(d){return iso(monday(d))}
function dayDistance(a,b){return Math.round((new Date(a+'T12:00:00')-new Date(b+'T12:00:00'))/86400000)} function recurring(slot,date){const ds=iso(date),start=slot.startDate||'1900-01-01',end=slot.endDate||'2999-12-31';if(ds<start||ds>end||(slot.exceptions||[]).includes(ds))return false;if(slot.recurrence==='once')return ds===start;if(new Date(ds+'T12:00:00').getDay()!==((Number(slot.day)+1)%7))return false;const diff=dayDistance(ds,start);if(diff<0)return false;if(slot.recurrence==='biweekly')return diff%14===0;if(slot.recurrence==='triweekly')return diff%21===0;if(slot.recurrence==='custom')return diff%(Number(slot.intervalWeeks||4)*7)===0;return true}
function occurrences(date){return db.schedule.filter(s=>recurring(s,date)).map(s=>({...s,date:iso(date)}))}
function dayOcc(d){const ds=iso(d);return db.schedule.filter(s=>recurring(s,d)).map(s=>{const ov=(s.overrides||{})[ds];return ov?{...s,...ov,time:ov.time||s.time,endTime:ov.endTime||s.endTime,day:ov.day??s.day,_overrideDate:ds}:s}).sort((a,b)=>a.time.localeCompare(b.time))}
function lessonFor(o){const exact=db.lessons.find(l=>String(l.scheduleId)===String(o.id)&&String(l.date)===String(o.date));if(exact)return exact;return db.lessons.find(l=>String(l.scheduleId)===String(o.id)&&(!o.date||String(l.date)===String(o.date)))||null}
function avg(ids){return weightedAverageForEvaluations(db.evaluations.filter(e=>e.grades?.some(g=>ids.includes(g.studentId)&&g.value!=='')),ids)}
