function ensureUsers(){if(!Array.isArray(db.users))db.users=[];if(!db.users.some(u=>u.role==='admin'))db.users.push({id:'u-admin',role:'admin',username:'admin',passwordHash:'8c6976e5b5410415bde908bd4dee15dfb167a9c873fc4bb8a81f6f2ab448a918',name:'Direction',active:true});if(!db.users.some(u=>u.role==='teacher'))db.users.push({id:'u-teacher-local',role:'teacher',username:'enseignant',passwordHash:'a608f391bff586bf0cd3fad5f7a2496d0b48c919db3c0c61b955206e3e97ed41',teacherId:'teacher-local',name:'Enseignant',active:true});for(const u of db.users.filter(x=>x.role==='teacher')){if(!u.teacherId||!db.teachers.some(t=>t.id===u.teacherId)){const n=splitPersonName(u.name||u.username);const t={id:uid(),role:'teacher',first:n.first||u.username,last:n.last,email:u.email||'',classIds:[],active:u.active!==false};db.teachers.push(t);u.teacherId=t.id}}syncTeacherClassLinks()}
