async function performLogin(e,role){e.preventDefault();const f=new FormData(e.target),username=String(f.get('username')||'').trim().toLowerCase(),pass=String(f.get('password')||'');try{const r=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({username,password:pass})});const out=await r.json();if(!r.ok)throw Error(out.error||'Connexion impossible.');closeModal();if(out.user.mustChangePassword){openInitialPasswordModal();return}writeSession(out.user);db=await api('/api/data');normalize();appSpace=out.user.role==='student'?'student':'teacher';page=out.user.role==='student'?'studentHome':(role==='admin'?'adminUsers':'dashboard');render()}catch(err){toast(err.message||'Identifiant ou mot de passe incorrect.')}}
function openInitialPasswordModal(){openModal('Sécuriser ce compte',`<div class="notice warn">Avant d’utiliser MaClasse, remplace le mot de passe provisoire par un mot de passe personnel d’au moins 12 caractères.</div><form onsubmit="saveInitialPassword(event)"><div class="form"><div class="field full"><label>Mot de passe provisoire actuel</label><input class="input" name="current" type="password" autocomplete="current-password" required></div><div class="field full"><label>Nouveau mot de passe</label><input class="input" name="next" type="password" minlength="12" autocomplete="new-password" required></div><div class="field full"><label>Confirmer le nouveau mot de passe</label><input class="input" name="confirm" type="password" minlength="12" autocomplete="new-password" required></div></div><div class="modalfoot"><button class="btn primary">Enregistrer et continuer</button></div></form>`)}
async function saveInitialPassword(e){e.preventDefault();const f=new FormData(e.target),current=String(f.get('current')||''),next=String(f.get('next')||''),confirm=String(f.get('confirm')||'');if(next.length<12)return toast('Choisis au moins 12 caractères.');if(next!==confirm)return toast('Les deux mots de passe ne correspondent pas.');try{const r=await fetch('/api/auth/change-password',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'same-origin',body:JSON.stringify({currentPassword:current,newPassword:next})}),out=await r.json();if(!r.ok)throw Error(out.error||'Modification impossible.');closeModal();const session=await api('/api/auth/session');writeSession(session.user);db=await api('/api/data');normalize();appSpace=authUser.role==='student'?'student':'teacher';page=authUser.role==='student'?'studentHome':(authUser.role==='admin'?'adminUsers':'dashboard');render();toast('Mot de passe modifié.')}catch(err){toast(err.message||'Modification impossible.')}}
