function notificationReadKey(n){return `${n.type}:${n.id||n.label||n.title}`}
function recordBulletinPublicationNotification(b){if(!b?.studentId||!b.published)return;db.notifications??=[];const id=`${b.id}:${b.publishedAt||'published'}`,key=notificationReadKey({type:'bulletin',id});if(!db.notifications.some(n=>n.key===key))db.notifications.push({key,type:'bulletin',id,studentId:b.studentId,read:false,date:b.publishedAt||new Date().toISOString()})}
function notificationFeed(role='teacher',sid=''){const out=[];db.notifications??=[];if(role==='teacher'){db.submissions.filter(x=>x.status!=='draft'&&!x.corrected).forEach(x=>{const l=db.lessons.find(q=>q.id===x.lessonId),st=student(x.studentId);if(l&&st)out.push({id:x.id,type:'submission',date:x.submittedAt,title:'Rendu à corriger',label:l.homework?.title||'Travail',detail:`${st.first} ${st.last}`,action:`openWorkTracking('${l.id}')`})});db.evaluations.forEach(e=>{const missing=(e.grades||[]).filter(g=>g.value==='').length;if(missing)out.push({id:e.id,type:'grade',date:e.date,title:'Notes à saisir',label:e.title||'Évaluation',detail:`${missing} note${missing>1?'s':''} manquante${missing>1?'s':''}`,action:`openEvaluation('${e.id}')`})})}else{const s=student(sid);if(!s)return [];studentLessonsFor(sid).forEach(l=>{const sub=studentSubmitted(l,sid);if(l.homework?.due&&!sub&&l.homework.due>=iso(new Date()))out.push({id:l.id,type:'work',date:l.homework.due,title:'Travail à faire',label:l.homework.title||'Travail',detail:l.subject||'',action:`openStudentWork('${l.id}')`});if(sub?.corrected)out.push({id:sub.id,type:'correction',date:sub.correctedAt||sub.submittedAt,title:'Correction disponible',label:l.homework.title||'Travail',detail:l.subject||'',action:`openStudentWork('${l.id}')`})});(db.bulletins||[]).filter(b=>b.studentId===sid&&b.published&&db.notifications.some(n=>n.type==='bulletin'&&n.studentId===sid&&n.id===`${b.id}:${b.publishedAt||'published'}`)).forEach(b=>out.push({id:`${b.id}:${b.publishedAt||'published'}`,type:'bulletin',date:b.publishedAt||b.updatedAt,title:'Nouveau bulletin publié',label:term(b.termId)?.name||'Bulletin officiel',detail:cls(b.classId)?.name||'',action:`printBulletin('${b.id}')`,bulletinId:b.id}))}if(role==='student'){(db.cloudItems||[]).forEach(x=>{if((x.shares||[]).some(g=>g.type==='student'&&g.id===sid))out.push({id:x.id,type:'cloud-share',date:x.createdAt,title:'Fichier partagé avec vous',label:x.name,detail:'Accéder à « Partagés avec moi »',action:"window.cloudSpace='shared';window.cloudPath=[];window.cloudSelected='"+x.id+"';go('studentDocuments')"})})}if(role==='teacher'){const tid=currentTeacherProfile()?.id||'teacher-local';(db.cloudItems||[]).forEach(x=>{if((x.shares||[]).some(g=>g.type==='teacher'&&g.id===tid))out.push({id:x.id,type:'cloud-share',date:x.createdAt,title:'Fichier partagé avec vous',label:x.name,detail:'Accéder à « Partagés avec moi »',action:"window.cloudSpace='shared';window.cloudPath=[];window.cloudSelected='"+x.id+"';go('documents')"})})}return out.filter(n=>!db.notifications.some(r=>r.read&&r.key===notificationReadKey(n))).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')))}
function activityReadKey(x){return `activity:${x.type}:${x.id||x.label||x.title}`}
