function scheduleDropConflict(s,date,timeValue,endValue,ignoreId){const d=new Date(date+'T12:00:00');return dayOcc(d).filter(x=>x.id!==ignoreId).some(x=>mins(timeValue)<mins(x.endTime||addHour(x.time))&&mins(endValue)>mins(x.time))}
function applyScheduleDrop(id,date,minutes,mode){const s=db.schedule.find(x=>x.id===id);if(!s)return;const oldStart=mins(s.time),oldEnd=mins(s.endTime||addHour(s.time)),dur=Math.max(15,oldEnd-oldStart),newEnd=Math.min(1200,minutes+dur),t=`${String(Math.floor(minutes/60)).padStart(2,'0')}:${String(minutes%60).padStart(2,'0')}`,et=`${String(Math.floor(newEnd/60)).padStart(2,'0')}:${String(newEnd%60).padStart(2,'0')}`;if(scheduleDropConflict(s,date,t,et,id))return toast('Impossible : ce déplacement crée un conflit.');const newDay=(new Date(date+'T12:00:00').getDay()+6)%7;if(mode==='all'){s.day=newDay;s.time=t;s.endTime=et}else{const ds=date;s.overrides??={};s.overrides[ds]={day:newDay,time:t,endTime:et}}save();render();toast(mode==='all'?'Créneau récurrent déplacé':'Séance déplacée pour cette date')}
function dropSchedule(ev,date){ev.preventDefault();const id=ev.dataTransfer.getData('text/plain'),s=db.schedule.find(x=>x.id===id);if(!s)return;const rect=ev.currentTarget.getBoundingClientRect();let minutes=360+Math.round(((ev.clientY-rect.top)/1.2)/15)*15;minutes=Math.max(360,Math.min(1200,minutes));if(s.recurrence==='once'){applyScheduleDrop(id,date,minutes,'all');return}openModal('Déplacer le cours',`<div class="notice"><b>${esc(s.subject||'Cours')}</b><br>Ce créneau est récurrent. Choisis si tu veux déplacer uniquement cette séance ou toute la récurrence.</div><div class="modalfoot"><button class="btn" onclick="closeModal();applyScheduleDrop('${id}','${date}',${minutes},'one')">Cette séance seulement</button><button class="btn primary" onclick="closeModal();applyScheduleDrop('${id}','${date}',${minutes},'all')">Toute la récurrence</button></div>`)}
function scheduleEditorFromOccurrence(sid,date=null){closeModal();openSchedule(sid,date)}
function scheduleMonth(d,occFn=dayOcc){let y=d.getFullYear(),m=d.getMonth(),first=new Date(y,m,1),days=new Date(y,m+1,0).getDate(),pad=(first.getDay()+6)%7;return `<div class="card"><div class="sectionhead"><div><h2 style="margin:0">${d.toLocaleDateString('fr-FR',{month:'long',year:'numeric'})}</h2><small class="muted">Vue mensuelle</small></div><div class="actions"><button class="btn" onclick="changeMonth(-1)">‹</button><button class="btn" onclick="changeMonth(1)">›</button><button class="btn" onclick="selectedWeek=startWeek(new Date());render()">Aujourd’hui</button></div></div><div class="miniCal monthCal" style="margin-top:14px">${['L','M','M','J','V','S','D'].map(x=>`<b style="text-align:center;font-size:10px;color:var(--muted)">${x}</b>`).join('')}${Array.from({length:pad},()=>'<span></span>').join('')}${Array.from({length:days},(_,i)=>{let x=new Date(y,m,i+1),oc=occFn(x);return `<button onclick="selectedWeek=new Date('${iso(x)}');scheduleView='day';render()" class="${iso(x)===iso(d)?'sel':''}"><b>${i+1}</b>${oc.length?`<small>${oc.length}</small>`:''}</button>`}).join('')}</div></div><div class="card" style="margin-top:12px"><div class="sectionhead"><h3>Créneaux du mois</h3></div><div class="section">${Array.from({length:days},(_,i)=>{let x=new Date(y,m,i+1),oc=occFn(x);return oc.length?`<div class="daywork"><b>${x.toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long'})}</b><span class="muted">${oc.length} cours</span></div>`:''}).join('')||'<div class="empty">Aucun cours ce mois.</div>'}</div></div>`}
function mins(t){let [h,m]=String(t||'00:00').split(':').map(Number);return h*60+m}function addHour(t){let n=mins(t)+60;return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`}
function miniCalendar(){const d=new Date(lessonDay+'T12:00:00');let first=new Date(d.getFullYear(),d.getMonth(),1),start=monday(first);let arr=[];for(let i=0;i<42;i++){let x=new Date(start);x.setDate(start.getDate()+i);arr.push(`<button class="${iso(x)===lessonDay?'sel':''}" onclick="lessonDay='${iso(x)}';selectedWeek=startWeek(new Date('${iso(x)}'));render()">${x.getDate()}</button>`)}return `<div class="monthNav"><button class="btn small" onclick="changeLessonMonth(-1)">‹</button><strong>${d.toLocaleDateString('fr-FR',{month:'long',year:'numeric'})}</strong><button class="btn small" onclick="changeLessonMonth(1)">›</button></div><div class="miniCal">${['L','M','M','J','V','S','D'].map(x=>`<b style="font-size:9px;text-align:center;color:#718096">${x}</b>`).join('')}${arr.map((_,i)=>{let x=new Date(start);x.setDate(start.getDate()+i);return `<button class="${iso(x)===lessonDay?'sel':''}" onclick="lessonDay='${iso(x)}';selectedWeek=startWeek(new Date('${iso(x)}'));render()">${x.getDate()}</button>`}).join('')}</div>`}
