function openSchedule(id=null,occurrenceDate=null){window.scheduleEditorOccurrenceDate=occurrenceDate||null;const s=id?db.schedule.find(x=>x.id===id):{day:0,time:'08:00',endTime:'09:00',classId:'',subject:'',room:'',group:'',recurrence:'weekly',startDate:iso(selectedWeek),endDate:'',exceptions:[]};const rec=s.recurrence||'weekly';openModal(id?'Modifier le créneau':'Ajouter un créneau',`<form onsubmit="saveSchedule(event,'${id||''}')"><div class="form"><div class="field"><label>Jour *</label><select class="select" name="day">${DAYS.map((x,i)=>`<option value="${i}" ${Number(s.day)===i?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Classe *</label><select class="select" name="classId" required><option value="">Choisir</option>${db.classes.map(c=>`<option value="${c.id}" ${s.classId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Professeur habituel</label><select class="select" name="teacherId"><option value="">Non précisé</option>${db.teachers.filter(t=>t.active!==false).map(t=>`<option value="${t.id}" ${String(s.teacherId||'')===String(t.id)?'selected':''}>${esc(teacherName(t))}</option>`).join('')}</select></div><div class="field"><label>Début *</label><input class="input" type="time" name="time" value="${esc(s.time)}" required></div><div class="field"><label>Fin</label><input class="input" type="time" name="endTime" value="${esc(s.endTime||'')}"></div><div class="field"><label>Matière *</label><input class="input" name="subject" value="${esc(s.subject)}" required></div><div class="field"><label>Sous-groupe (facultatif)</label><input class="input" name="group" value="${esc(s.group||'')}" placeholder="Groupe 1"></div><div class="field"><label>Salle</label><input class="input" name="room" value="${esc(s.room||'')}"></div><div class="field"><label>Récurrence *</label><select class="select" name="recurrence"><option value="weekly" ${rec==='weekly'?'selected':''}>Chaque semaine</option><option value="biweekly" ${rec==='biweekly'?'selected':''}>Toutes les 2 semaines</option><option value="triweekly" ${rec==='triweekly'?'selected':''}>Toutes les 3 semaines</option><option value="custom" ${rec==='custom'?'selected':''}>Toutes les N semaines</option><option value="once" ${rec==='once'?'selected':''}>Une seule fois</option></select></div><div class="field"><label>Intervalle (si N semaines)</label><input class="input" type="number" min="1" max="52" name="intervalWeeks" value="${esc(s.intervalWeeks||4)}"></div><div class="field"><label>À partir du</label><input class="input" type="date" name="startDate" value="${esc(s.startDate||iso(selectedWeek))}"></div><div class="field"><label>Jusqu'au</label><input class="input" type="date" name="endDate" value="${esc(s.endDate||'')}"></div><div class="field full"><label>Organisation annuelle</label><div class="notice">Ce créneau est un élément de l’emploi du temps récurrent. Tu peux modifier son jour, son horaire, sa matière, sa classe et sa période sans recréer les séances une par une.</div></div><div class="field full"><label>Dates exceptionnelles (optionnel)</label><input class="input" name="exceptions" value="${esc((s.exceptions||[]).join(', '))}" placeholder="2026-11-11, 2026-12-21"><div class="hint">Sépare les dates par des virgules pour supprimer ce cours ces jours-là.</div></div></div><div class="modalfoot">${id?`<button type="button" class="btn danger" onclick="deleteSchedule('${id}')">Supprimer</button><button type="button" class="btn" onclick="duplicateSchedule('${id}')">Dupliquer</button><button type="button" class="btn primary" onclick="openScheduleOccurrence('${id}',window.scheduleEditorOccurrenceDate||null)">Ouvrir la séance</button>`:''}<button type="button" class="btn" onclick="closeModal()">Annuler</button><button class="btn primary">Enregistrer</button></div></form>`)}
function scheduleOverlap(a,b){const aStart=mins(a.time),aEnd=mins(a.endTime||addHour(a.time)),bStart=mins(b.time),bEnd=mins(b.endTime||addHour(b.time));if(aStart>=bEnd||bStart>=aEnd)return false;return scheduleDatesOverlap(a,b)}
function scheduleDatesOverlap(a,b){const startA=new Date((a.startDate||'1900-01-01')+'T12:00:00'),startB=new Date((b.startDate||'1900-01-01')+'T12:00:00');const endA=new Date((a.endDate||'2999-12-31')+'T12:00:00'),endB=new Date((b.endDate||'2999-12-31')+'T12:00:00');if(startA>endB||startB>endA||Number(a.day)!==Number(b.day))return false;const lo=new Date(Math.max(startA,startB)),hi=new Date(Math.min(endA,endB));for(let d=new Date(lo);d<=hi;d.setDate(d.getDate()+1)){const ds=iso(d);if(d.getDay()!==Number(a.day)+1)continue;if((a.exceptions||[]).includes(ds)||(b.exceptions||[]).includes(ds))continue;if(recurring(a,d)&&recurring(b,d))return true}return false}
