function captureLessonDraft(){if(!$('#lessonContent'))return;lessonDraft={sid:lessonDraft?.sid,date:lessonDraft?.date,title:$('#lessonTitle')?.value||'',content:$('#lessonContent')?.innerHTML||'',makeWork:!!$('#makeWork')?.checked,workType:$('#workType')?.value||'normal',workTitle:$('#workTitle')?.value||'',workDue:$('#workDue')?.value||'',workDueTime:$('#workDueTime')?.value||'',workContent:$('#workContent')?.innerHTML||'',workSubmit:!!$('#workSubmit')?.checked,workEvalLink:!!$('#workEvalLink')?.checked,files:[...(lessonDraft?.files||[])],workFiles:[...(lessonDraft?.workFiles||[])]};}
function openOccurrence(sid,date){const o=db.schedule.find(x=>x.id===sid);if(!o)return;let l=lessonFor({...o,date})||{id:'',scheduleId:sid,date,classId:o.classId,subject:o.subject,files:[],homework:null};const pending=lessonDraft&&lessonDraft.sid===sid&&lessonDraft.date===date?lessonDraft:null;const hw=l.homework||{};const files=pending?.files||l.files||[];const workFiles=pending?.workFiles||hw.files||[];openModal(`${fmtDate(date)} · ${time(o.time)} · ${esc(o.subject)}`,`<div class="notice">Créneau : <b>${esc(cls(o.classId)?.name||'')}</b>${o.group?' · groupe '+esc(o.group):''} · ${esc(o.room||'')}${l.title?`<br><b>Séance :</b> ${esc(l.title)}`:''}${l.homework?`<br><b>Devoir lié :</b> ${esc(l.homework.title||'Travail à faire')} · à rendre le ${fmtDate(l.homework.due)}${l.homework.dueTime?' à '+time(l.homework.dueTime):''}`:''}</div><form onsubmit="saveLesson(event,'${l.id||''}','${sid}','${date}')"><div class="form" style="margin-top:12px"><div class="field full"><label>Titre de la séance</label><input id="lessonTitle" class="input" name="title" value="${esc(pending?.title??l.title??'')}"></div><div class="field full"><label>Ce qui a été fait</label>${richToolbar('lessonContent')}<div class="rich" id="lessonContent" contenteditable="true">${pending?.content??l.content??''}</div></div></div><div class="section"><div class="sectionhead"><h3>Fichiers du cours</h3><button type="button" class="btn small" onclick="captureLessonDraft();document.getElementById('lessonFile').click()">+ Fichier</button><input id="lessonFile" type="file" class="hide" multiple onchange="uploadLessonFiles('${sid}','${date}',this.files)"></div><div id="lessonFiles">${files.map((f,i)=>`<div class="file"><a href="${esc(f.url)}" target="_blank">${esc(f.name)}</a><button type="button" class="btn small danger" onclick="removeDraftFile('lesson',${i})">Supprimer</button></div>`).join('')||'<span class="muted">Aucun fichier.</span>'}</div></div><div class="section card" style="box-shadow:none;background:#fbfcfe"><div class="sectionhead"><h3>Travail à faire</h3><label class="check"><input id="makeWork" type="checkbox" ${(pending?.makeWork??!!l.homework)?'checked':''} onchange="toggleWorkForm(this.checked)"> Demander quelque chose</label></div><div id="workForm" class="${(pending?.makeWork??!!l.homework)?'':'hide'}"><div class="form"><div class="field"><label>Type</label><select class="select" id="workType"><option value="normal" ${(pending?.workType??hw.type)!=='evaluation'?'selected':''}>Travail à faire</option><option value="evaluation" ${(pending?.workType??hw.type)==='evaluation'?'selected':''}>Évaluation</option></select></div><div class="field full"><label>Titre du travail</label><input class="input" id="workTitle" value="${esc(pending?.workTitle??hw.title??'')}"></div><div class="field full"><label>À faire pour</label><div class="actions"><button type="button" class="btn" onclick="captureLessonDraft();openDuePicker('${sid}','${date}','${esc((pending?.workDue??hw.due)||'')}')">${(pending?.workDue??hw.due)?'Modifier le créneau · '+fmtDate(pending?.workDue??hw.due):'Choisir un créneau du planning'}</button><span id="workDueLabel" class="muted">${(pending?.workDue??hw.due)?esc(fmtDate(pending?.workDue??hw.due))+(pending?.workDueTime??hw.dueTime?' · '+time(pending?.workDueTime??hw.dueTime):''):'Aucune échéance sélectionnée'}</span></div><input id="workDue" type="hidden" value="${esc((pending?.workDue??hw.due)||'')}"><input id="workDueTime" type="hidden" value="${esc((pending?.workDueTime??hw.dueTime)||'')}"></div><div class="field full"><label>Consignes</label>${richToolbar('workContent')}<div class="rich" id="workContent" contenteditable="true">${pending?.workContent??hw.instructions??''}</div></div><div class="field full"><div class="sectionhead"><label>Pièces jointes du travail</label><button type="button" class="btn small" onclick="captureLessonDraft();document.getElementById('workFile').click()">+ Fichier</button><input id="workFile" type="file" class="hide" multiple onchange="uploadWorkFiles('${sid}','${date}',this.files)"></div><div id="workFiles">${workFiles.map((f,i)=>`<div class="file"><a href="${esc(f.url)}" target="_blank">${esc(f.name)}</a><button type="button" class="btn small danger" onclick="removeDraftFile('work',${i})">Supprimer</button></div>`).join('')||'<span class="muted">Aucune pièce jointe.</span>'}</div></div><div class="field"><label class="check"><input id="workSubmit" type="checkbox" ${(pending?.workSubmit??!!hw.requiresSubmission)?'checked':''}> Les élèves doivent rendre un fichier</label></div><div class="field"><label class="check"><input id="workEvalLink" type="checkbox" ${(pending?.workEvalLink??!!hw.linkedEvaluation)?'checked':''}> Relier automatiquement au module des notes</label></div>${hw.submissionFolder||pending?.workSubmit?'<div class="folderBox">📁 <b>Dossier virtuel de rendus</b><br><small class="muted">Les fichiers remis par les élèves seront regroupés dans ce dossier.</small></div>':''}</div></div></div><div class="modalfoot"><button type="button" class="btn primary" onclick="openAttendance(null,{classId:'${o.classId}',date:'${date}',slotId:'${sid}'})">Faire l’appel</button><button type="button" class="btn" onclick="scheduleEditorFromOccurrence('${sid}','${date}')">Modifier l’EDT</button><button type="button" class="btn" onclick="showSubmissions('${sid}','${date}')">Rendus</button><button type="button" class="btn" onclick="lessonDraft=null;closeModal()">Fermer</button><button class="btn primary">Enregistrer la séance</button></div></form>`);lessonDraft={sid,date,title:pending?.title??l.title??'',content:pending?.content??l.content??'',makeWork:pending?.makeWork??!!l.homework,workType:pending?.workType??hw.type??'normal',workTitle:pending?.workTitle??hw.title??'',workDue:pending?.workDue??hw.due??'',workDueTime:pending?.workDueTime??hw.dueTime??'',workContent:pending?.workContent??hw.instructions??'',workSubmit:pending?.workSubmit??!!hw.requiresSubmission,workEvalLink:pending?.workEvalLink??!!hw.linkedEvaluation,files,workFiles};}

function openDuePicker(sid,date,current){const source=db.schedule.find(x=>x.id===sid);if(!source)return;captureLessonDraft();let arr=[];for(let i=1;i<=120;i++){let d=new Date(date+'T12:00:00');d.setDate(d.getDate()+i);for(const o of dayOcc(d)){if(o.classId===source.classId&&o.subject===source.subject&&(!source.group||o.group===source.group))arr.push({...o,date:iso(d)});}}window.dueParent={sid,date};openModal('Choisir le créneau de rendu',`<div class="notice">Seuls les futurs créneaux correspondant à la même classe, matière${source.group?' et groupe':''} sont proposés.</div><div class="section">${arr.slice(0,60).map(x=>`<button type="button" class="daywork" style="width:100%;text-align:left;cursor:pointer" onclick="selectDueSlot('${x.date}','${x.time}')"><b>${fmtDate(x.date)} · ${time(x.time)}–${time(x.endTime||addHour(x.time))}</b><span class="muted">${esc(cls(x.classId)?.name||'')}${x.group?' · groupe '+esc(x.group):''}</span></button>`).join('')||'<div class="empty">Aucun créneau correspondant dans les 120 prochains jours.</div>'}</div><div class="modalfoot"><button class="btn" type="button" onclick="openOccurrence('${sid}','${date}')">Annuler</button></div>`)}
function selectDueSlot(d,t){const p=window.dueParent;if(!p)return;if(!lessonDraft)lessonDraft={sid:p.sid,date:p.date};lessonDraft.workDue=d;lessonDraft.workDueTime=t;lessonDraft.makeWork=true;closeModal();openOccurrence(p.sid,p.date)}

