function ensureLinkedEvaluation(l,o){if(!l.homework?.linkedEvaluation)return null;let eid=typeof l.homework.linkedEvaluation==='object'?l.homework.linkedEvaluation.id:l.homework.linkedEvaluation;let ev=eid?db.evaluations.find(x=>x.id===eid):null;if(!ev){ev={id:uid(),classId:o.classId,group:o.group||'',subject:o.subject||'',title:l.homework.title||'Évaluation',date:l.homework.due||l.date,coefficient:1,grades:[]};ev.grades=targetStudents(ev).map(s=>({studentId:s.id,value:'',comment:''}));db.evaluations.push(ev)}else{ev.classId=o.classId;ev.group=o.group||ev.group||'';ev.subject=o.subject||ev.subject;ev.title=l.homework.title||ev.title;ev.date=l.homework.due||ev.date}l.homework.linkedEvaluation={id:ev.id};ev.linkedLessonId=l.id;return ev}
function saveLesson(e,id,sid,date){e.preventDefault();captureLessonDraft();const o=Object.fromEntries(new FormData(e.target)),slot=db.schedule.find(x=>x.id===sid);let l=id?db.lessons.find(x=>x.id===id):{id:uid(),scheduleId:sid,date,classId:slot.classId,subject:slot.subject,files:[],homework:null};o.content=lessonDraft?.content||'';Object.assign(l,o,{scheduleId:sid,date,files:lessonDraft?.files||l.files||[]});if($('#makeWork')?.checked){const due=$('#workDue')?.value||lessonDraft?.workDue||'';const dueTime=$('#workDueTime')?.value||lessonDraft?.workDueTime||'';if(!due||!dueTime)return toast('Choisis un créneau du planning pour l’échéance.');l.homework={title:$('#workTitle')?.value||lessonDraft?.workTitle||'',type:$('#workType')?.value||lessonDraft?.workType||'normal',due,dueTime,instructions:$('#workContent')?.innerHTML||lessonDraft?.workContent||'',files:lessonDraft?.workFiles||l.homework?.files||[],requiresSubmission:!!$('#workSubmit')?.checked,linkedEvaluation:($('#workEvalLink')?.checked||$('#workType')?.value==='evaluation')?(l.homework?.linkedEvaluation||true):false};if(l.homework.requiresSubmission&&!l.homework.submissionFolder)l.homework.submissionFolder={id:uid(),name:'Rendus — '+(l.homework.title||'Travail'),createdAt:new Date().toISOString()};if(!l.homework.requiresSubmission)l.homework.submissionFolder=null;ensureLinkedEvaluation(l,slot)}else l.homework=null;if(!id)db.lessons.push(l);auditEvent(id?'Séance modifiée':'Séance créée',`${l.subject||slot.subject||''} · ${fmtDate(date)}`);lessonDraft=null;save();closeModal();render();toast('Séance enregistrée')}
function refreshDraftFileList(kind){const list=kind==='lesson'?lessonDraft?.files||[]:lessonDraft?.workFiles||[];const el=$(kind==='lesson'?'#lessonFiles':'#workFiles');if(el)el.innerHTML=list.map((f,i)=>`<div class="file"><a href="${esc(f.url)}" target="_blank">${esc(f.name)}</a><button type="button" class="btn small danger" onclick="removeDraftFile('${kind}',${i})">Supprimer</button></div>`).join('')||'<span class="muted">Aucun fichier.</span>'}
async function uploadWorkFiles(sid,date,files){captureLessonDraft();lessonDraft??={sid,date,files:[],workFiles:[]};lessonDraft.workFiles??=[];for(const file of [...files]){try{const x=await upload(file,'submissions/'+sid);lessonDraft.workFiles.push(x);refreshDraftFileList('work');toast('Pièce jointe ajoutée')}catch(e){toast('Échec du téléversement')}}}
