function fileHtml(f){return `<div class="file"><a href="${esc(f.url)}" target="_blank">${esc(f.name)}</a><span class="muted">${Math.ceil((f.size||0)/1024)} Ko</span></div>`}
async function upload(file,folder='general'){const r=await fetch('/api/upload',{method:'POST',headers:{'X-Filename':file.name,'X-Upload-Folder':folder},body:file});if(!r.ok)throw new Error('Téléversement impossible');return {...await r.json(),size:file.size}}

