function openSubmissionCorrection(subId){const sub=db.submissions.find(x=>x.id===subId),s=sub&&student(sub.studentId),l=sub&&db.lessons.find(x=>x.id===sub.lessonId);if(!sub||!s||!l)return;openModal(`Correction — ${esc(s.first+' '+s.last)}`,`<div class="notice"><b>${esc(l.homework?.title||'Travail')}</b> · ${esc(l.subject||'')}</div><div class="section"><h3>Fichiers reçus</h3>${submissionFiles(sub).map(f=>`<div class="file"><a href="${esc(f.url)}" target="_blank" rel="noopener">${esc(f.name)}</a><a class="btn small" href="${esc(f.url)}" download>↓</a></div>`).join('')||'<div class="empty">Aucun fichier.</div>'}</div><form onsubmit="saveSubmissionCorrection(event,'${sub.id}')"><div class="field full"><label>Retour à l’élève</label>${richToolbar('correctionEditor')}<div id="correctionEditor" class="rich" contenteditable="true" data-placeholder="Écrire le retour à l’élève…">${sub.correctionComment||''}</div></div><div class="field full"><label>Fichiers de correction</label><button type="button" class="btn mailBrowse" onclick="document.getElementById('correctionFilePicker').click()">📎 Ajouter des fichiers</button><input id="correctionFilePicker" style="display:none" type="file" multiple onchange="uploadCorrectionFiles('${sub.id}',this.files);this.value=''"><div id="correctionFiles">${(sub.correctionFiles||[]).map((f,i)=>`<div class="file"><a href="${esc(f.url)}" target="_blank">${esc(f.name)}</a><button type="button" class="btn small danger" onclick="removeCorrectionFile('${sub.id}',${i})">Supprimer</button></div>`).join('')||'<span class="muted">Aucun fichier.</span>'}</div></div><div class="modalfoot"><button type="button" class="btn" onclick="closeModal()">Fermer</button><button class="btn primary">Enregistrer la correction</button></div></form>`);}
async function uploadCorrectionFiles(subId,files){const sub=db.submissions.find(x=>x.id===subId);if(!sub)return;const editor=document.getElementById('correctionEditor');if(editor)sub.correctionComment=editor.innerHTML||sub.correctionComment||'';sub.correctionFiles??=[];for(const f of [...files]){try{sub.correctionFiles.push(await upload(f,'corrections/'+subId))}catch(e){toast('Échec du téléversement')}}save();openSubmissionCorrection(subId)}
async function removeCorrectionFile(subId,index){const sub=db.submissions.find(x=>x.id===subId),f=sub?.correctionFiles?.[index];if(!f)return;const editor=document.getElementById('correctionEditor');if(editor)sub.correctionComment=editor.innerHTML||sub.correctionComment||'';sub.correctionFiles.splice(index,1);await deleteUploadedFile(f);save();openSubmissionCorrection(subId)}
function saveSubmissionCorrection(e,id){e.preventDefault();const sub=db.submissions.find(x=>x.id===id);if(!sub)return;const editor=e.target.querySelector('#correctionEditor');sub.correctionComment=editor?.innerHTML||'';sub.corrected=true;sub.correctedAt=new Date().toISOString();save();closeModal();toast('Correction enregistrée');const l=db.lessons.find(x=>x.id===sub.lessonId);if(l)openWorkTracking(l.id)}
function showSubmissions(sid,date){const o=db.schedule.find(x=>x.id===sid),l=lessonFor({...o,date});if(!l?.homework?.requiresSubmission)return openModal('Rendus',`<div class="empty">Ce travail ne demande pas de rendu de fichier.</div>`);const ss=[...new Map(db.students.filter(s=>s.classId===o.classId&&(!o.group||s.group===o.group)).map(s=>[s.id,s])).values()].sort((a,b)=>String(a.last||'').localeCompare(String(b.last||''),'fr',{sensitivity:'base'})||String(a.first||'').localeCompare(String(b.first||''),'fr',{sensitivity:'base'}));const rows=ss.map(s=>{const sub=db.submissions.find(x=>x.lessonId===l.id&&x.studentId===s.id&&x.status!=='draft');if(!sub)return `<div class="submissionFile"><div class="submissionMeta"><b>${esc(s.last.toUpperCase())} ${esc(s.first)}</b><small class="muted">Aucun fichier rendu</small></div><div class="submissionActions"><span class="pill orange">Non rendu</span></div></div>`;return `<div class="submissionFile"><div class="submissionMeta"><b>${esc(s.last.toUpperCase())} ${esc(s.first)}</b><small class="muted">${submissionFiles(sub).length} fichier(s) · ${sub.submittedAt?new Date(sub.submittedAt).toLocaleString('fr-FR'):''}</small></div><div class="submissionActions"><button class="btn small mailBrowse" onclick="openSubmissionCorrection('${sub.id}')">Parcourir / corriger</button></div></div>`}).join('');openModal('Rendus des élèves',`<div class="notice"><b>${esc(l.homework.title||'Travail')}</b><br><span class="muted">${ss.length} élève(s) concerné(s), classés par ordre alphabétique.</span></div><div class="section">${rows||'<div class="empty">Aucun élève concerné.</div>'}</div><div class="modalfoot"><button class="btn" onclick="openOccurrence('${sid}','${date}')">Retour au travail</button></div>`)}
function lessons(){const cf=window.classContext||'';let d=new Date(lessonDay+'T12:00:00'),ds=weekDates(d),occ=dayOcc(d).filter(o=>!cf||o.classId===cf),workCount=db.lessons.filter(l=>l.homework?.due===lessonDay&&(!cf||l.classId===cf)&&(!window.classGroupContext||l.group===window.classGroupContext)).length;return shell('Cahier de cours','Leçons & séances','Prépare les séances, ajoute le contenu du cours et gère les travaux à rendre.',`<div class="lessonTopBar"><div class="lessonModeSwitch"><button class="lessonMode lessonModeGreen ${lessonTab==='done'?'active':''}" onclick="lessonTab='done';render()">Contenu de séance</button><button class="lessonMode lessonModeBlue ${lessonTab==='work'?'active':''}" onclick="lessonTab='work';render()">Devoir à la maison <span class="lessonCountBlue">${workCount}</span></button><button class="lessonMode lessonModeNeutral ${lessonTab==='upcoming'?'active':''}" onclick="lessonTab='upcoming';render()">À faire</button></div></div>`)+`<div class="lessonWorkspace"><aside class="card lessonCalendar"><div class="sectionhead"><div><b>Calendrier</b></div></div>${miniCalendar()}</aside><section class="card lessonMain"><div class="sectionhead"><div><h2 style="text-transform:capitalize">${d.toLocaleDateString('fr-FR',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</h2><small class="muted">${occ.length} créneau(x) prévu(s)</small></div></div>${lessonTab==='done'?lessonDayList(occ):lessonTab==='work'?lessonWorkList():lessonUpcomingList(d)}</section><aside class="card lessonWeek"><div class="sectionhead"><div><b>Semaine</b><small class="muted" style="display:block">Navigation rapide</small></div></div><div class="verticalDays">${ds.map(x=>{let q=dayOcc(x),w=db.lessons.filter(l=>l.homework?.due===iso(x)).length;return `<button class="dayBtn ${iso(x)===lessonDay?'active':''}" onclick="lessonDay='${iso(x)}';selectedWeek=startWeek(new Date('${iso(x)}'));render()"><span>${x.toLocaleDateString('fr-FR',{weekday:'long',day:'numeric'})}</span><span class="count">${lessonTab==='work'?w:q.length}</span></button>`}).join('')}</div></aside></div>`}
function lessonDayList(occ){return occ.map(o=>{let l=lessonFor({...o,date:lessonDay});const preview=l?.content?String(l.content).replace(/<[^>]*>/g,' ').replace(/\s+/g,' ').trim().slice(0,180):'';const title=l?.title||'';return `<div class="lessonEntry" onclick="openOccurrence('${o.id}','${lessonDay}')"><div class="lessonEntryHead"><div><b>${time(o.time)} · ${esc(o.subject)}</b>${title?`<div style="margin-top:4px;font-weight:700">${esc(title)}</div>`:''}<div class="lessonEntryMeta"><span class="pill blue">${esc(cls(o.classId)?.name||'')}</span>${o.group?`<span class="pill">Groupe ${esc(o.group)}</span>`:''}${l?.content?'<span class="pill green">Contenu renseigné</span>':'<span class="pill orange">Contenu à renseigner</span>'}${l?.homework?'<span class="pill blue">Devoir lié</span>':''}</div>${preview?`<div class="muted" style="margin-top:7px;line-height:1.45">${esc(preview)}${preview.length>=180?'…':''}</div>`:''}${l?.homework?`<div class="lessonHomeworkHint"><b>${esc(l.homework.title||'Travail à faire')}</b> <span class="muted">· à rendre le ${fmtDate(l.homework.due)}${l.homework.dueTime?' à '+time(l.homework.dueTime):''}</span></div>`:''}</div><span class="muted">${esc(o.room||'')}</span></div></div>`}).join('')||'<div class="empty">Aucune séance prévue ce jour.</div>'}
function lessonWorkList(){const due=lessonDay,cf=window.classContext||'';const items=db.lessons.filter(l=>l.homework?.due===due&&(!cf||l.classId===cf)&&(!window.classGroupContext||l.group===window.classGroupContext)).map(l=>{const o=db.schedule.find(x=>x.id===l.scheduleId);return o?{l,o}:null}).filter(Boolean);return items.map(({l,o})=>`<div class="message ${l.homework?.type==='evaluation'?'workRed':''}" style="cursor:pointer" onclick="openOccurrence('${l.scheduleId}','${l.date}')"><b>${esc(l.homework.title||'Travail')}</b><small>${esc(l.subject)} · ${esc(cls(l.classId)?.name||'')} · donné le ${fmtDate(l.date)} · à rendre aujourd’hui${l.homework.dueTime?' à '+time(l.homework.dueTime):''}</small></div>`).join('')||'<div class="empty">Aucun travail à rendre ce jour.</div>'}
function lessonUpcomingList(d){let a=[];for(let i=0;i<21;i++){let x=new Date(d);x.setDate(x.getDate()+i);for(const o of dayOcc(x).filter(q=>(!window.classContext||q.classId===window.classContext)&&(!window.classGroupContext||q.group===window.classGroupContext))){let l=lessonFor({...o,date:iso(x)});if(l?.homework)a.push({x,l,o})}}return a.map(z=>`<div class="message ${z.l.homework?.type==='evaluation'?'workRed':''}"><b>${z.x.toLocaleDateString('fr-FR',{weekday:'short',day:'numeric',month:'short'})} · ${time(z.o.time)} · ${esc(z.l.homework.title||'Travail')}</b><small>${esc(z.l.subject)} · échéance ${fmtDate(z.l.homework.due)}${z.l.homework.dueTime?' à '+time(z.l.homework.dueTime):''}</small></div>`).join('')||'<div class="empty">Aucun travail à faire sur les trois prochaines semaines.</div>'}
function currentTeacherProfile(){return db.teachers.find(t=>t.id===authUser?.teacherId)||db.teachers.find(t=>t.id==='teacher-local')||db.teachers[0]}
function ppClassStats(c){const ss=db.students.filter(s=>s.classId===c.id),ids=ss.map(s=>s.id),avg=weightedAverageForEvaluations(db.evaluations.filter(e=>e.classId===c.id),ids);const rows=db.attendance.flatMap(a=>(a.rows||[]).filter(r=>ids.includes(r.studentId)).map(r=>({...r,date:a.date})));const abs=rows.filter(r=>r.status==='absent').length,late=rows.filter(r=>r.status==='retard').length;const missing=v103MissingWorkList().filter(x=>x.student&&ids.includes(x.student.id)).length;return {students:ss.length,avg,abs,late,missing}}
function openPPDashboard(classId){
 const c=cls(classId),tid=currentTeacherProfile()?.id||'teacher-local';
 if(!c||c.principalTeacherId!==tid)return toast('Cette classe ne vous est pas attribuée comme PP.');
 window.classContext=c.id;window.classGroupContext='';
 page='ppDashboard';appSpace='teacher';render();
}
function ppDashboard(){
 const c=cls(window.classContext),tid=currentTeacherProfile()?.id||'teacher-local';
 if(!c||c.principalTeacherId!==tid)return classes();
 const st=db.students.filter(x=>x.classId===c.id).sort((a,b)=>String(a.last||'').localeCompare(String(b.last||''),'fr',{sensitivity:'base'})||String(a.first||'').localeCompare(String(b.first||''),'fr',{sensitivity:'base'}));
 const stats=ppClassStats(c),groups=c.groups||[...new Set(st.map(x=>x.group).filter(Boolean))];
 const recentE=db.evaluations.filter(e=>e.classId===c.id).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).slice(0,5);
 const recentA=db.attendance.filter(a=>a.classId===c.id).sort((a,b)=>String(b.date||'').localeCompare(String(a.date||''))).slice(0,5);
 const missing=v103MissingWorkList().filter(x=>x.student&&st.some(s=>s.id===x.student.id));
 const low=st.filter(s=>{const v=Number(v101StudentAverage(s.id));return Number.isFinite(v)&&v<10;});
 const bulletins=db.bulletins.filter(b=>b.classId===c.id);
 const notReady=st.filter(s=>{const b=bulletins.find(x=>x.studentId===s.id);return !b||!b.validated;});
 const alerts=[];
 if(low.length)alerts.push(`<div class="ppAlert"><i class="ppAlertDot red"></i><div><b>${low.length} élève(s) sous 10/20</b><small>À surveiller dans les résultats de la classe.</small></div><button class="btn small" onclick="goClassModule('students','${c.id}')">Voir</button></div>`);
 if(missing.length)alerts.push(`<div class="ppAlert"><i class="ppAlertDot orange"></i><div><b>${missing.length} travail(aux) non rendu(s)</b><small>Suivi issu des devoirs déjà enregistrés.</small></div><button class="btn small" onclick="goClassModule('lessons','${c.id}')">Voir</button></div>`);
 if(notReady.length)alerts.push(`<div class="ppAlert"><i class="ppAlertDot blue"></i><div><b>${notReady.length} bulletin(s) à vérifier</b><small>Les bulletins non validés restent hors publication officielle.</small></div><button class="btn small" onclick="goClassModule('bulletins','${c.id}')">Vérifier</button></div>`);
 if(!alerts.length)alerts.push(`<div class="empty" style="padding:20px">Aucun point d’attention détecté à partir des données disponibles.</div>`);
 const studentRows=st.slice(0,30).map(s=>{const avg=Number(v101StudentAverage(s.id)),abs=db.attendance.flatMap(a=>a.rows||[]).filter(r=>r.studentId===s.id&&r.status==='absent').length,late=db.attendance.flatMap(a=>a.rows||[]).filter(r=>r.studentId===s.id&&r.status==='retard').length,miss=missing.filter(x=>x.student?.id===s.id).length;const risk=(!Number.isFinite(avg)||avg<10||abs>=3||miss>=2)?'red':(avg<12||abs>0||miss>0)?'orange':'';return `<tr><td class="ppStudentName"><b>${esc(s.last?.toUpperCase()||'')} ${esc(s.first||'')}</b><small>${esc(s.group||'Classe entière')}</small></td><td>${Number.isFinite(avg)?avg.toFixed(2):'—'} /20</td><td>${abs}</td><td>${late}</td><td>${miss}</td><td><span class="ppRisk ${risk}">${risk==='red'?'À surveiller':risk==='orange'?'À suivre':'RAS'}</span></td></tr>`}).join('');
 return shell('Professeur principal',`Classe ${esc(c.name)}`,`${esc(c.level||'Niveau non renseigné')} · ${stats.students} élève(s)`, `<button class="btn" onclick="go('classes')">Mes classes</button><button class="btn primary" onclick="goClassModule('students','${c.id}')">Élèves</button>`) +
 `<section class="card ppDashboardHero"><div class="ppHeroIdentity"><div class="ppHeroMark">PP</div><div><h2>Pilotage de ${esc(c.name)}</h2><p>Vue transversale de la classe · professeur principal : ${esc(teacherName(currentTeacherProfile()||{}))}</p></div></div><div class="actions"><button class="btn small" onclick="openClass('${c.id}')">Paramètres de la classe</button></div><div class="ppKpis" style="grid-column:1/-1"><div class="ppKpi"><small>Élèves</small><b>${stats.students}</b><span>effectif actuel</span></div><div class="ppKpi"><small>Moyenne</small><b>${stats.avg} /20</b><span>évaluations disponibles</span></div><div class="ppKpi"><small>Absences</small><b>${stats.abs}</b><span>enregistrées</span></div><div class="ppKpi"><small>Retards</small><b>${stats.late}</b><span>enregistrés</span></div><div class="ppKpi"><small>Non rendus</small><b>${stats.missing}</b><span>travaux signalés</span></div></div></section>
 <section class="card section"><div class="ppSectionTitle"><div><h2>Accès rapides</h2><p>Les outils utiles au suivi quotidien de la classe.</p></div></div><div class="ppQuickGrid"><button class="card ppQuick" onclick="goClassModule('students','${c.id}')"><span class="ppQuickIcon">♙</span><span><b>Élèves</b><small>Profils et suivi individuel</small></span></button><button class="card ppQuick" onclick="goClassModule('attendance','${c.id}')"><span class="ppQuickIcon">☑</span><span><b>Assiduité</b><small>Absences et retards</small></span></button><button class="card ppQuick" onclick="goClassModule('evaluations','${c.id}')"><span class="ppQuickIcon">✓</span><span><b>Résultats</b><small>Évaluations et moyennes</small></span></button><button class="card ppQuick" onclick="goClassModule('bulletins','${c.id}')"><span class="ppQuickIcon">▥</span><span><b>Bulletins</b><small>Préparer et publier</small></span></button><button class="card ppQuick" onclick="goClassModule('lessons','${c.id}')"><span class="ppQuickIcon">▤</span><span><b>Travaux</b><small>Devoirs et rendus</small></span></button><button class="card ppQuick" onclick="goClassModule('messages','${c.id}')"><span class="ppQuickIcon">✉</span><span><b>Messagerie</b><small>Échanges liés à la classe</small></span></button><button class="card ppQuick" onclick="goClassModule('documents','${c.id}')"><span class="ppQuickIcon">☁</span><span><b>Documents</b><small>Ressources de la classe</small></span></button><button class="card ppQuick" onclick="goClassModule('schedule','${c.id}')"><span class="ppQuickIcon">▦</span><span><b>Emploi du temps</b><small>Créneaux de la classe</small></span></button></div>${groups.length?`<div class="section"><div class="sectionhead"><h3>Groupes</h3></div><div class="groupPills">${groups.map(g=>`<button class="pill purple" style="cursor:pointer" onclick="goClassModule('students','${c.id}','${String(g).replace(/'/g,"\\'")}')">${esc(g)}</button>`).join('')}</div></div>`:''}</section>
 <div class="grid g2 section"><section class="card"><div class="ppSectionTitle"><div><h2>Points d’attention</h2><p>Signaux calculés à partir des données existantes.</p></div></div><div class="ppAlerts">${alerts.join('')}</div></section><section class="card"><div class="ppSectionTitle"><div><h2>Dernières données</h2><p>Activité récente de la classe.</p></div></div>${recentE.map(e=>`<div class="message"><b>${esc(e.title)}</b><small>${esc(e.subject||'')} · ${fmtDate(e.date)} · ${evalAverage(e)} /20</small></div>`).join('')}${recentA.map(a=>`<div class="message"><b>Appel · ${fmtDate(a.date)}</b><small>${attendanceSlotLabel(a)} · ${a.rows.filter(r=>r.status==='absent').length} absence(s)</small></div>`).join('')||(!recentE.length?'<div class="empty">Aucune donnée récente.</div>':'')}</section></div>
 <section class="card section"><div class="ppSectionTitle"><div><h2>Suivi des élèves</h2><p>Vue synthétique pour repérer rapidement les situations à suivre.</p></div><button class="btn small" onclick="goClassModule('students','${c.id}')">Ouvrir les élèves</button></div><div class="tablewrap"><table class="table ppStudentTable"><thead><tr><th>Élève</th><th>Moyenne</th><th>Abs.</th><th>Ret.</th><th>Non rendus</th><th>Suivi</th></tr></thead><tbody>${studentRows||'<tr><td colspan="6"><div class="empty">Aucun élève.</div></td></tr>'}</tbody></table></div>${st.length>30?`<div class="hint" style="margin-top:8px">30 élèves affichés ici. Ouvrez le module Élèves pour la liste complète.</div>`:''}</section>`;
}

function classes(){const tid=currentTeacherProfile()?.id||'teacher-local',pp=db.classes.filter(c=>c.principalTeacherId===tid),mine=pp.length;return shell('Structure','Classes','Gérez les classes et pilotez celles dont vous êtes professeur principal.',`<button class="btn primary" onclick="openClass()">+ Nouvelle classe</button>`)+`<div class="card section"><div class="sectionhead"><div><h2>Mes classes principales</h2><div class="muted">Le PP dispose ici d’un espace de pilotage transversal : élèves, résultats, absences, travaux et communication.</div></div><span class="pill ${mine?'green':'orange'}">${mine}</span></div>${pp.map(c=>{const z=ppClassStats(c);return `<div class="ppClassCard"><div class="sectionhead"><div><h3>${esc(c.name)}</h3><small class="muted">${esc(c.level||'Niveau non renseigné')} · ${z.students} élève(s)</small><small class="muted" style="display:block;margin-top:4px">Enseignants : ${classTeachers(c).map(t=>esc(teacherName(t))).join(' · ')||'Aucun renseigné'}</small></div><span class="pill green">PP</span></div><div class="miniKpis"><div class="miniKpi"><small>Moyenne</small><b>${z.avg}</b></div><div class="miniKpi"><small>Absences</small><b>${z.abs}</b></div><div class="miniKpi"><small>Retards</small><b>${z.late}</b></div><div class="miniKpi"><small>Non rendus</small><b>${z.missing}</b></div></div><div class="actions"><button class="btn primary small" onclick="openPPDashboard('${c.id}')">Piloter la classe</button><button class="btn small" onclick="openClass('${c.id}')">Paramètres</button></div></div>`}).join('')||'<div class="empty">Aucune classe ne vous est encore attribuée comme PP.</div>'}</div><div class="grid g3">${db.classes.map(c=>{const n=db.students.filter(s=>s.classId===c.id).length,slots=db.schedule.filter(x=>x.classId===c.id).length,evals=db.evaluations.filter(x=>x.classId===c.id).length;return `<div class="card"><div class="sectionhead"><div><h2>${esc(c.name)}</h2><div class="muted">${esc(c.level||'Niveau non renseigné')}${c.group?' · '+esc(c.group):''}${c.doubleLevel?' · Double niveau':''}</div><div class="muted" style="margin-top:5px">PP : ${esc(teacherName(db.teachers.find(t=>t.id===c.principalTeacherId)||{}))}</div>${c.groups?.length?`<div class="groupPills">${c.groups.map(g=>`<span class="pill purple">${esc(g)}</span>`).join('')}</div>`:''}</div><span class="pill blue">${n} élève(s)</span></div><div class="gradeStats section"><div class="metric"><small>Appel</small><b>${c.attendanceMode==='hour'?'Chaque cours':'Demi-journée'}</b></div><div class="metric"><small>EDT</small><b>${slots}</b></div><div class="metric"><small>Évals</small><b>${evals}</b></div></div><div class="actions"><button class="btn small" onclick="openClass('${c.id}')">Modifier</button><button class="btn small" onclick="manageClassGroups('${c.id}')">Groupes</button><button class="btn small" onclick="go('students');setTimeout(()=>{const x=$('#studentClass');if(x){x.value='${c.id}';filterStudents()}},0)">Élèves</button></div></div>`}).join('')||'<div class="card"><div class="empty">Aucune classe. Créez votre première classe.</div></div>'}</div>`}
function splitPersonName(name){const parts=String(name||'').trim().split(/\s+/).filter(Boolean);if(!parts.length)return {first:'',last:''};if(parts.length===1)return {first:parts[0],last:''};return {first:parts.slice(0,-1).join(' '),last:parts.at(-1)}}
function syncTeacherClassLinks(){(db.teachers||[]).forEach(t=>{t.classIds=db.classes.filter(c=>(c.teacherIds||[]).includes(t.id)).map(c=>c.id)})}
function openClass(id=null){const current=currentTeacherProfile()?.id||'teacher-local';const c=id?cls(id):{id:'',name:'',level:'',group:'',attendanceMode:'hour',periodMode:db.settings.termMode,doubleLevel:false,levels:[],groups:[],principalTeacherId:authUser?.role==='teacher'?current:'',teacherIds:authUser?.role==='teacher'?[current]:[]};if(id&&!c)return;const levels=Array.isArray(c.levels)?c.levels:[];const groups=Array.isArray(c.groups)?c.groups:[];const teacherIds=Array.isArray(c.teacherIds)?c.teacherIds:[];openModal(id?'Modifier la classe':'Nouvelle classe',`<form onsubmit="saveClass(event,'${id||''}')"><div class="form"><div class="field"><label>Nom de la classe *</label><input class="input" name="name" value="${esc(c.name)}" placeholder="CMA" required></div><div class="field"><label>Niveau</label><input class="input" name="level" value="${esc(c.level||'')}" placeholder="CM1 ou CM1/CM2"></div><div class="field"><label>Groupe principal</label><input class="input" name="group" value="${esc(c.group||'')}" placeholder="Facultatif"></div><div class="field"><label>Appel</label><select class="select" name="attendanceMode"><option value="hour" ${c.attendanceMode==='hour'?'selected':''}>À chaque cours</option><option value="halfday" ${c.attendanceMode!=='hour'?'selected':''}>Par demi-journée</option></select></div><div class="field"><label>Professeur principal</label><select class="select" name="principalTeacherId"><option value="">Aucun</option>${db.teachers.map(t=>`<option value="${t.id}" ${c.principalTeacherId===t.id?'selected':''}>${esc(teacherName(t))}</option>`).join('')}</select></div><div class="field"><label>Organisation des périodes</label><select class="select" name="periodMode"><option value="trimestres" ${c.periodMode==='trimestres'?'selected':''}>Trimestres</option><option value="semestres" ${c.periodMode==='semestres'?'selected':''}>Semestres</option></select></div><div class="field full"><label>Enseignants de la classe</label><div class="hint">Les enseignants sélectionnés sont rattachés à la classe et deviennent disponibles dans les modules qui utilisent cette relation.</div><div class="recipientGrid">${db.teachers.map(t=>`<label class="recipientCheck"><input type="checkbox" name="teacherIds" value="${t.id}" ${teacherIds.includes(t.id)?'checked':''}> ${esc(teacherName(t))}</label>`).join('')||'<span class="muted">Aucun profil professeur.</span>'}</div></div><div class="field full"><label class="check"><input type="checkbox" name="doubleLevel" ${c.doubleLevel?'checked':''} onchange="toggleDoubleLevelFields(this.checked)"> Classe à double niveau</label><div class="hint">Ex. CMA en CM1/CM2 : les groupes de niveau pourront être créés automatiquement.</div></div><div class="field full" id="doubleLevelFields" style="display:${c.doubleLevel?'block':'none'}"><label>Niveaux de la classe</label><div class="hint">Sépare les niveaux par « / » dans le champ Niveau, par exemple <b>CM1/CM2</b>.</div><div class="notice" style="margin-top:8px">${levels.length?`Niveaux détectés : ${levels.map(x=>esc(x)).join(' · ')}`:'Les groupes seront proposés automatiquement à l’enregistrement.'}</div></div><div class="field full"><div class="notice">Ces paramètres sont enregistrés dans la sauvegarde de la classe et sont réutilisés par les élèves, l’EDT, les évaluations, les appels, les périodes et les groupes.</div></div></div><div class="modalfoot">${id?`<button type="button" class="btn danger" onclick="deleteClass('${id}')">Supprimer</button>`:''}<button type="button" class="btn" onclick="closeModal()">Annuler</button><button class="btn primary">Enregistrer</button></div></form>`)}
function toggleDoubleLevelFields(on){const x=$('#doubleLevelFields');if(x)x.style.display=on?'block':'none'}
function reconcileStudentGroupsForClass(oldClass,newClass,students){if(!oldClass||!newClass)return;const valid=new Set(newClass.groups||[]),oldPrefix=String(oldClass.name||'')+'/';for(const s of students){if(s.classId!==oldClass.id||!s.group)continue;if(oldClass.doubleLevel){const level=String(s.group).startsWith(oldPrefix)?String(s.group).slice(oldPrefix.length):'';s.group=(newClass.doubleLevel&&level&&(newClass.levels||[]).includes(level))?`${newClass.name}/${level}`:(valid.has(s.group)?s.group:'')}else if(!valid.has(s.group))s.group=''}}
function saveClass(e,id){e.preventDefault();const o=Object.fromEntries(new FormData(e.target));o.name=o.name.trim();if(!o.name)return toast('Le nom de la classe est obligatoire.');const duplicate=db.classes.find(c=>c.id!==id&&c.name.trim().toLowerCase()===o.name.toLowerCase());if(duplicate)return toast('Cette classe existe déjà.');const oldClass=id?{...cls(id),groups:[...(cls(id)?.groups||[])],levels:[...(cls(id)?.levels||[])]}:null;o.doubleLevel=!!e.target.doubleLevel?.checked;o.level=String(o.level||'').trim();o.levels=o.doubleLevel?o.level.split('/').map(x=>x.trim()).filter(Boolean):[];if(o.doubleLevel&&o.levels.length<2)return toast('Indique au moins deux niveaux, par exemple CM1/CM2.');o.groups=o.doubleLevel?o.levels.map(level=>`${o.name}/${level}`):(id&&!oldClass?.doubleLevel?(oldClass?.groups||[]):[]);o.teacherIds=[...e.target.querySelectorAll('input[name="teacherIds"]:checked')].map(x=>x.value);o.principalTeacherId=String(o.principalTeacherId||'');if(o.principalTeacherId&&!o.teacherIds.includes(o.principalTeacherId))o.teacherIds.push(o.principalTeacherId);if(authUser?.role==='teacher'&&!o.teacherIds.includes(currentTeacherProfile()?.id||'teacher-local'))o.teacherIds.push(currentTeacherProfile()?.id||'teacher-local');if(o.doubleLevel&&!o.group)o.group=o.name;if(id){reconcileStudentGroupsForClass(oldClass,{...oldClass,...o},db.students);Object.assign(cls(id),o)}else db.classes.push({id:uid(),...o});syncTeacherClassLinks();auditEvent(id?'Classe modifiée':'Classe créée',o.name);save();closeModal();render();toast(id?'Classe modifiée':'Classe créée')}
function deleteClass(id){const c=cls(id);if(!c)return;const n=db.students.filter(s=>s.classId===id).length,slots=db.schedule.filter(x=>x.classId===id).length;confirmModal(`Supprimer « ${c.name} » ? ${n?`${n} élève(s) sont encore rattaché(s). `:''}${slots?`${slots} créneau(x) d’EDT sont encore rattaché(s). `:''}Les évaluations, appels et bulletins existants resteront dans les données mais ne seront plus rattachés à une classe active.`,'Supprimer la classe',()=>{db.classes=db.classes.filter(x=>x.id!==id);save();render();toast('Classe supprimée')})}
function studentsModule(){return shell('Scolarité','Élèves','Fiches élèves, groupes et informations d’inscription.',`<button class="btn" onclick="openImportStudents()">Importer CSV</button><button class="btn primary" onclick="openStudent()">+ Inscrire un élève</button>`)+`<div class="card"><div class="searchRow"><input class="input" id="studentSearch" placeholder="Rechercher un élève…" oninput="filterStudents()"><select class="select" style="max-width:220px" id="studentClass" onchange="filterStudents()"><option value="">Toutes les classes</option>${db.classes.map(c=>`<option value="${c.id}" ${window.classContext===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="tablewrap"><table class="table"><thead><tr><th>Élève</th><th>Naissance</th><th>Classe</th><th>Groupe</th><th>Moyenne</th><th></th></tr></thead><tbody id="studentRows">${studentRows()}</tbody></table></div></div>`}
function studentRows(){let q=($('#studentSearch')?.value||'').toLowerCase(),c=$('#studentClass')?.value||'',g=window.classGroupContext||'';return db.students.filter(s=>(!q||(s.first+' '+s.last).toLowerCase().includes(q))&&(!c||s.classId===c)&&(!g||s.group===g)).map(s=>`<tr><td><div class="person"><div class="avatar">${initials(s)}</div><div><b>${esc(s.last.toUpperCase())} ${esc(s.first)}</b><small>${esc(s.email||'')}</small></div></div></td><td>${fmtDate(s.birth)}</td><td>${esc(cls(s.classId)?.name||'À classer')}</td><td>${esc(s.group||'—')}</td><td>${weightedAvg([s.id])} /20</td><td><button class="btn small" onclick="openStudentProfile('${s.id}')">Profil</button><button class="btn small" onclick="openStudentActivity('${s.id}')">Suivi</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">Aucun élève.</div></td></tr>'}
function filterStudents(){document.getElementById('studentRows').innerHTML=studentRows()}
function studentWorkItems(id){return db.lessons.filter(l=>l.homework&&l.classId===student(id)?.classId&&((l.homework.due&&l.homework.due>=iso(new Date()))||l.date>=iso(new Date()))).map(l=>({l,due:l.homework.due||l.date})).sort((a,b)=>a.due.localeCompare(b.due)).slice(0,8)}
function studentAbsenceCount(id){return db.attendance.filter(a=>a.rows.some(r=>r.studentId===id&&r.status==='absent')).length}
function studentLateCount(id){return db.attendance.filter(a=>a.rows.some(r=>r.studentId===id&&r.status==='retard')).length}
function studentEvaluations(id){return db.evaluations.flatMap(e=>{const g=e.grades.find(x=>x.studentId===id);return g?[{e,g}]:[]}).sort((a,b)=>b.e.date.localeCompare(a.e.date))}
function openStudent(id){const s=id?student(id):{first:'',last:'',birth:'',sex:'',classId:'',group:'',email:'',phone:'',notes:''};const evs=id?studentEvaluations(id):[];const works=id?studentWorkItems(id):[];openModal(id?'Fiche élève':'Inscrire un élève',`<form onsubmit="saveStudent(event,'${id||''}')"><div class="form"><div class="field"><label>Prénom *</label><input class="input" name="first" required value="${esc(s.first)}"></div><div class="field"><label>Nom *</label><input class="input" name="last" required value="${esc(s.last)}"></div><div class="field"><label>Date de naissance</label><input class="input" type="date" name="birth" value="${esc(s.birth)}"></div><div class="field"><label>Sexe</label><select class="select" name="sex"><option value="">Non renseigné</option><option value="F" ${s.sex==='F'?'selected':''}>Fille</option><option value="M" ${s.sex==='M'?'selected':''}>Garçon</option><option value="X" ${s.sex==='X'?'selected':''}>Autre / non précisé</option></select></div><div class="field"><label>Classe</label><select class="select" name="classId" onchange="refreshStudentGroupChoices(this.value)"><option value="">À classer</option>${db.classes.map(c=>`<option value="${c.id}" ${s.classId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Groupe / sous-groupe</label><select class="select" id="studentGroup" name="group">${studentGroupOptions(s.classId,s.group||'')}</select></div><div class="field"><label>Email</label><input class="input" type="email" name="email" value="${esc(s.email||'')}"></div><div class="field"><label>Téléphone</label><input class="input" name="phone" value="${esc(s.phone||'')}"></div><div class="field full"><label>Informations complémentaires</label><textarea name="notes">${esc(s.notes||'')}</textarea></div></div>${id?`<div class="section"><div class="gradeStats"><div class="metric"><small>Moyenne</small><b>${avg([id])} /20</b></div><div class="metric"><small>Évaluations</small><b>${evs.length}</b></div><div class="metric"><small>Absences</small><b>${studentAbsenceCount(id)}</b></div><div class="metric"><small>Retards</small><b>${studentLateCount(id)}</b></div></div></div><div class="section"><div class="sectionhead"><h3>Dernières évaluations</h3><button type="button" class="btn small" onclick="closeModal();go('evaluations')">Voir le module</button></div>${evs.slice(0,6).map(x=>`<div class="message"><b>${esc(x.e.title)}</b><small>${esc(x.e.subject)} · ${fmtDate(x.e.date)} · <strong>${x.g.value===''?'Non noté':esc(x.g.value)+'/20'}</strong></small>${x.g.comment?`<span class="muted">${esc(x.g.comment)}</span>`:''}</div>`).join('')||'<div class="empty">Aucune note enregistrée.</div>'}</div><div class="section"><div class="sectionhead"><h3>Accès au dossier scolaire</h3></div><div class="actions"><button type="button" class="btn small" onclick="closeModal();go('attendance')">Présences</button><button type="button" class="btn small" onclick="closeModal();go('evaluations')">Évaluations</button><button type="button" class="btn small" onclick="closeModal();go('messages')">Messagerie</button><button type="button" class="btn small" onclick="closeModal();go('documents')">Documents</button></div></div><div class="section"><div class="sectionhead"><h3>Travaux à venir</h3><button type="button" class="btn small" onclick="closeModal();go('lessons')">Voir les séances</button></div>${works.map(x=>`<div class="message"><b>${esc(x.l.homework.title||'Travail')}</b><small>${esc(x.l.subject)} · à rendre le ${fmtDate(x.due)}</small></div>`).join('')||'<div class="empty">Aucun travail à venir.</div>'}</div>`:''}<div class="modalfoot">${id?`<button type="button" class="btn danger" onclick="deleteStudent('${id}')">Supprimer</button>`:''}<button type="button" class="btn" onclick="closeModal()">Annuler</button><button class="btn primary">Enregistrer</button></div></form>`)}
function studentGroupOptions(classId,current=''){const groups=cls(classId)?.groups||[];return `<option value="">${groups.length?'Classe entière':'Aucun groupe'}</option>`+groups.map(g=>`<option value="${esc(g)}" ${current===g?'selected':''}>${esc(g)}</option>`).join('')}
function refreshStudentGroupChoices(classId){const x=$('#studentGroup');if(x)x.innerHTML=studentGroupOptions(classId,'')}
function saveStudent(e,id){e.preventDefault();const o=Object.fromEntries(new FormData(e.target));if(id)Object.assign(student(id),o);else db.students.push({id:uid(),...o});auditEvent(id?'Fiche élève modifiée':'Élève inscrit',`${o.first||''} ${o.last||''}`.trim());save();closeModal();render();toast('Élève enregistré')}
function deleteStudent(id){confirmModal('Supprimer définitivement cet élève et ses notes, appels et rendus associés ?', 'Supprimer',()=>{db.students=db.students.filter(x=>x.id!==id);db.evaluations.forEach(e=>e.grades=e.grades.filter(g=>g.studentId!==id));db.attendance.forEach(a=>a.rows=a.rows.filter(r=>r.studentId!==id));db.submissions=db.submissions.filter(s=>s.studentId!==id);save();closeModal();render()})}
function openImportStudents(){openModal('Importer des élèves','<div class="notice">Colonnes reconnues : <b>prenom, nom, date de naissance, sexe, classe, groupe, email, telephone, notes</b>. Les champs après nom sont facultatifs.</div><div class="drop" style="margin-top:12px"><label><b>Choisir un CSV</b><br><span class="muted">Séparateur ; ou ,</span><input id="csvStudents" type="file" accept=".csv" onchange="previewStudentCSV(this.files[0])"></label></div><div id="csvPreview"></div><div class="modalfoot"><button class="btn" onclick="closeModal()">Annuler</button><button class="btn primary" id="importBtn" disabled onclick="doImportStudents()">Importer</button></div>')}
let csvBuffer=null;function parseCSV(t){t=t.replace(/^\uFEFF/,'');let lines=t.split(/\r?\n/).filter(Boolean),sep=(lines[0].match(/;/g)||[]).length>=(lines[0].match(/,/g)||[]).length?';':',';function p(s){let a=[],c='',q=false;for(let i=0;i<s.length;i++){let ch=s[i];if(ch==='"'){if(q&&s[i+1]==='"'){c+='"';i++}else q=!q}else if(ch===sep&&!q){a.push(c.trim());c=''}else c+=ch}a.push(c.trim());return a}return {h:p(lines[0]).map(x=>x.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'')),r:lines.slice(1).map(p)}}
function previewStudentCSV(file){if(!file)return;const r=new FileReader();r.onload=()=>{csvBuffer=parseCSV(r.result);$('#csvPreview').innerHTML=`<div class="section"><b>${csvBuffer.r.length}</b> ligne(s) · ${csvBuffer.h.join(', ')}</div>`;$('#importBtn').disabled=false};r.readAsText(file)}
function ci(h,...a){return a.map(x=>h.indexOf(x)).find(x=>x>=0)}function doImportStudents(){let h=csvBuffer.h,fi=ci(h,'prenom','prénom'),la=ci(h,'nom'),bi=ci(h,'date de naissance','naissance','date_naissance'),sx=ci(h,'sexe','sex'),cl=ci(h,'classe','class'),gr=ci(h,'groupe','group'),em=ci(h,'email','e-mail'),ph=ci(h,'telephone','tel','téléphone'),no=ci(h,'notes','informations');if(fi<0||la<0)return toast('Il faut au minimum prénom et nom.');let n=0;for(const r of csvBuffer.r){if(!r[fi]||!r[la])continue;let cname=r[cl]||'',c=db.classes.find(x=>x.name.toLowerCase()===cname.toLowerCase());if(cname&&!c){c={id:uid(),name:cname,level:'',group:'',room:'',attendanceMode:'halfday',periodMode:''};db.classes.push(c)}db.students.push({id:uid(),first:r[fi],last:r[la],birth:bi>=0?r[bi]:'',sex:sx>=0?r[sx]:'',classId:c?.id||'',group:gr>=0?r[gr]:'',email:em>=0?r[em]:'',phone:ph>=0?r[ph]:'',notes:no>=0?r[no]:''});n++}save();closeModal();render();toast(`${n} élève(s) importé(s)`)}
function gradeNumber(v){if(v===''||v===null||v===undefined)return null;const n=typeof v==='string'?Number(v.trim().replace(',','.')):Number(v);return Number.isFinite(n)?n:null}
/* V21.17 — moteur métier Évaluations : contrat centralisé, sans dépendance à l'UI. */
function evaluationModelMaxScore(e){const n=Number(e?.maxScore);return Number.isFinite(n)&&n>0?n:20}
function evaluationModelCoefficient(e){const n=Number(e?.coefficient);return Number.isFinite(n)&&n>0?n:1}
function evaluationModelDate(e){return String(e?.date||'')}
function evaluationModelTerms(db){const raw=db?.settings?.terms||db?.terms||[];return Array.isArray(raw)?raw:[]}
function evaluationModelTerm(db,termId){if(!termId)return null;return evaluationModelTerms(db).find(t=>String(t.id)===String(termId))||null}
function evaluationModelInTerm(e,term){if(!term)return true;const d=evaluationModelDate(e);if(!d)return false;return (!term.start||d>=String(term.start))&&(!term.end||d<=String(term.end))}
function evaluationModelPublished(e,today){if(e?.published===false)return false;const at=String(e?.publishAt||'');return !at||!today||at<=String(today)}
function evaluationModelTargetStudents(db,e){return (db?.students||[]).filter(s=>s.classId===e?.classId&&(!e?.group||s.group===e.group))}
function evaluationModelGrade(e,studentId){return (e?.grades||[]).find(g=>String(g.studentId)===String(studentId))||null}
function evaluationModelNumericGrade(e,g){if(!g||g.value===''||g.value===null||g.value===undefined)return null;const raw=gradeNumber(g.value);if(raw===null)return null;const max=evaluationModelMaxScore(e);return raw>=0&&raw<=max?raw:max<0?null:raw>max?null:raw}
function evaluationModelOn20(e,g){const raw=evaluationModelNumericGrade(e,g);return raw===null?null:(raw/evaluationModelMaxScore(e))*20}
function evaluationModelVisible(db,e,{studentId='',termId='',today=''}={}){if(!e||!evaluationModelPublished(e,today))return false;if(studentId&&!evaluationModelTargetStudents(db,e).some(s=>String(s.id)===String(studentId)))return false;return evaluationModelInTerm(e,evaluationModelTerm(db,termId))}
function evaluationModelItems(db,{studentId='',termId='',today=''}={}){return (db?.evaluations||[]).filter(e=>evaluationModelVisible(db,e,{studentId,termId,today})).map(e=>{const g=studentId?evaluationModelGrade(e,studentId):null;return {evaluationId:e.id,title:e.title||'',subject:e.subject||'',date:e.date||'',coefficient:evaluationModelCoefficient(e),max:evaluationModelMaxScore(e),raw:g?evaluationModelNumericGrade(e,g):null,on20:g?evaluationModelOn20(e,g):null,published:true,qualitative:Boolean((e.competencies||[]).length||(e.criteria||[]).length),comment:g?.comment||'',competencyRatings:{...(g?.competencyRatings||{})},criterionScores:{...(g?.criterionScores||{})}}})}
function evaluationModelAverage(items){const rows=(items||[]).filter(x=>x.on20!==null);if(!rows.length)return null;let sum=0,w=0;for(const x of rows){const c=Number(x.coefficient)>0?Number(x.coefficient):1;sum+=x.on20*c;w+=c}return w?sum/w:null}
function evaluationModelStudentReport(db,studentId,termId='',today=''){const items=evaluationModelItems(db,{studentId,termId,today}),by=new Map();for(const x of items){const key=x.subject||'Sans matière';if(!by.has(key))by.set(key,[]);by.get(key).push(x)}const subjects=[...by.entries()].map(([name,rows])=>({name,items:rows,average:evaluationModelAverage(rows)}));const overall=evaluationModelAverage(items);return {studentId,termId:termId||'',items,subjects,overall,counts:{total:items.length,numeric:items.filter(x=>x.on20!==null).length,qualitative:items.filter(x=>x.qualitative).length}}}
function evaluationModelClassStats(db,classId,subject='',today=''){const ids=(db?.students||[]).filter(s=>s.classId===classId).map(s=>s.id);const es=(db?.evaluations||[]).filter(e=>e.classId===classId&&(!subject||e.subject===subject)&&evaluationModelPublished(e,today));let sum=0,w=0,count=0,min=null,max=null;for(const e of es){const maxScore=evaluationModelMaxScore(e),coef=evaluationModelCoefficient(e);for(const sid of ids){const g=evaluationModelGrade(e,sid),v=evaluationModelOn20(e,g);if(v===null)continue;sum+=v*coef;w+=coef;count++;min=min===null?v:Math.min(min,v);max=max===null?v:Math.max(max,v)}}return {classId,subject,evaluations:es.length,students:ids.length,graded:count,average:w?sum/w:null,min,max}}
function evaluationModelSetGrade(db,eid,sid,value){const e=(db?.evaluations||[]).find(x=>x.id===eid);if(!e)return {ok:false,error:'evaluation_not_found'};const max=evaluationModelMaxScore(e);if(value!==''&&evaluationModelNumericGrade(e,{value})===null)return {ok:false,error:'invalid_grade',max};e.grades??=[];let g=e.grades.find(x=>String(x.studentId)===String(sid));if(!g){g={studentId:sid,value:'',comment:'',competencyRatings:{},criterionScores:{}};e.grades.push(g)}g.value=value;g.competencyRatings??={};g.criterionScores??={};return {ok:true,evaluation:e,grade:g}}
function evaluationModelSetCriterion(db,eid,sid,criterionId,value){const e=(db?.evaluations||[]).find(x=>x.id===eid);if(!e)return {ok:false,error:'evaluation_not_found'};const c=(e.criteria||[]).find(x=>String(x.id)===String(criterionId));if(!c)return {ok:false,error:'criterion_not_found'};const levels=Array.isArray(c.levels)?c.levels.map(Number).filter(Number.isFinite):[];if(value!==''&&!levels.includes(Number(value))&&Number(value)!==Number(c.maxPoints))return {ok:false,error:'invalid_criterion_score'};e.grades??=[];let g=e.grades.find(x=>String(x.studentId)===String(sid));if(!g){g={studentId:sid,value:'',comment:'',competencyRatings:{},criterionScores:{}};e.grades.push(g)}g.criterionScores??={};if(value==='')delete g.criterionScores[criterionId];else g.criterionScores[criterionId]=Number(value);return {ok:true,evaluation:e,grade:g}}
function evaluationModelSetCompetency(db,eid,sid,competency,value){const e=(db?.evaluations||[]).find(x=>x.id===eid);if(!e)return {ok:false,error:'evaluation_not_found'};if(!(e.competencies||[]).includes(competency))return {ok:false,error:'competency_not_found'};const n=value===''?null:Number(value);if(n!==null&&(!Number.isInteger(n)||n<1||n>4))return {ok:false,error:'invalid_competency_level'};e.grades??=[];let g=e.grades.find(x=>String(x.studentId)===String(sid));if(!g){g={studentId:sid,value:'',comment:'',competencyRatings:{},criterionScores:{}};e.grades.push(g)}g.competencyRatings??={};if(n===null)delete g.competencyRatings[competency];else g.competencyRatings[competency]=String(n);return {ok:true,evaluation:e,grade:g}}
function evaluationModelNormalize(e){if(!e||typeof e!=='object')return null;e.grades=Array.isArray(e.grades)?e.grades:[];e.coefficient=evaluationModelCoefficient(e);e.maxScore=evaluationModelMaxScore(e);e.competencies=Array.isArray(e.competencies)?e.competencies:[];e.criteria=Array.isArray(e.criteria)?e.criteria:[];for(const g of e.grades){g.competencyRatings=g.competencyRatings&&typeof g.competencyRatings==='object'?g.competencyRatings:{};g.criterionScores=g.criterionScores&&typeof g.criterionScores==='object'?g.criterionScores:{};if(g.value!==''&&g.value!==null&&g.value!==undefined){const n=gradeNumber(g.value);g.value=n===null?'':n}}return e}
function weightedAverageForEvaluations(es,ids){const rows=[];for(const e of es||[])for(const sid of ids||[]){const g=evaluationModelGrade(e,sid),v=evaluationModelOn20(e,g);if(v!==null)rows.push({on20:v,coefficient:evaluationModelCoefficient(e)})}const avg=evaluationModelAverage(rows);return avg===null?'—':avg.toFixed(2)}
function classAverage(classId,subjectName=''){const ids=db.students.filter(s=>s.classId===classId).map(s=>s.id);return weightedAverageForEvaluations(db.evaluations.filter(e=>e.classId===classId&&(!subjectName||e.subject===subjectName)),ids)}
function groupAverage(classId,group,subjectName=''){const ids=db.students.filter(s=>s.classId===classId&&s.group===group).map(s=>s.id);return weightedAverageForEvaluations(db.evaluations.filter(e=>e.classId===classId&&(!subjectName||e.subject===subjectName)),ids)}
function weightedAvg(ids){return weightedAverageForEvaluations(db.evaluations.filter(e=>e.grades?.some(g=>ids.includes(g.studentId))),ids)}
function evaluationStats(){const c=$('#evalClassFilter')?.value||'',sub=$('#evalSubjectFilter')?.value||'';if(!c)return '<div class="notice">Sélectionne une classe pour afficher ses statistiques.</div>';const es=db.evaluations.filter(e=>e.classId===c&&(!sub||e.subject===sub)),ids=db.students.filter(s=>s.classId===c).map(s=>s.id),vals=es.flatMap(e=>e.grades.filter(g=>ids.includes(g.studentId)&&g.value!=='').map(g=>Number(g.value))).filter(Number.isFinite),overall=weightedAverageForEvaluations(es,ids),groupsList=groups(c),subjects=[...new Set(es.map(e=>e.subject).filter(Boolean))];const evalRows=es.map(e=>{const v=e.grades.map(g=>gradeNumber(g.value)).filter(x=>x!==null),av=v.length?(v.reduce((a,b)=>a+b,0)/v.length).toFixed(2):'—';return `<tr><td><b>${esc(e.title)}</b><small class="muted" style="display:block">${esc(e.subject)}</small></td><td>${fmtDate(e.date)}</td><td>${av} /20</td><td>${v.length?Math.min(...v).toFixed(2):'—'}</td><td>${v.length?Math.max(...v).toFixed(2):'—'}</td></tr>`}).join('');return `<div class="gradeStats" style="margin-bottom:12px"><div class="metric"><small>Moyenne pondérée de la classe</small><b>${overall} /20</b></div><div class="metric"><small>Élèves</small><b>${ids.length}</b></div><div class="metric"><small>Évaluations</small><b>${es.length}</b></div><div class="metric"><small>Notes saisies</small><b>${vals.length}</b></div></div>${groupsList.length?`<div class="sectionhead"><h3>Par sous-groupe</h3></div><div class="tablewrap"><table class="table"><thead><tr><th>Sous-groupe</th><th>Élèves</th><th>Moyenne</th></tr></thead><tbody>${groupsList.map(g=>`<tr><td><b>${esc(g)}</b></td><td>${db.students.filter(s=>s.classId===c&&s.group===g).length}</td><td><b>${groupAverage(c,g,sub)} /20</b></td></tr>`).join('')}</tbody></table></div>`:''}${subjects.length?`<div class="section"><div class="sectionhead"><h3>Par matière</h3></div><div class="tablewrap"><table class="table"><thead><tr><th>Matière</th><th>Moyenne</th><th>Évaluations</th></tr></thead><tbody>${subjects.map(x=>`<tr><td><b>${esc(x)}</b></td><td>${classAverage(c,x)} /20</td><td>${es.filter(e=>e.subject===x).length}</td></tr>`).join('')}</tbody></table></div></div>`:''}${evalRows?`<div class="section"><div class="sectionhead"><h3>Détail des évaluations</h3></div><div class="tablewrap"><table class="table"><thead><tr><th>Évaluation</th><th>Date</th><th>Moyenne</th><th>Min.</th><th>Max.</th></tr></thead><tbody>${evalRows}</tbody></table></div></div>`:''}`}

function evaluations(){return shell('Évaluations','Évaluations','Évaluations par classe ou sous-groupe, saisie collective et statistiques.',`<button class="btn" onclick="manageEvaluationGrids()">Grilles & compétences</button><button class="btn" onclick="openCompetencyReport()">Bilan compétences</button><button class="btn primary" onclick="openEvaluation()">+ Nouvelle évaluation</button>`)+`<div class="card"><div class="searchRow"><select class="select" id="evalClassFilter" onchange="renderEvalList()"><option value="">Toutes les classes</option>${db.classes.map((c,i)=>`<option value="${c.id}" ${((window.classContext&&window.classContext===c.id)||( !window.classContext && i===0))?'selected':''}>${esc(c.name)}</option>`).join('')}</select><select class="select" id="evalSubjectFilter" onchange="renderEvalList()"><option value="">Toutes les matières</option>${[...new Set(db.evaluations.map(e=>e.subject))].filter(Boolean).map(s=>`<option>${esc(s)}</option>`).join('')}</select></div><div id="evalStats" class="section">${evaluationStats()}</div><div id="evalList">${evalList()}</div></div>`}
function applyEvaluationTemplate(id){const t=(db.evaluationTemplates||[]).find(x=>x.id===id);if(!t)return;const modal=$('#modal');if(!modal)return;const set=(name,value)=>{const el=modal.querySelector(`[name="${name}"]`);if(el&&value!==undefined)el.value=value};set('subject',t.subject||'');set('title',t.title||t.name||'');set('competenciesText',(t.competencies||[]).join('\n'));set('criteriaJson',JSON.stringify(t.criteria||[]));}

function saveEvaluationTemplate(ev){ev.preventDefault();const f=ev.target,o=Object.fromEntries(new FormData(f));const name=String(o.name||'').trim(),competencies=String(o.competenciesText||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean).filter((x,i,a)=>a.indexOf(x)===i),criteria=String(o.criteriaText||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean).map(line=>{const [label,...rest]=line.split('|').map(x=>x.trim());return {id:uid(),name:label,levels:rest.map(v=>Number(String(v).split(':')[0])).filter(Number.isFinite),levelDetails:rest.map(v=>{const m=String(v).match(/^\s*(-?\d+(?:\.\d+)?)\s*:\s*(.*)$/);return m?{points:Number(m[1]),description:m[2].trim()}:null}).filter(Boolean),competency:''}}).filter(c=>c.name&&c.levels.length);if(!name)return toast('Donnez un nom à la grille.');if(!competencies.length&&!criteria.length)return toast('Ajoutez au moins une compétence ou un critère noté.');db.evaluationTemplates??=[];db.competencyLibrary??=[];const t={id:uid(),name,title:String(o.title||name).trim(),level:String(o.level||'').trim(),subject:String(o.subject||'').trim(),competencies,criteria,createdAt:new Date().toISOString()};db.evaluationTemplates.push(t);competencies.forEach(c=>{if(!db.competencyLibrary.some(x=>(typeof x==='string'?x:x.name)===c))db.competencyLibrary.push(c)});db.competencyLibrary.sort((a,b)=>String(a.name||a).localeCompare(String(b.name||b),'fr'));save();manageEvaluationGrids();toast('Grille enregistrée');}

function deleteEvaluationTemplate(id){confirmModal('Supprimer cette grille réutilisable ? Les évaluations déjà créées ne seront pas modifiées.','Supprimer',()=>{db.evaluationTemplates=(db.evaluationTemplates||[]).filter(t=>t.id!==id);save();manageEvaluationGrids();toast('Grille supprimée')})}
function manageEvaluationGrids(){db.evaluationTemplates??=[];db.competencyLibrary??=[];openModal('Grilles d’évaluation et compétences',`<div class="notice">Créez vos modèles une seule fois, puis réutilisez-les pour vos évaluations. Modifier ou supprimer un modèle ne change pas les évaluations déjà enregistrées.</div><form onsubmit="saveEvaluationTemplate(event)"><div class="form section"><div class="field"><label>Nom de la grille *</label><input class="input" name="name" required placeholder="Ex. Lecture — compréhension"></div><div class="field"><label>Matière</label><input class="input" name="subject" placeholder="Français"></div><div class="field"><label>Titre proposé</label><input class="input" name="title" placeholder="Évaluation de compréhension"></div><div class="field" style="grid-column:1/-1"><label>Compétences (une par ligne) *</label><textarea class="input" name="competenciesText" rows="4" placeholder="Comprendre un texte\nRepérer les informations explicites\nJustifier une réponse"></textarea></div></div><div class="field section"><label>Critères et points (un par ligne, facultatif)</label><textarea class="input" name="criteriaText" rows="3" placeholder="Présentation organisée | 2 | 1 | 0&#10;Respect de la consigne | 3 | 2 | 1 | 0"></textarea><small class="muted">Format : critère | points possibles. Pour décrire les niveaux : Qualité de la langue | 4:Très bonne maîtrise | 3:Quelques erreurs | 2:Fragile | 0:À reprendre. Les critères notés sont distincts des compétences.</small></div><div class="modalfoot"><button class="btn primary">Enregistrer cette grille</button></div></form><div class="section"><h3>Mes grilles (${db.evaluationTemplates.length})</h3>${db.evaluationTemplates.map(t=>`<div class="message" style="display:flex;justify-content:space-between;gap:12px;align-items:center"><div><b>${esc(t.name)}</b><small style="display:block" class="muted">${esc(t.subject||'Toutes matières')} · ${(t.competencies||[]).length} compétence(s) · ${(t.criteria||[]).length} critère(s)</small><small class="muted">${(t.competencies||[]).map(esc).join(' · ')}</small></div><button class="btn small" onclick="v206EditTemplate('${t.id}')">Modifier</button><button class="btn small danger" onclick="deleteEvaluationTemplate('${t.id}')">Supprimer</button></div>`).join('')||'<div class="empty">Aucune grille enregistrée.</div>'}</div><div class="section"><h3>Bibliothèque de compétences (${db.competencyLibrary.length})</h3><div class="muted">Les compétences sont ajoutées automatiquement à cette bibliothèque lorsque vous enregistrez une grille ou une évaluation.</div>${db.competencyLibrary.length?`<div class="tagList" style="display:flex;flex-wrap:wrap;gap:6px;margin-top:8px">${db.competencyLibrary.map(c=>`<span class="pill">${esc(c)}</span>`).join('')}</div>`:'<div class="empty">La bibliothèque se remplira au fil de vos grilles.</div>'}</div><div class="modalfoot"><button class="btn" onclick="closeModal()">Fermer</button></div>`)}
function competencySummary(classId,subject=''){const es=db.evaluations.filter(e=>e.classId===classId&&(!subject||e.subject===subject));const names=[...new Set(es.flatMap(e=>Array.isArray(e.competencies)?e.competencies:[]))].sort((a,b)=>a.localeCompare(b,'fr'));return names.map(name=>{const ratings=[];for(const e of es){if(!(e.competencies||[]).includes(name))continue;for(const g of e.grades||[]){const v=Number(g.competencyRatings?.[name]);if(g.studentId&&Number.isFinite(v)&&v>=1&&v<=4)ratings.push({studentId:g.studentId,value:v,date:e.date||''})}}const avg=ratings.length?ratings.reduce((n,r)=>n+r.value,0)/ratings.length:null;return {name,count:ratings.length,average:avg===null?'—':avg.toFixed(2),ratings}})}
function openCompetencyReport(){const first=db.classes[0]?.id||'';openModal('Bilan des compétences',`<div class="searchRow"><div class="field"><label>Classe</label><select id="competencyReportClass" class="select" onchange="refreshCompetencyReport()">${db.classes.map(c=>`<option value="${c.id}" ${c.id===first?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Matière</label><select id="competencyReportSubject" class="select" onchange="refreshCompetencyReport()"><option value="">Toutes les matières</option>${[...new Set(db.evaluations.map(e=>e.subject).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'fr')).map(x=>`<option>${esc(x)}</option>`).join('')}</select></div></div><div id="competencyReportResults" class="section"></div><div class="modalfoot"><button class="btn" onclick="closeModal()">Fermer</button></div>`);refreshCompetencyReport()}
function refreshCompetencyReport(){const root=$('#competencyReportResults');if(!root)return;const cid=$('#competencyReportClass')?.value||'',subject=$('#competencyReportSubject')?.value||'',summary=competencySummary(cid,subject);if(!summary.length){root.innerHTML='<div class="empty">Aucune compétence évaluée pour ces critères. Ajoutez des compétences à une évaluation puis renseignez les niveaux des élèves.</div>';return}const labels={1:'Insuffisant',2:'Fragile',3:'Bien',4:'Très bien'};root.innerHTML=summary.map(c=>{const counts=[1,2,3,4].map(v=>({v,n:c.ratings.filter(r=>r.value===v).length}));return `<div class="card section"><div class="sectionhead"><div><h3>${esc(c.name)}</h3><small class="muted">${c.count} appréciation(s) saisie(s) · Niveau moyen : ${c.average}/4</small></div></div><div class="miniKpis">${counts.map(x=>`<div class="miniKpi"><small>${labels[x.v]}</small><b>${x.n}</b></div>`).join('')}</div><div class="tablewrap section"><table class="table"><thead><tr><th>Élève</th><th>Niveau le plus récent</th></tr></thead><tbody>${c.ratings.slice().sort((a,b)=>String(b.date).localeCompare(String(a.date))).reduce((acc,r)=>{if(!acc.some(x=>x.studentId===r.studentId))acc.push(r);return acc},[]).map(r=>{const st=student(r.studentId);return `<tr><td>${esc(st?st.first+' '+st.last:'Élève')}</td><td>${r.value} — ${labels[r.value]}</td></tr>`}).join('')||'<tr><td colspan="2">Aucun niveau renseigné.</td></tr>'}</tbody></table></div></div>`}).join('')}
function evalList(){let c=$('#evalClassFilter')?.value||'',s=$('#evalSubjectFilter')?.value||'';let a=db.evaluations.filter(e=>(!c||e.classId===c)&&(!s||e.subject===s)).sort((x,y)=>y.date.localeCompare(x.date));return a.length?`<div class="tablewrap"><table class="table"><thead><tr><th>Évaluation</th><th>Classe / groupe</th><th>Date</th><th>Coef.</th><th>Moyenne</th><th></th></tr></thead><tbody>${a.map(e=>{let ids=targetStudents(e).map(x=>x.id);return `<tr><td><b>${esc(e.title)}</b><small class="muted" style="display:block">${esc(e.subject)}</small></td><td>${esc(cls(e.classId)?.name||'')} ${e.group?`· ${esc(e.group)}`:'· classe entière'}</td><td>${fmtDate(e.date)}</td><td>${esc(e.coefficient||1)}</td><td><b>${evalAverage(e)} /20</b></td><td><button class="btn small" onclick="openEvaluation('${e.id}')">Saisir / modifier</button></td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">Aucune évaluation.</div>'}
function renderEvalList(){if($('#evalList'))$('#evalList').innerHTML=evalList();if($('#evalStats'))$('#evalStats').innerHTML=evaluationStats()}
function targetStudents(e){return db.students.filter(s=>s.classId===e.classId&&(!e.group||s.group===e.group))}
function openEvaluation(id=null){let e=id?db.evaluations.find(x=>x.id===id):{classId:'',group:'',subject:'',title:'',date:iso(new Date()),coefficient:1,grades:[]};openModal(id?'Saisie des notes':'Créer une évaluation',`<div class="notice">Choisis d’abord la <b>classe</b>, puis éventuellement le <b>sous-groupe</b>. Le tableau des élèves concernés sera automatiquement construit.</div><form onsubmit="saveEvaluationMeta(event,'${id||''}')"><div class="form" style="margin-top:12px"><div class="field"><label>Classe *</label><select class="select" name="classId" required onchange="evaluationGroupOptions(this.value,'${id||''}')"><option value="">Choisir</option>${db.classes.map(c=>`<option value="${c.id}" ${e.classId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Sous-groupe</label><select class="select" name="group" id="evalGroup"><option value="">Classe entière</option>${groups(e.classId).map(g=>`<option ${e.group===g?'selected':''}>${esc(g)}</option>`).join('')}</select></div><div class="field"><label>Matière *</label><input class="input" name="subject" required value="${esc(e.subject)}" placeholder="Français"></div><div class="field"><label>Évaluation *</label><input class="input" name="title" required value="${esc(e.title)}" placeholder="Contrôle de grammaire"></div><div class="field" style="grid-column:1/-1"><label>Appliquer une grille enregistrée</label><input type="hidden" name="criteriaJson" value="${esc(JSON.stringify(e.criteria||[]))}"><select class="select" onchange="applyEvaluationTemplateForClass(this.value)"><option value="">Ne pas appliquer de grille</option>${(db.evaluationTemplates||[]).filter(t=>!t.level||!cls(e.classId)?.level||String(t.level).toLocaleLowerCase('fr')===String(cls(e.classId)?.level).toLocaleLowerCase('fr')).map(t=>`<option value="${t.id}">${esc(t.name)}${t.subject?" · "+esc(t.subject):''}</option>`).join('')}</select><small class="muted">La grille remplit le titre, la matière et les compétences ; vous pouvez ensuite tout modifier.</small></div><div class="field"><label>Date</label><input class="input" type="date" name="date" value="${esc(e.date)}"></div><div class="field"><label>Coefficient</label><input class="input" type="number" step="0.5" min="0.5" name="coefficient" value="${esc(e.coefficient||1)}"></div><div class="field" style="grid-column:1/-1"><label>Compétences évaluées (facultatif)</label><textarea class="input" name="competenciesText" rows="2" placeholder="Une compétence par ligne, par exemple : Comprendre un texte
Justifier une réponse">${esc((e.competencies||[]).join("\n"))}</textarea><small class="muted">Une compétence par ligne. Vous pourrez ensuite renseigner le niveau de chaque élève.</small></div></div><div class="modalfoot"><button type="button" class="btn" onclick="closeModal()">Annuler</button><button class="btn primary">${id?'Actualiser le groupe':'Créer et ouvrir le tableau'}</button></div></form>${id?`<div class="section" id="gradeTableArea">${gradeTable(e)}</div>`:''}`)}
function groups(cid){return [...new Set(db.students.filter(s=>s.classId===cid&&s.group).map(s=>s.group))].sort()}
function evaluationGroupOptions(cid,id){const s=$('#evalGroup');if(s)s.innerHTML='<option value="">Classe entière</option>'+groups(cid).map(g=>`<option>${esc(g)}</option>`).join('')}
function saveEvaluationMeta(ev,id){ev.preventDefault();let o=Object.fromEntries(new FormData(ev.target));o.coefficient=Number(o.coefficient||1);try{o.criteria=JSON.parse(o.criteriaJson||'[]')}catch(_){o.criteria=[]}delete o.criteriaJson;o.competencies=String(o.competenciesText||'').split(/\r?\n/).map(x=>x.trim()).filter(Boolean).filter((x,i,a)=>a.indexOf(x)===i);
   const selectedClass=cls(o.classId); o.level=String(selectedClass?.level||o.level||'').trim();delete o.competenciesText;db.competencyLibrary??=[];o.competencies.forEach(c=>{if(!db.competencyLibrary.some(x=>(typeof x==='string'?x:x.name)===c))db.competencyLibrary.push(c)});db.competencyLibrary.sort((a,b)=>String(a.name||a).localeCompare(String(b.name||b),'fr'));if(id){const target=db.evaluations.find(x=>x.id===id);if(!target)return;Object.assign(target,o);target.grades??=[];target.grades.forEach(g=>g.competencyRatings??={});auditEvent('Évaluation modifiée',o.title||'Évaluation');save();closeModal();openEvaluation(id)}else{let e={id:uid(),...o,grades:targetStudents(o).map(s=>({studentId:s.id,value:'',competencyRatings:{},criterionScores:{}}))};db.evaluations.push(e);auditEvent('Évaluation créée',e.title||'Évaluation');save();closeModal();openEvaluation(e.id)} }
function gradeExtremes(e){const v=e.grades.filter(g=>g.value!=='').map(g=>gradeNumber(g.value)).filter(x=>x!==null);return {min:v.length?Math.min(...v).toFixed(2):'—',max:v.length?Math.max(...v).toFixed(2):'—'}}
function gradeTable(e){const ss=targetStudents(e),competencies=Array.isArray(e.competencies)?e.competencies:[],criteria=Array.isArray(e.criteria)?e.criteria:[];if(!ss.length)return '<div class="notice warn">Aucun élève ne correspond à cette classe / ce sous-groupe.</div>';const levels=[['','Non évalué'],['1','Insuffisant'],['2','Fragile'],['3','Bien'],['4','Très bien']];const maxTotal=criteria.reduce((n,c)=>n+Math.max(0,...(c.levels||[0]).map(Number)),0);return `<div class="gradeStats"><div class="metric"><small>Élèves concernés</small><b>${ss.length}</b></div><div class="metric"><small>Moyenne</small><b id="evalAvg">${evalAverage(e)} /20</b></div><div class="metric"><small>Note max</small><b>${gradeExtremes(e).max}</b></div><div class="metric"><small>Note min</small><b>${gradeExtremes(e).min}</b></div>${criteria.length?`<div class="metric"><small>Total des critères</small><b>${maxTotal} point(s)</b></div>`:''}</div>${competencies.length?`<div class="notice" style="margin-top:12px">Niveaux de compétence : 1 = Insuffisant · 2 = Fragile · 3 = Bien · 4 = Très bien. Ils sont distincts des points attribués aux critères.</div>`:''}<div class="tablewrap" style="margin-top:10px"><table class="table evaltable"><thead><tr><th>Élève</th><th>Groupe</th><th>Note /20</th>${criteria.map(c=>`<th>${esc(c.name)}<small style="display:block">${Math.max(0,...(c.levels||[0]).map(Number))} pt max.</small></th>`).join('')}${criteria.length?'<th>Total critères</th>':''}${competencies.map(c=>`<th>${esc(c)}</th>`).join('')}<th>Observation</th></tr></thead><tbody>${ss.map(st=>{let g=e.grades.find(x=>x.studentId===st.id)||{value:'',comment:'',competencyRatings:{},criterionScores:{}};g.competencyRatings??={};g.criterionScores??={};return `<tr><td><b>${esc(st.last.toUpperCase())} ${esc(st.first)}</b></td><td>${esc(st.group||'—')}</td><td><input class="input" type="number" min="0" max="20" step="0.01" value="${esc(g.value)}" onchange="setGrade('${e.id}','${st.id}',this.value)"></td>${criteria.map(c=>`<td><select class="select" aria-label="${esc(c.name)} — ${esc(st.first)} ${esc(st.last)}" onchange="setCriterionScore('${e.id}','${st.id}','${c.id}',this.value)"><option value="">—</option>${(c.levels||[]).map(v=>{const d=(c.levelDetails||[]).find(x=>Number(x.points)===Number(v))?.description||'';return `<option value="${v}" title="${esc(d)}" ${String(g.criterionScores[c.id]??'')===String(v)?'selected':''}>${v} pt${d?' — '+esc(d):''}</option>`}).join('')}</select></td>`).join('')}${criteria.length?`<td><b class="criterionTotal" data-student="${st.id}">${criteria.reduce((n,c)=>n+(Number(g.criterionScores[c.id])||0),0)} / ${maxTotal}</b></td>`:''}${competencies.map(c=>`<td><select class="select competencyRatingSelect" aria-label="${esc(c)} — ${esc(st.first)} ${esc(st.last)}" onchange="setCompetencyRating('${e.id}','${st.id}',${JSON.stringify(c).replace(/"/g,'&quot;')},this.value);setRatingColor(this)"><option value="">Non évalué</option>${levels.slice(1).map(([v,label])=>`<option value="${v}" ${v==='4'?'title=\"Ancien libellé : Très bien maîtrisé\"':''} ${String(g.competencyRatings[c]??'')===v?'selected':''}>${label}</option>`).join('')}</select></td>`).join('')}<td><input class="input" value="${esc(g.comment||'')}" onchange="setGradeComment('${e.id}','${st.id}',this.value)" placeholder="Facultatif"></td></tr>`}).join('')}</tbody></table></div><div class="modalfoot"><button class="btn danger" onclick="deleteEvaluation('${e.id}')">Supprimer</button><button class="btn" onclick="closeModal();render()">Fermer</button></div>`}

function evalAverage(e){const rows=targetStudents(e).map(s=>evaluationModelOn20(e,evaluationModelGrade(e,s.id))).filter(v=>v!==null);if(!rows.length)return '—';return (rows.reduce((a,b)=>a+b,0)/rows.length).toFixed(2)}
function setGrade(eid,sid,v){let e=db.evaluations.find(x=>x.id===eid),g=e.grades.find(x=>x.studentId===sid);if(!g){g={studentId:sid,value:'',comment:''};e.grades.push(g)}g.value=v;save();if($('#evalAvg'))$('#evalAvg').textContent=evalAverage(e)+' /20'}function setGradeComment(eid,sid,v){let e=db.evaluations.find(x=>x.id===eid),g=e.grades.find(x=>x.studentId===sid);if(!g){g={studentId:sid,value:'',comment:'',competencyRatings:{}};e.grades.push(g)}g.comment=v;save()}function setCompetencyRating(eid,sid,competency,value){const e=db.evaluations.find(x=>x.id===eid);if(!e)return;let g=e.grades.find(x=>x.studentId===sid);if(!g){g={studentId:sid,value:'',comment:'',competencyRatings:{}};e.grades.push(g)}g.competencyRatings??={};if(value==='')delete g.competencyRatings[competency];else g.competencyRatings[competency]=value;save()}function deleteEvaluation(id){confirmModal('Supprimer cette évaluation et toutes ses notes ?', 'Supprimer',()=>{db.evaluations=db.evaluations.filter(e=>e.id!==id);db.lessons.forEach(l=>{if(l.homework?.linkedEvaluation&&(l.homework.linkedEvaluation.id===id||l.homework.linkedEvaluation===id))l.homework.linkedEvaluation=false});save();closeModal();render()})}
function attendanceSlotLabel(a){if(a.mode==='halfday')return a.partOfDay==='afternoon'?'Après-midi':'Matin';const o=db.schedule.find(x=>x.id===a.slotId);return o?`${time(o.time)}–${time(o.endTime||addHour(o.time))} · ${esc(o.subject)}`:(a.time||'Cours')}
function attendance(){let classes=db.classes,cf=window.classContext||'';return shell('Vie de classe','Appels','Tableau à cases : présent par défaut, absent ou retard en un clic. Le mode d’appel se règle par classe.',`<button class="btn primary" onclick="openAttendance()">+ Nouvel appel</button><button class="btn" onclick="go('attendanceFollowup')">Suivi des absences et retards</button>`)+`<div class="card"><div class="toolbar"><label class="label">Classe</label><select class="select" style="max-width:240px" onchange="window.classContext=this.value;render()"><option value="">Toutes les classes</option>${db.classes.map(c=>`<option value="${c.id}" ${cf===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="tablewrap"><table class="table"><thead><tr><th>Date</th><th>Classe</th><th>Créneau</th><th>Mode</th><th>Absents</th><th></th></tr></thead><tbody>${db.attendance.filter(a=>!cf||a.classId===cf).sort((a,b)=>b.date.localeCompare(a.date)).map(a=>`<tr><td>${fmtDate(a.date)}</td><td>${esc(cls(a.classId)?.name||'')}</td><td>${attendanceSlotLabel(a)}</td><td><span class="pill blue">${a.mode==='halfday'?'Demi-journée':'Par cours'}</span></td><td>${a.rows.filter(x=>x.status==='absent').length}</td><td><button class="btn small" onclick="openAttendance('${a.id}')">Ouvrir</button></td></tr>`).join('')||'<tr><td colspan="6"><div class="empty">Aucun appel enregistré.</div></td></tr>'}</tbody></table></div></div>`}
function openAttendance(id=null,preset=null){const p=(!id&&preset)||{};const pDate=p.date||iso(new Date());const firstOcc=dayOcc(new Date(pDate)).find(o=>o.classId);const defaultClass=p.classId||firstOcc?.classId||'';const defaultSlot=p.slotId||((cls(defaultClass)?.attendanceMode==='hour')?dayOcc(new Date(pDate)).find(o=>o.classId===defaultClass)?.id||'':'');let a=id?db.attendance.find(x=>x.id===id):{classId:defaultClass,date:pDate,slotId:defaultSlot,partOfDay:'',rows:[]};const mode=a.classId?(cls(a.classId)?.attendanceMode||'halfday'):'halfday';a.mode=mode;openModal(id?'Modifier l’appel':'Nouvel appel',`<form onsubmit="saveAttendance(event,'${id||''}')"><div class="form"><div class="field"><label>Classe *</label><select class="select" name="classId" id="attClass" required onchange="attendanceSetup(this.value,'${id||''}')"><option value="">Choisir</option>${db.classes.map(c=>`<option value="${c.id}" ${a.classId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Date *</label><input class="input" id="attDate" type="date" name="date" required value="${esc(a.date)}" onchange="attendanceSetup($('#attClass').value,'${id||''}')"></div></div><div id="attendanceContext" class="section">${attendanceContext(a)}</div><div id="attendanceArea" class="section">${attendanceTable(a)}</div><div class="modalfoot"><button type="button" class="btn" onclick="closeModal()">Annuler</button><button class="btn primary">Enregistrer l’appel</button></div></form>`)}
function attendanceContext(a){if(!a.classId)return '<div class="notice">Choisis une classe pour afficher le mode d’appel configuré dans ses paramètres.</div>';const mode=cls(a.classId)?.attendanceMode||'halfday';if(mode==='halfday')return `<div class="attContext"><div class="field"><label>Mode configuré</label><div class="input" style="background:#f8fafc">Demi-journée</div></div><div class="field"><label>Période</label><select class="select" name="partOfDay" id="attPart"><option value="morning" ${a.partOfDay==='morning'?'selected':''}>Matin</option><option value="afternoon" ${a.partOfDay==='afternoon'?'selected':''}>Après-midi</option></select></div></div>`;const slots=dayOcc(new Date($('#attDate')?.value||a.date)).filter(o=>o.classId===a.classId);return `<div class="attContext"><div class="field"><label>Mode configuré</label><div class="input" style="background:#f8fafc">À chaque cours</div></div><div class="field"><label>Cours</label><select class="select" name="slotId" id="attSlot"><option value="">Choisir le cours</option>${slots.map(o=>`<option value="${o.id}" ${a.slotId===o.id?'selected':''}>${time(o.time)}–${time(o.endTime||addHour(o.time))} · ${esc(o.subject)}</option>`).join('')}</select>${!slots.length?'<div class="hint">Aucun cours de cette classe dans l’EDT ce jour-là.</div>':''}</div></div>`}
function attendanceSetup(cid,id){const date=$('#attDate')?.value||iso(new Date()),old=id?db.attendance.find(x=>x.id===id):{classId:cid,date,slotId:'',partOfDay:'',rows:[]};old.classId=cid;old.date=date;old.mode=cls(cid)?.attendanceMode||'halfday';if($('#attendanceContext'))$('#attendanceContext').innerHTML=attendanceContext(old);if($('#attendanceArea'))$('#attendanceArea').innerHTML=attendanceTable(old)}

function attendanceTable(a){const slot=a.mode==='hour'?(dayOcc(new Date(a.date||iso(new Date()))).find(x=>String(x.id)===String(a.slotId))||db.schedule.find(x=>String(x.id)===String(a.slotId))):null;let ss=db.students.filter(s=>s.classId===a.classId&&(!slot?.group||String(s.group||'')===String(slot.group)));if(!ss.length)return '<div class="notice warn">Cette classe n’a aucun élève.</div>';return `<div class="notice">Par défaut, tous les élèves sont <b>présents</b>. Clique directement dans la colonne voulue. Si un élève est absent, tu peux ensuite cocher « justifiée » et saisir le motif.</div><div class="tablewrap" style="margin-top:10px"><table class="table attendance"><thead><tr><th>Élève</th><th>Présent</th><th>Absent</th><th>Retard</th><th>Justifiée</th><th>Motif</th></tr></thead><tbody>${ss.map(s=>{let r=a.rows.find(x=>x.studentId===s.id)||{studentId:s.id,status:'present',justified:false,reason:''};return `<tr data-student="${s.id}"><td><b>${esc(s.last.toUpperCase())} ${esc(s.first)}</b></td>${['present','absent','retard'].map(st=>`<td><button type="button" class="statusBtn ${r.status===st?'on '+st:''}" onclick="setAtt('${s.id}','${st}')">${st==='present'?'✓':st==='absent'?'A':'R'}</button></td>`).join('')}<td><input type="checkbox" ${r.justified?'checked':''} onchange="setAttJust('${s.id}',this.checked)"></td><td><input class="input" value="${esc(r.reason||'')}" placeholder="Motif" onchange="setAttReason('${s.id}',this.value)"></td></tr>`}).join('')}</tbody></table></div>`}
let attDraft=null;function getAttDraft(){if(!attDraft)attDraft={};return attDraft}function setAtt(sid,status){const row=getAttDraft()[sid]||{status:'present',justified:false,reason:''};row.status=status;getAttDraft()[sid]=row;const tr=document.querySelector(`[data-student="${sid}"]`);tr.querySelectorAll('.statusBtn').forEach(b=>b.className='statusBtn');tr.querySelectorAll('.statusBtn')[['present','absent','retard'].indexOf(status)].className='statusBtn on '+status}function setAttJust(sid,v){(getAttDraft()[sid]??={status:'present'}).justified=v}function setAttReason(sid,v){(getAttDraft()[sid]??={status:'present'}).reason=v}
function saveAttendance(ev,id){ev.preventDefault();const o=Object.fromEntries(new FormData(ev.target)),c=cls(o.classId),mode=c?.attendanceMode||'halfday',slot=mode==='hour'?(dayOcc(new Date(o.date)).find(x=>String(x.id)===String(o.slotId))||db.schedule.find(x=>String(x.id)===String(o.slotId))):null,ss=db.students.filter(s=>s.classId===o.classId&&(!slot?.group||String(s.group||'')===String(slot.group))),draft=getAttDraft();if(mode==='hour'&&!o.slotId)return toast('Choisis un cours de l’EDT.');if(mode==='halfday'&&!o.partOfDay)return toast('Choisis matin ou après-midi.');let a=id?db.attendance.find(x=>x.id===id):{id:uid()};Object.assign(a,{classId:o.classId,date:o.date,mode,slotId:mode==='hour'?o.slotId:'',partOfDay:mode==='halfday'?o.partOfDay:'',time:mode==='hour'?(dayOcc(new Date(o.date)).find(x=>x.id===o.slotId)?.time||''):'',rows:ss.map(s=>{let old=a.rows?.find(r=>r.studentId===s.id)||{status:'present',justified:false,reason:''},d=draft[s.id]||old;return {studentId:s.id,status:d.status||'present',justified:!!d.justified,reason:d.reason||''}})});if(!id)db.attendance.push(a);auditEvent(id?'Appel modifié':'Appel enregistré',`${cls(o.classId)?.name||''} · ${fmtDate(o.date)}`);attDraft=null;save();closeModal();render();toast('Appel enregistré')}
function bulletins(){const cf=window.classContext||'';return shell('Évaluation','Bulletins','Périodes, matières, appréciations et synthèse par élève. Les matières absentes peuvent rester vides.',`<button class="btn" onclick="go('settings')">Périodes</button><button class="btn primary" onclick="openBulletin()">+ Bulletin</button>`)+`<div class="card"><div class="toolbar"><label class="label">Classe</label><select class="select" style="max-width:240px" onchange="window.classContext=this.value;render()"><option value="">Toutes les classes</option>${db.classes.map(c=>`<option value="${c.id}" ${cf===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="tablewrap"><table class="table"><thead><tr><th>Élève</th><th>Classe</th><th>Période</th><th>État</th><th></th></tr></thead><tbody>${db.bulletins.filter(b=>!cf||b.classId===cf).map(b=>`<tr><td><b>${esc(student(b.studentId)?.last||'')} ${esc(student(b.studentId)?.first||'')}</b></td><td>${esc(cls(b.classId)?.name||'')}</td><td>${esc(term(b.termId)?.name||'')}</td><td><span class="pill ${b.published?'green':'orange'}">${b.published?'Finalisé':'Brouillon'}</span></td><td><button class="btn small" onclick="openBulletin('${b.id}')">Ouvrir</button></td></tr>`).join('')||'<tr><td colspan="5"><div class="empty">Aucun bulletin créé.</div></td></tr>'}</tbody></table></div></div>`}
function term(id){return db.settings.terms.find(x=>x.id===id)}function openBulletin(id=null){let b=id?db.bulletins.find(x=>x.id===id):{studentId:'',classId:'',termId:db.settings.terms[0]?.id||'',subjectData:{},overall:''};if(!id)return openModal('Créer un bulletin',`<form onsubmit="createBulletin(event)"><div class="form"><div class="field"><label>Classe *</label><select class="select" name="classId" required><option value="">Choisir</option>${db.classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Période *</label><select class="select" name="termId">${db.settings.terms.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></div><div class="field full"><label>Élève *</label><select class="select" name="studentId" required><option value="">Choisir</option>${db.students.map(s=>`<option value="${s.id}">${esc(s.last.toUpperCase())} ${esc(s.first)} · ${esc(cls(s.classId)?.name||'')}</option>`).join('')}</select></div></div><div class="modalfoot"><button type="button" class="btn" onclick="closeModal()">Annuler</button><button class="btn primary">Créer</button></div></form>`);let s=student(b.studentId),c=cls(b.classId),subjects=[...new Set(db.evaluations.filter(e=>e.classId===b.classId).map(e=>e.subject).filter(Boolean))];openModal('Bulletin',`<div class="bulletin"><div class="bulletinhead"><div><h2>Bulletin scolaire</h2><div class="muted">${esc(c?.name||'')} · ${esc(term(b.termId)?.name||'')}</div></div><div><b>${esc(s?.last?.toUpperCase()||'')} ${esc(s?.first||'')}</b><br><small>${fmtDate(s?.birth)}</small></div></div><div class="bulletinGrid"><div><b>Matière</b></div><div><b>Moyenne</b></div><div><b>Appréciation</b></div>${subjects.map(sub=>{let av=subjectAverage(b.studentId,b.classId,sub,b.termId);return `<div>${esc(sub)}</div><div>${av}</div><div><input class="input" value="${esc(b.subjectData[sub]?.comment||'')}" data-bulletin-id="${esc(b.id)}" data-bulletin-subject="${esc(sub)}" onchange="setBulletinCommentFromInput(this)"></div>`}).join('')}</div><div class="section"><label class="field"><b>Appréciation générale</b><textarea onchange="setBulletinOverall('${b.id}',this.value)">${esc(b.overall||'')}</textarea></label></div></div><div class="modalfoot"><button class="btn" onclick="window.print()">Imprimer</button><button class="btn danger" onclick="deleteBulletin('${b.id}')">Supprimer</button><button class="btn primary" onclick="closeModal()">Fermer</button></div>`)}
function createBulletin(e){e.preventDefault();const o=Object.fromEntries(new FormData(e.target));if(student(o.studentId)?.classId!==o.classId)return toast('L’élève sélectionné n’appartient pas à cette classe.');db.bulletins.push({id:uid(),...o,subjectData:{},overall:'',published:false});save();closeModal();openBulletin(db.bulletins[db.bulletins.length-1].id)}

function canEditBulletinSubject(classId,subject){if(authUser?.role==='admin')return true;if(authUser?.role!=='teacher')return false;const t=currentTeacherProfile(),c=cls(classId);if(!t||!c)return false;const assigned=(c.teacherIds||[]).includes(t.id)||c.principalTeacherId===t.id;if(!assigned)return false;const norm=v=>String(v||'').normalize('NFD').replace(/[\\u0300-\\u036f]/g,'').trim().toLocaleLowerCase('fr');return (Array.isArray(t.subjects)?t.subjects:[]).some(x=>norm(x)===norm(subject))}
function setBulletinComment(id,sub,v){let b=db.bulletins.find(x=>x.id===id);b.subjectData[sub]??={};b.subjectData[sub].comment=v;save()}function setBulletinOverall(id,v){db.bulletins.find(x=>x.id===id).overall=v;save()}function deleteBulletin(id){confirmModal('Supprimer ce bulletin ?', 'Supprimer',()=>{db.bulletins=db.bulletins.filter(x=>x.id!==id);save();closeModal();render()})}
function teacherUser(id=currentTeacherId()){return db.teachers?.find(t=>t.id===id)||{id:id||'teacher-local',role:'teacher',first:'Enseignant',last:'MaClasse',classIds:[]}}
function teacherName(t){return `${t?.first||''} ${t?.last||''}`.trim()||'Enseignant'}
function accessibleTeachersForStudent(sid){const s=student(sid);if(!s)return[];const ids=new Set([...(cls(s.classId)?.teacherIds||[])]);return (db.teachers||[]).filter(t=>t.active!==false&&(!ids.size||ids.has(t.id)))}
function teacherCanReachStudent(tid,sid){const s=student(sid),t=teacherUser(tid);return !!s&&(!t.classIds?.length||t.classIds.includes(s.classId))}
function documentInventory(){const items=[];for(const l of db.lessons){for(const f of (l.files||[]))items.push({file:f,kind:'Cours',title:l.title||l.subject||'Séance',date:l.date,subject:l.subject,classId:l.classId,group:l.group||'',key:`course|${l.id}`});for(const f of (l.homework?.files||[]))items.push({file:f,kind:'Devoir',title:l.homework.title||'Travail',date:l.homework.due||l.date,subject:l.subject,classId:l.classId,group:l.group||'',key:`homework|${l.id}`})}for(const c of db.conversations)for(const m of (c.messages||[]))for(const f of (m.files||[]))items.push({file:f,kind:'Liaison',title:c.title||conversationTitle(c),date:m.date,subject:'',classId:c.classId||'',group:'',key:`message|${c.id}|${m.id}`});for(const sub of (db.submissions||[])){const l=db.lessons.find(x=>x.id===sub.lessonId),st=student(sub.studentId);if(l&&sub.file)items.push({file:sub.file,kind:'Rendu élève',title:l.homework?.title||'Travail à rendre',date:sub.submittedAt?.slice(0,10)||l.homework?.due||l.date,subject:l.subject,classId:l.classId,group:l.group||'',studentId:sub.studentId,studentName:st?`${st.last.toUpperCase()} ${st.first}`:'Élève',key:`submission|${l.id}`})}return items}
function docDate(d){return d||'9999-12-31'}
function docLabel(x){const date=docDate(x.date), subject=x.subject||'Sans matière', title=x.title||'Sans titre'; return {date,subject,title,className:cls(x.classId)?.name||'Toutes classes'}}
function documentTree(items){const roots=new Map();for(const x of items){const meta=docLabel(x),rootName=x.kind; if(!roots.has(rootName))roots.set(rootName,{name:rootName,kind:x.kind,classes:new Map()});const root=roots.get(rootName);const className=meta.className;if(!root.classes.has(className))root.classes.set(className,{name:className,subjects:new Map()});const c=root.classes.get(className);if(!c.subjects.has(meta.subject))c.subjects.set(meta.subject,new Map());const subj=c.subjects.get(meta.subject);const workKey=`${meta.date}|${meta.title}|${x.key}`;if(!subj.has(workKey))subj.set(workKey,{name:meta.title,date:meta.date,files:[],studentFiles:[]});const w=subj.get(workKey);if(x.kind==='Rendu élève'){w.studentFiles.push({file:x.file,name:x.studentName||'Élève'})}else w.files.push(x.file)}return [...roots.values()].sort((a,b)=>a.name.localeCompare(b.name,'fr')).map(r=>({...r,classes:[...r.classes.values()].sort((a,b)=>a.name.localeCompare(b.name,'fr')).map(c=>({...c,subjects:[...c.subjects.entries()].sort((a,b)=>a[0].localeCompare(b[0],'fr')).map(([name,works])=>({name,works:[...works.values()].sort((a,b)=>b.date.localeCompare(a.date)).map(w=>w)}))}))}))}
function fileIcon(name){const e=String(name||'').split('.').pop().toLowerCase();return ['pdf'].includes(e)?'📕':['doc','docx','odt'].includes(e)?'📘':['xls','xlsx','csv'].includes(e)?'📗':['ppt','pptx'].includes(e)?'📙':['jpg','jpeg','png','gif','webp'].includes(e)?'🖼️':['zip','rar'].includes(e)?'🗜️':'📄'}
function docFileHtml(f,label=''){const name=esc(f?.name||'Fichier');const lab=label?`<small>${esc(label)}</small>`:'';const links=f?.url?`<a class="btn small" href="${esc(f.url)}" target="_blank" rel="noopener">Ouvrir</a><a class="btn small" href="${esc(f.url)}" download>Télécharger</a>`:'—';return `<div class="docFile"><span>▧</span><div><b>${name}</b>${lab}</div><div class="actions">${links}</div></div>`}
function docWorkHtml(w){return `<details class="docWork" open><summary><div><b>${fmtDate(w.date)} — ${esc(w.name)}</b></div><span>${w.files.length+w.studentFiles.length} fichier(s)</span></summary><div class="docWorkBody">${w.files.map(f=>docFileHtml(f)).join('')}${w.studentFiles.map(x=>docFileHtml(x.file,x.name)).join('')}</div></details>`}
function docSubjectHtml(sub){return `<details class="docSubject" open><summary><span>📚 ${esc(sub.name)}</span><span>${sub.works.length} travail(s)</span></summary><div class="docWorkList">${sub.works.map(docWorkHtml).join('')}</div></details>`}
function docClassHtml(c){return `<details class="docClass" open><summary><b>${esc(c.name)}</b><span>${c.subjects.length} matière(s)</span></summary><div class="docClassBody">${c.subjects.map(docSubjectHtml).join('')}</div></details>`}
function documentTreeHtml(tree){return tree.map(r=>{const count=r.classes.reduce((n,c)=>n+c.subjects.reduce((m,s)=>m+s.works.reduce((k,w)=>k+w.files.length+w.studentFiles.length,0),0),0);return `<details class="docRoot" open><summary><div><span class="pill ${r.kind==='Cours'?'green':r.kind==='Devoir'?'blue':r.kind==='Rendu élève'?'orange':'purple'}">${esc(r.name)}</span></div><b>${count} fichier(s)</b></summary><div class="docRootBody">${r.classes.map(docClassHtml).join('')}</div></details>`}).join('')||'<div class="empty">Aucun document ne correspond à ces critères.</div>'}
function documentRows(items){const q=($('#docSearch')?.value||'').toLowerCase(),kind=$('#docKind')?.value||'',classId=$('#docClass')?.value||'';const filtered=items.filter(x=>(!kind||x.kind===kind)&&(!classId||x.classId===classId)&&((x.file?.name||'').toLowerCase().includes(q)||(x.title||'').toLowerCase().includes(q)||(x.subject||'').toLowerCase().includes(q)||(x.studentName||'').toLowerCase().includes(q)));return documentTreeHtml(documentTree(filtered))}
function documentsLegacy(){const items=documentInventory(),kinds=[...new Set(items.map(x=>x.kind))];const kindOptions=kinds.map(k=>`<option value="${esc(k)}">${esc(k)}</option>`).join('');const classOptions=db.classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('');return shell('Ressources','Documents','Une arborescence automatique : type → classe → matière → travail, avec la date du rendu en premier.',`<button class="btn" onclick="go('lessons')">Voir les séances</button>`)+`<div class="card docTools"><div class="searchRow"><input class="input" id="docSearch" placeholder="Rechercher un fichier, un travail, un élève…" oninput="filterDocuments()"><select class="select" id="docKind" onchange="filterDocuments()"><option value="">Tous les types</option>${kindOptions}</select><select class="select" id="docClass" onchange="filterDocuments()"><option value="">Toutes les classes</option>${classOptions}</select></div><div class="muted" style="margin-top:8px">Exemple : <b>Devoirs → 6A → Français → 03/10/2026 — Dictée 2</b>. Les 30 rendus de ce travail restent dans le même dossier.</div></div><div class="docSections"><div class="sectionhead"><div><h2>Arborescence</h2><div class="muted">${items.length} fichier(s)</div></div><button class="btn small" onclick="document.querySelectorAll('.docRoot,.docClass,.docSubject,.docWork').forEach(x=>x.open=false)">Tout réduire</button></div><div id="docList">${documentRows(items)}</div></div>`}
function filterDocuments(){const box=$('#docList');if(box)box.innerHTML=documentRows(documentInventory())}

function studentProfileData(id){const s=student(id);if(!s)return null;const grades=studentEvaluations(id), abs=db.attendance.flatMap(a=>a.rows.filter(r=>r.studentId===id&&r.status!=='present').map(r=>({date:a.date,status:r.status,justified:r.justified,reason:r.reason,classId:a.classId}))).sort((a,b)=>b.date.localeCompare(a.date));const works=studentWorkItems(id);const msgs=db.conversations.filter(c=>c.participantIds?.includes(id)).flatMap(c=>(c.messages||[]).map(m=>({...m,conversationId:c.id,title:c.title||conversationTitle(c)}))).sort((a,b)=>String(b.date).localeCompare(String(a.date)));const bulletins=db.bulletins.filter(b=>b.studentId===id);return {s,grades,abs,works,msgs,bulletins}}
function profile360Data(id){const s=student(id);if(!s)return null;const grades=studentEvaluations(id).sort((a,b)=>b.e.date.localeCompare(a.e.date));const abs=db.attendance.flatMap(a=>(a.rows||[]).filter(r=>r.studentId===id&&r.status!=='present').map(r=>({date:a.date,status:r.status,justified:r.justified,reason:r.reason,classId:a.classId}))).sort((a,b)=>b.date.localeCompare(a.date));const works=studentWorkItems(id);const msgs=db.conversations.filter(c=>c.participantIds?.includes(id)).flatMap(c=>(c.messages||[]).map(m=>({...m,conversationId:c.id,title:c.title||conversationTitle(c)}))).sort((a,b)=>String(b.date).localeCompare(String(a.date)));const bulletins=db.bulletins.filter(b=>b.studentId===id).sort((a,b)=>String(b.termId).localeCompare(String(a.termId)));const docs=documentInventory().filter(x=>x.studentId===id);return {s,grades,abs,works,msgs,bulletins,docs}}
function profile360Tab(id,tab){const d=profile360Data(id);if(!d)return;const {s,grades,abs,works,msgs,bulletins,docs}=d;let body='';if(tab==='notes')body=`<div class="profile360Card"><h3>Évaluations</h3>${grades.map(x=>`<div class="profile360Link"><div><b>${esc(x.e.title)}</b><small>${esc(x.e.subject||'')} · ${fmtDate(x.e.date)} · coef. ${x.e.coefficient||1}</small></div><b>${x.g.value===''?'Non noté':esc(x.g.value)+' /20'}</b></div>`).join('')||'<div class="profile360Empty">Aucune évaluation.</div>'}</div>`;else if(tab==='attendance')body=`<div class="profile360Card"><h3>Assiduité</h3>${abs.map(x=>`<div class="profile360Link"><div><b>${x.status==='absent'?'Absence':'Retard'}</b><small>${fmtDate(x.date)} · ${x.justified?'Justifiée':'Non justifiée'}${x.reason?' · '+esc(x.reason):''}</small></div><span class="pill ${x.justified?'green':'red'}">${x.justified?'OK':'À vérifier'}</span></div>`).join('')||'<div class="profile360Empty">Aucune absence ou retard.</div>'}</div>`;else if(tab==='works')body=`<div class="profile360Card"><h3>Travaux</h3>${works.map(x=>{const got=db.submissions.some(z=>z.lessonId===x.l.id&&z.studentId===id);return `<div class="profile360Link"><div><b>${esc(x.l.homework?.title||'Travail')}</b><small>${esc(x.l.subject||'')} · échéance ${fmtDate(x.due)}</small></div><span class="pill ${got?'green':'orange'}">${got?'Rendu':'À faire'}</span></div>`}).join('')||'<div class="profile360Empty">Aucun travail à venir.</div>'}</div>`;else if(tab==='communications')body=`<div class="profile360Card"><div class="sectionhead"><h3>Communications</h3><button class="btn small" onclick="openMessage(null,'${s.classId}')">+ Nouveau</button></div>${msgs.map(m=>`<button class="profile360Link" style="width:100%;text-align:left;background:transparent;border:0;border-bottom:1px solid var(--line);cursor:pointer;color:var(--ui-text)" onclick="openConversation('${m.conversationId}')"><div><b>${esc(m.title||'Conversation')}</b><small>${messageDateTime(m.date)} · Message</small></div><span>›</span></button>`).join('')||'<div class="profile360Empty">Aucune communication adressée à cet élève.</div>'}</div>`;else if(tab==='bulletins')body=`<div class="profile360Card"><h3>Bulletins</h3>${bulletins.map(b=>`<div class="profile360Link"><div><b>${esc(term(b.termId)?.name||'Période')}</b><small>${b.published?'Finalisé':'Brouillon'}${b.overall?' · '+esc(b.overall):''}</small></div><button class="btn small" onclick="openBulletin('${b.id}')">Ouvrir</button></div>`).join('')||'<div class="profile360Empty">Aucun bulletin.</div>'}</div>`;else if(tab==='documents')body=`<div class="profile360Card"><h3>Documents liés</h3>${docs.map((x,i)=>{const key='pd'+i+'_'+uid().slice(-6);window._profileDocs=window._profileDocs||{};window._profileDocs[key]=[x];return `<div class="profile360Link"><div><b>${esc(x.file?.name||'Fichier')}</b><small>${esc(x.kind)} · ${esc(x.title||'')} · ${fmtDate(x.date)}</small></div><button class="btn small" onclick="openProfileDocument('${key}')">Ouvrir</button></div>`}).join('')||'<div class="profile360Empty">Aucun document lié à cet élève.</div>'}</div>`;else body=`<div class="profile360Grid"><div class="profile360Card"><h3>Résumé scolaire</h3><div class="miniKpis"><div class="miniKpi"><small>Moyenne</small><b>${weightedAvg([id])} /20</b></div><div class="miniKpi"><small>Évaluations</small><b>${grades.length}</b></div><div class="miniKpi"><small>Absences</small><b>${abs.filter(x=>x.status==='absent').length}</b></div><div class="miniKpi"><small>Rendus</small><b>${db.submissions.filter(x=>x.studentId===id).length}</b></div></div></div><div class="profile360Card"><h3>Dernières activités</h3>${grades.slice(0,4).map(x=>`<div class="profile360Link"><div><b>${esc(x.e.title)}</b><small>${esc(x.e.subject||'')} · ${fmtDate(x.e.date)}</small></div><b>${x.g.value===''?'—':esc(x.g.value)+'/20'}</b></div>`).join('')||'<div class="profile360Empty">Aucune activité récente.</div>'}</div><div class="profile360Card"><h3>À surveiller</h3>${abs.filter(x=>!x.justified).slice(0,4).map(x=>`<div class="profile360Link"><div><b>Absence non justifiée</b><small>${fmtDate(x.date)}${x.reason?' · '+esc(x.reason):''}</small></div><button class="btn small" onclick="profile360Tab('${id}','attendance')">Voir</button></div>`).join('')||'<div class="profile360Empty">Aucun point d’attention.</div>'}</div><div class="profile360Card"><h3>Accès rapides</h3><div class="actions"><button class="btn" onclick="profile360Tab('${id}','notes')">Notes</button><button class="btn" onclick="profile360Tab('${id}','works')">Travaux</button><button class="btn" onclick="profile360Tab('${id}','communications')">Communications</button><button class="btn" onclick="profile360Tab('${id}','documents')">Documents</button></div></div></div>`;const tabs=[['overview','Vue d’ensemble'],['notes','Notes'],['attendance','Assiduité'],['works','Travaux'],['communications','Communications'],['bulletins','Bulletins'],['documents','Documents']];const html=`<div class="profile360Head"><div class="profile360Identity"><div class="profile360Avatar">${initials(s)}</div><div><h2 style="margin:0">${esc(s.last.toUpperCase())} ${esc(s.first)}</h2><div class="muted">${esc(cls(s.classId)?.name||'Sans classe')}${s.group?' · '+esc(s.group):''} · ${s.birth?fmtDate(s.birth):'Date de naissance non renseignée'}</div></div></div><div class="actions"><button class="btn" onclick="closeModal();openStudent('${id}')">Modifier</button><button class="btn" onclick="openStudentActivity('${id}')">Suivi rapide</button></div></div><div class="profile360Tabs">${tabs.map(([k,label])=>`<button class="profile360Tab ${tab===k?'active':''}" onclick="profile360Tab('${id}','${k}')">${label}</button>`).join('')}</div>${body}<div class="modalfoot"><button class="btn primary" onclick="closeModal()">Fermer</button></div>`;$('#modal').innerHTML=html}
function openProfileDocument(key){const items=window._profileDocs?.[key]||[];if(items.length)openDocumentWork(items)}
function openStudentProfile(id){const d=profile360Data(id);if(!d)return;openModal('Profil élève', '');profile360Tab(id,'overview')}
function adminUsers(){const teachers=db.users.filter(u=>u.role==='teacher'),students=db.users.filter(u=>u.role==='student');return shell('Administration','Utilisateurs','Créer, désactiver et gérer les accès MaClasse.',`<button class="btn primary" onclick="openUserEditor()">+ Nouveau professeur</button><button class="btn" onclick="openStudentAccountEditor()">+ Compte élève</button><button class="btn" onclick="clearSession()">Se déconnecter</button>`)+`<div class="card"><div class="sectionhead"><div><h2>Comptes enseignants</h2><div class="muted">Accès à l’espace de travail professeur.</div></div></div>${teachers.map(u=>`<div class="message" style="display:flex;justify-content:space-between;gap:12px;align-items:center"><div><b>${esc(u.name||u.username)}</b><small>@${esc(u.username)} · ${u.active===false?'Désactivé':'Actif'}${u.teacherId?' · professeur lié':''}</small></div><div class="actions"><button class="btn small" onclick="openUserEditor('${u.id}')">Modifier</button><button class="btn small" onclick="toggleUser('${u.id}')">${u.active===false?'Activer':'Désactiver'}</button></div></div>`).join('')||'<div class="empty">Aucun compte professeur.</div>'}</div><div class="card section"><div class="sectionhead"><div><h2>Comptes élèves</h2><div class="muted">Un compte personnel rattaché à une fiche élève.</div></div></div>${students.map(u=>{const st=db.students.find(x=>String(x.id)===String(u.studentId));return `<div class="message" style="display:flex;justify-content:space-between;gap:12px;align-items:center"><div><b>${esc(st?st.first+' '+st.last:u.name||u.username)}</b><small>@${esc(u.username)} · ${u.active===false?'Désactivé':'Actif'}${st?' · '+esc(cls(st.classId)?.name||'Classe non renseignée'):' · profil introuvable'}</small></div><div class="actions"><button class="btn small" onclick="toggleUser('${u.id}')">${u.active===false?'Activer':'Désactiver'}</button></div></div>`}).join('')||'<div class="empty">Aucun compte élève créé.</div>'}</div><div class="notice section"><b>Confidentialité</b><br>Un compte élève ne reçoit que les informations de sa propre fiche. La messagerie et le Cloud élève restent désactivés le temps de terminer leurs contrôles d’accès.</div>`}
function openStudentAccountEditor(){const linked=new Set(db.users.filter(u=>u.role==='student'&&u.active!==false).map(u=>String(u.studentId)));const available=db.students.filter(st=>!linked.has(String(st.id)));openModal('Créer un compte élève',`<form onsubmit="saveStudentAccount(event)"><div class="form"><div class="field full"><label>Élève *</label><select class="select" name="studentId" required><option value="">Choisir un élève…</option>${available.map(st=>`<option value="${esc(st.id)}">${esc(st.first+' '+st.last)} · ${esc(cls(st.classId)?.name||'Classe non renseignée')}</option>`).join('')}</select></div><div class="field"><label>Identifiant *</label><input class="input" name="username" autocomplete="off" required></div><div class="field"><label>Mot de passe provisoire *</label><input class="input" type="password" name="password" minlength="12" autocomplete="new-password" required></div></div><div class="notice">L’élève devra changer ce mot de passe à sa première connexion. Communique les identifiants directement à la personne concernée.</div><div class="modalfoot"><button type="button" class="btn" onclick="closeModal()">Annuler</button><button class="btn primary" ${available.length?'':'disabled'}>Créer le compte</button></div></form>`);if(!available.length)toast('Tous les élèves ont déjà un compte actif.')}
async function saveStudentAccount(e){e.preventDefault();const f=new FormData(e.target),studentId=String(f.get('studentId')||''),username=String(f.get('username')||'').trim().toLowerCase(),password=String(f.get('password')||'');const st=student(studentId);if(!st)return toast('Élève introuvable.');if(!/^[a-z0-9._-]{3,40}$/.test(username))return toast('Identifiant : 3 à 40 caractères (lettres, chiffres, point, tiret ou underscore).');if(password.length<12)return toast('Le mot de passe provisoire doit contenir au moins 12 caractères.');if(db.users.some(u=>String(u.username||'').toLowerCase()===username))return toast('Cet identifiant est déjà utilisé.');if(db.users.some(u=>u.role==='student'&&String(u.studentId)===studentId))return toast('Cet élève possède déjà un compte.');db.users.push({id:uid(),role:'student',studentId,username,name:st.first+' '+st.last,active:true,mustChangePassword:true,passwordHash:await hashPassword(password)});save();closeModal();render();toast('Compte élève créé. Mot de passe à changer à la première connexion.')}
function openUserEditor(id=''){const u=id?db.users.find(x=>x.id===id):{username:'',name:'',email:'',teacherId:'',active:true};openModal(id?'Modifier le professeur':'Nouveau professeur',`<form onsubmit="saveUser(event,'${id}')"><div class="form"><div class="field"><label>Nom affiché *</label><input class="input" name="name" value="${esc(u.name||'')}" required></div><div class="field"><label>Identifiant *</label><input class="input" name="username" value="${esc(u.username||'')}" required></div><div class="field full"><label>Email</label><input class="input" type="email" name="email" value="${esc(u.email||'')}" placeholder="facultatif"></div><div class="field full"><div class="notice">Une fiche professeur unique sera créée ou mise à jour automatiquement avec ce compte. Vous n’avez plus à gérer un rattachement séparé.</div></div><div class="field full"><label>${id?'Nouveau mot de passe (laisser vide pour conserver)':'Mot de passe *'}</label><input class="input" type="password" name="password" minlength="6" ${id?'':'required'} autocomplete="new-password"></div></div><div class="modalfoot"><button type="button" class="btn" onclick="closeModal()">Annuler</button><button class="btn primary">Enregistrer</button></div></form>`)}
async function saveUser(e,id){e.preventDefault();const f=new FormData(e.target),username=String(f.get('username')||'').trim().toLowerCase(),name=String(f.get('name')||'').trim(),email=String(f.get('email')||'').trim(),pass=String(f.get('password')||'');if(!username||!name)return toast('Le nom et l’identifiant sont obligatoires.');if(db.users.some(u=>String(u.username||'').toLowerCase()===username&&u.id!==id))return toast('Cet identifiant est déjà utilisé.');let u=id?db.users.find(x=>x.id===id):null;if(id&&!u)return toast('Compte introuvable.');let t=u?db.teachers.find(x=>x.id===u.teacherId):null;if(u&&!t){const n=splitPersonName(u.name||name);t={id:uid(),role:'teacher',first:n.first,last:n.last,email:u.email||'',classIds:[],active:u.active!==false};db.teachers.push(t);u.teacherId=t.id}if(!t){const n=splitPersonName(name);t={id:uid(),role:'teacher',first:n.first||name,last:n.last||'',email,classIds:[],active:true};db.teachers.push(t)}const n=splitPersonName(name);t.first=n.first||name;t.last=n.last||'';t.email=email;t.active=u?.active!==false;if(id){u.username=username;u.name=name;u.email=email;u.teacherId=t.id;if(pass)u.passwordHash=await hashPassword(pass)}else db.users.push({id:uid(),role:'teacher',username,name,email,teacherId:t.id,active:true,passwordHash:await hashPassword(pass)});syncTeacherClassLinks();save();closeModal();render();toast(id?'Compte et profil professeur modifiés':'Compte et profil professeur créés')}
function toggleUser(id){const u=db.users.find(x=>x.id===id);if(!u)return;u.active=u.active===false;auditEvent(u.active?'Compte activé':'Compte désactivé',u.name||u.username);save();render();toast(u.active?'Compte activé':'Compte désactivé')}
function settings(){const rooms=Array.isArray(db.settings.rooms)?db.settings.rooms:[];return shell('Configuration','Paramètres','Périodes scolaires, salles, sauvegarde et données.',`<button class="btn primary" onclick="save()">Enregistrer</button>`)+`<div class="grid g2"><div class="card"><div class="sectionhead"><h2>Périodes scolaires</h2></div><div class="form"><div class="field full"><label>Organisation générale</label><select class="select" id="termMode"><option value="trimestres" ${db.settings.termMode==='trimestres'?'selected':''}>Trimestres</option><option value="semestres" ${db.settings.termMode==='semestres'?'selected':''}>Semestres</option></select></div></div><div class="section" id="terms">${db.settings.terms.map(t=>`<div class="card" style="box-shadow:none;margin-bottom:8px"><div class="form"><div class="field"><label>Nom</label><input class="input termName" data-id="${t.id}" value="${esc(t.name)}"></div><div class="field"><label>Début</label><input class="input termStart" data-id="${t.id}" type="date" value="${esc(t.start)}"></div><div class="field"><label>Fin</label><input class="input termEnd" data-id="${t.id}" type="date" value="${esc(t.end)}"></div></div></div>`).join('')}</div><button class="btn" onclick="addTerm()">+ Ajouter une période</button><button class="btn primary" style="margin-left:6px" onclick="saveTerms()">Enregistrer les périodes</button></div><div class="card"><div class="sectionhead"><h2>Salles & ressources</h2><button class="btn small" onclick="addPlannerRoom()">+ Salle</button></div><div class="notice">Ces informations servent au Planner pour éviter les salles trop petites ou incompatibles avec un besoin matériel.</div><div class="section">${rooms.map((r,i)=>`<div class="metric" style="margin-bottom:8px"><b>${esc(r.name)}</b><span class="muted">${Number(r.capacity||0)||'?'} places${Array.isArray(r.equipment)&&r.equipment.length?' · '+esc(r.equipment.join(', ')):''}</span><button class="btn small" style="float:right" onclick="editPlannerRoom(${i})">Modifier</button></div>`).join('')||'<div class="empty">Aucune salle configurée. Le Planner peut quand même travailler avec les salles déjà présentes dans l’EDT.</div>'}</div></div><div class="card"><div class="sectionhead"><h2>Données</h2></div><div class="notice">Le programme et les données sont physiquement séparés : <b>index.html</b> contient l’interface, <b>data/maclasse.json</b> contient vos données. Les fichiers ajoutés sont dans <b>data/uploads/</b>. À chaque modification enregistrée, MaClasse conserve automatiquement jusqu’à 15 copies de sécurité dans <b>data/backups/</b>.</div><div class="section"><button class="btn" onclick="downloadBackup()">Exporter une copie JSON</button><label class="btn" style="display:inline-block">Importer une copie JSON<input class="hide" type="file" accept=".json" onchange="restoreBackup(this.files[0]);this.value=''"></label>${authCanManage()?`<label class="btn" style="display:inline-block">Restaurer une archive complète ZIP<input class="hide" type="file" accept=".zip,application/zip" onchange="restoreZipBackup(this.files[0]);this.value=''"></label>`:''}</div><div class="section"><button class="btn danger" onclick="resetData()">Réinitialiser toutes les données</button></div><div class="section"><h3>État du stockage</h3><p class="muted">${db.students.length} élèves · ${db.classes.length} classes · ${db.evaluations.length} évaluations · ${db.lessons.length} séances · ${db.conversations.length} conversations.</p><p class="muted">Schéma de données : compatible V19.x · Journal local : ${(db.auditLog||[]).length} événement(s).</p><button class="btn small" onclick="downloadAuditLog()">Exporter l’historique</button><button class="btn small" style="margin-left:6px" onclick="runDataCheck()">Vérifier la cohérence des données</button></div></div></div>`}
async function restoreZipBackup(file){
 if(!file)return;
 if(!authCanManage())return toast('La restauration complète est réservée à la direction.');
 if(file.size>100*1024*1024)return toast('Archive trop volumineuse (100 Mo maximum).');
 confirmModal('Cette opération remplacera la base MaClasse ET les fichiers téléversés par le contenu de cette archive. Une sauvegarde complète de l’état actuel sera créée avant la restauration.','Restaurer l’archive complète',async()=>{
  const button=document.querySelector('.modalfoot .btn.primary');if(button){button.disabled=true;button.textContent='Restauration…'}
  try{
   const response=await fetch('/api/backup/restore',{method:'POST',headers:{'Content-Type':'application/zip'},body:file});
   let result={};try{result=await response.json()}catch{}
   if(!response.ok)throw Error(result.error||'Restauration refusée.');
   const revision=response.headers.get('X-MaClasse-Revision');if(revision)dataRevision=revision;
   db=await api('/api/data');normalize();closeModal();render();
   const stats=result.restored||{};toast(`Restauration terminée · ${stats.classes||0} classe(s), ${stats.students||0} élève(s), ${stats.files||0} fichier(s)`);
  }catch(error){if(button){button.disabled=false;button.textContent='Confirmer'}toast(error?.message||'Restauration impossible. Les données actuelles sont conservées.')}
 });
}
function addPlannerRoom(){openModal('Nouvelle salle',`<form onsubmit="savePlannerRoom(event)"><div class="form"><div class="field"><label>Nom *</label><input class="input" name="name" required placeholder="B204"></div><div class="field"><label>Capacité</label><input class="input" name="capacity" type="number" min="0" value="30"></div><div class="field full"><label>Équipements</label><input class="input" name="equipment" placeholder="ordinateurs, vidéoprojecteur"></div></div><div class="modalfoot"><button type="button" class="btn" onclick="closeModal()">Annuler</button><button class="btn primary">Enregistrer</button></div></form>`)}
function editPlannerRoom(i){const r=db.settings.rooms[i];if(!r)return;openModal('Modifier la salle',`<form onsubmit="savePlannerRoom(event,${i})"><div class="form"><div class="field"><label>Nom *</label><input class="input" name="name" value="${esc(r.name)}" required></div><div class="field"><label>Capacité</label><input class="input" name="capacity" type="number" min="0" value="${Number(r.capacity||0)}"></div><div class="field full"><label>Équipements</label><input class="input" name="equipment" value="${esc((r.equipment||[]).join(', '))}"></div></div><div class="modalfoot"><button type="button" class="btn danger" onclick="deletePlannerRoom(${i})">Supprimer</button><button type="button" class="btn" onclick="closeModal()">Annuler</button><button class="btn primary">Enregistrer</button></div></form>`)}
function savePlannerRoom(e,i=null){e.preventDefault();const o=Object.fromEntries(new FormData(e.target));const r={id:i===null?uid():(db.settings.rooms[i]?.id||uid()),name:String(o.name||'').trim(),capacity:Math.max(0,Number(o.capacity||0)),equipment:String(o.equipment||'').split(',').map(x=>x.trim()).filter(Boolean)};if(!r.name)return;db.settings.rooms??=[];if(i===null)db.settings.rooms.push(r);else db.settings.rooms[i]=r;save();closeModal();render();toast('Salle enregistrée')}
function deletePlannerRoom(i){db.settings.rooms.splice(i,1);save();closeModal();render();toast('Salle supprimée')}

function saveTerms(){db.settings.termMode=$('#termMode').value;db.settings.terms.forEach(t=>{t.name=document.querySelector(`.termName[data-id="${t.id}"]`).value;t.start=document.querySelector(`.termStart[data-id="${t.id}"]`).value;t.end=document.querySelector(`.termEnd[data-id="${t.id}"]`).value});save();toast('Périodes enregistrées')}function addTerm(){db.settings.terms.push({id:uid(),name:'Nouvelle période',start:'',end:''});render()}function downloadBackup(){
 const stamp=new Date().toISOString().replace(/[:.]/g,'-');
 const a=document.createElement('a');
 a.href=URL.createObjectURL(new Blob([JSON.stringify(db,null,2)],{type:'application/json'}));
 a.download=`maclasse-sauvegarde-${stamp}.json`;a.click();
 setTimeout(()=>URL.revokeObjectURL(a.href),1000);
}
/* V19.7: valider et confirmer une restauration avant tout remplacement des données. */
/* V19.8: utiliser l’identité du compte enseignant actif pour la messagerie. */
/* V19.9: maintenir les affectations de groupes cohérentes lors de l’édition d’une classe. */
function validateBackupData(candidate){
 if(!candidate||typeof candidate!=='object'||Array.isArray(candidate))throw Error('La racine du fichier doit être un objet JSON.');
 if(!candidate.settings||typeof candidate.settings!=='object'||Array.isArray(candidate.settings))throw Error('La section settings est absente ou invalide.');
 const arrays=['classes','students','teachers','subjects','schedule','lessons','evaluations','attendance','bulletins','attachments','submissions','conversations','cloudItems','mailFolders','users','notifications','auditLog'];
 const present=arrays.filter(k=>Object.prototype.hasOwnProperty.call(candidate,k));
 if(!present.includes('classes')||!present.includes('students'))throw Error('Ce fichier ne ressemble pas à une sauvegarde MaClasse (classes/élèves manquants).');
 for(const key of present)if(!Array.isArray(candidate[key]))throw Error(`La section « ${key} » doit être une liste.`);
 return true;
}
function restoreBackup(file){
 if(!file)return;
 const r=new FileReader();
 r.onerror=()=>toast('Lecture impossible. Vérifiez le fichier puis réessayez.');
 r.onload=()=>{
  let candidate;
  try{candidate=JSON.parse(r.result);validateBackupData(candidate)}
  catch(e){toast('Sauvegarde refusée : '+(e?.message||'fichier JSON invalide'));return}
  confirmModal('La restauration remplacera les données actuellement ouvertes par celles du fichier sélectionné. Une copie de sécurité sera conservée par MaClasse si la sauvegarde serveur aboutit. Vérifiez que vous avez choisi le bon fichier.', 'Restaurer cette sauvegarde', async()=>{
   const previous=db;clearTimeout(saveTimer);
   try{
    db=candidate;normalize();
    auditEvent('Sauvegarde restaurée',file.name||'Fichier JSON');
    await api('/api/save',{method:'POST',headers:{'Content-Type':'application/json','If-Match':dataRevision||''},body:JSON.stringify(db)});
    render();toast('Sauvegarde restaurée avec succès');
   }catch(e){db=previous;render();toast('Restauration échouée : les données en mémoire ont été rétablies. Vérifiez le serveur et réessayez.')}
  });
 };
 r.readAsText(file);
}
function runDataCheck(){
 const issues=[];
 const collections=['classes','students','teachers','subjects','schedule','lessons','evaluations','attendance','bulletins','submissions','conversations','cloudItems','users'];
 const ids={};
 for(const key of collections){
  const rows=Array.isArray(db[key])?db[key]:[];const seen=new Set();
  for(const row of rows){if(!row||!row.id){issues.push(`${key} : enregistrement sans identifiant.`);continue}if(seen.has(row.id))issues.push(`Identifiant en double dans ${key} : ${row.id}`);seen.add(row.id)}
  ids[key]=seen;
 }
 const ref=(ok,msg)=>{if(!ok)issues.push(msg)};
 for(const st of db.students||[])if(st.classId)ref(ids.classes.has(st.classId),`Élève « ${(st.first||'')+' '+(st.last||'')} » : classe introuvable (${st.classId}).`);
 for(const slot of db.schedule||[])if(slot.classId)ref(ids.classes.has(slot.classId),`Créneau EDT « ${slot.subject||slot.id} » : classe introuvable (${slot.classId}).`);
 for(const lesson of db.lessons||[]){
  if(lesson.classId)ref(ids.classes.has(lesson.classId),`Séance « ${lesson.title||lesson.id} » : classe introuvable (${lesson.classId}).`);
  if(lesson.scheduleId)ref(ids.schedule.has(lesson.scheduleId),`Séance « ${lesson.title||lesson.id} » : créneau EDT introuvable (${lesson.scheduleId}).`);
 }
 for(const ev of db.evaluations||[]){
  if(ev.classId)ref(ids.classes.has(ev.classId),`Évaluation « ${ev.title||ev.id} » : classe introuvable (${ev.classId}).`);
  for(const grade of ev.grades||[])if(grade.studentId)ref(ids.students.has(grade.studentId),`Évaluation « ${ev.title||ev.id} » : élève introuvable (${grade.studentId}).`);
 }
 for(const att of db.attendance||[]){
  if(att.classId)ref(ids.classes.has(att.classId),`Appel du ${att.date||'date inconnue'} : classe introuvable (${att.classId}).`);
  if(att.slotId)ref(ids.schedule.has(att.slotId),`Appel du ${att.date||'date inconnue'} : créneau EDT introuvable (${att.slotId}).`);
  for(const row of att.rows||[])ref(ids.students.has(row.studentId),`Appel du ${att.date||'date inconnue'} : élève introuvable (${row.studentId||'identifiant vide'}).`);
 }
 for(const sub of db.submissions||[]){if(sub.lessonId)ref(ids.lessons.has(sub.lessonId),`Rendu ${sub.id||''} : séance introuvable (${sub.lessonId}).`);if(sub.studentId)ref(ids.students.has(sub.studentId),`Rendu ${sub.id||''} : élève introuvable (${sub.studentId}).`)}
 for(const teacher of db.teachers||[]){if(teacher.userId)ref((db.users||[]).some(u=>u.id===teacher.userId),`Professeur « ${teacher.first||''} ${teacher.last||''} » : compte utilisateur introuvable (${teacher.userId}).`);for(const cid of teacher.classIds||[])ref(ids.classes.has(cid),`Professeur « ${teacher.first||''} ${teacher.last||''} » : classe liée introuvable (${cid}).`)}
 for(const user of db.users||[]){if(user.role==='teacher'&&user.teacherId)ref(ids.teachers.has(user.teacherId),`Compte « ${user.username||user.id} » : profil professeur introuvable (${user.teacherId}).`);if(user.role==='student'&&user.studentId)ref(ids.students.has(user.studentId),`Compte « ${user.username||user.id} » : profil élève introuvable (${user.studentId}).`)}
 for(const item of db.cloudItems||[])if(item.parentId)ref(ids.cloudItems.has(item.parentId),`Élément documentaire « ${item.name||item.id} » : dossier parent introuvable (${item.parentId}).`);
 const body=issues.length?`<div class="notice warn">${issues.length} point(s) à vérifier. Ce contrôle ne modifie aucune donnée.</div><div class="section" style="max-height:48vh;overflow:auto">${issues.map(x=>`<div class="notice" style="margin-bottom:7px">${esc(x)}</div>`).join('')}</div>`:'<div class="notice">Aucune incohérence détectée dans les contrôles effectués. Cela ne remplace pas une vérification complète de tous les modules.</div>';
 openModal('Vérification des données',`${body}<div class="modalfoot"><button class="btn primary" onclick="closeModal()">Fermer</button></div>`);
}
function confirmModal(message,yesText='Supprimer',onYes=()=>{}){openModal('Confirmation',`<div class="notice warn">${esc(message)}</div><div class="modalfoot"><button class="btn" type="button" onclick="closeModal()">Annuler</button><button class="btn danger" type="button" id="confirmYes">${esc(yesText)}</button></div>`);$('#confirmYes').onclick=()=>{closeModal();onYes()}}
function resetData(){confirmModal('Toutes les classes, élèves, emplois du temps, séances, évaluations, appels, bulletins et messages seront supprimés.', 'Tout effacer', async()=>{try{const result=await api('/api/reset');clearTimeout(saveTimer);db=blank();normalize();render();toast(result?.backup?'Données effacées · copie de sécurité créée':'Données effacées')}catch(e){toast(e?.message||'Réinitialisation refusée : aucune donnée effacée')}})}
function openModal(title,body){$('#modal').innerHTML=`<div class="modalhead"><div><h2>${title}</h2></div><button class="close" onclick="closeModal()">×</button></div>${body}`;$('#modalback').classList.add('open')}function closeModal(){$('#modalback').classList.remove('open');attDraft=null}function toast(t){const x=$('#toast');x.textContent=t;x.classList.add('show');clearTimeout(x._t);x._t=setTimeout(()=>x.classList.remove('show'),1600)}$('#modalback').addEventListener('click',e=>{if(e.target.id==='modalback')closeModal()});function normalize(){const b=blank();if(!db||typeof db!=='object')db=blank();db.settings??={};for(const k of Object.keys(b))if(db[k]===undefined||db[k]===null)db[k]=b[k];db.students=Array.isArray(db.students)?db.students.filter(Boolean):[];db.classes=Array.isArray(db.classes)?db.classes.filter(Boolean):[];db.lessons=Array.isArray(db.lessons)?db.lessons.filter(Boolean):[];db.evaluations=Array.isArray(db.evaluations)?db.evaluations.filter(Boolean):[];db.attendance=Array.isArray(db.attendance)?db.attendance.filter(Boolean):[];db.submissions=Array.isArray(db.submissions)?db.submissions.filter(Boolean):[];for(const k of ['schedule','bulletins','attachments','conversations','teachers','subjects','cloudItems','mailFolders','users','notifications','auditLog','messages'])db[k]=Array.isArray(db[k])?db[k]:[];if(!db.teachers.length)db.teachers=[{id:'teacher-local',role:'teacher',first:'Enseignant',last:'MaClasse',email:'',classIds:db.classes.map(c=>c.id),active:true}];db.classes.forEach(c=>{c.teacherIds??=['teacher-local'];c.doubleLevel=!!c.doubleLevel;c.levels=Array.isArray(c.levels)?c.levels:(c.doubleLevel&&c.level?String(c.level).split('/').map(x=>x.trim()).filter(Boolean):[]);c.groups=Array.isArray(c.groups)?c.groups:[]});db.schedule.forEach(x=>{x.teacherId??='';x.courseId=[x.classId,x.subject,x.teacherId||'',x.group||''].join('|');x.color??='';x.pattern??='none';x.endTime??=addHour(x.time||'08:00');x.recurrence??='weekly';x.exceptions=Array.isArray(x.exceptions)?x.exceptions:[];x.overrides??={}});db.settings??={};db.settings.rooms=Array.isArray(db.settings.rooms)?db.settings.rooms:[];if(!db.settings.terms?.length)db.settings.terms=b.settings.terms;db.lessons.forEach(l=>{l.files??=[];if(l.homework){l.homework.files??=[];l.homework.submissionFolder??=l.homework.requiresSubmission?{id:uid(),name:'Rendus — '+(l.homework.title||'Travail'),createdAt:new Date().toISOString()}:null}});db.classes.forEach(c=>{c.attendanceMode??='hour';c.periodMode??=db.settings.termMode;c.name??='Classe';c.level??='';c.group??='';c.principalTeacherId??=''});syncTeacherClassLinks();db.evaluations.forEach(e=>{e.grades??=[];e.coefficient=Number(e.coefficient||1);e.competencies=Array.isArray(e.competencies)?e.competencies.filter(x=>typeof x==='string'&&x.trim()).map(x=>x.trim()):[];e.grades.forEach(g=>{g.competencyRatings=g.competencyRatings&&typeof g.competencyRatings==='object'&&!Array.isArray(g.competencyRatings)?g.competencyRatings:{}})});db.attendance.forEach(a=>{a.mode??=cls(a.classId)?.attendanceMode||'halfday';a.slotId??='';a.partOfDay??='';a.time??='';a.rows??=[]});db.bulletins.forEach(b=>{b.subjectData??={};b.overall??=''});window.cloudPath=Array.isArray(window.cloudPath)?window.cloudPath:[];window.cloudView??='grid';db.cloudItems.forEach(x=>{x.shares=Array.isArray(x.shares)?x.shares:[];x.space??=(x.classId?'class':'personal');x.ownerId??=(x.space==='personal'?'teacher-local':'');x.parentId=x.parentId||'';x.group??='';x.createdAt??=new Date().toISOString()});db.cloudItems.forEach(x=>{if(x.parentId){const p=db.cloudItems.find(q=>q.id===x.parentId);if(!p||p.space!==x.space||String(p.classId||'')!==String(x.classId||'')||String(p.group||'')!==String(x.group||''))x.parentId=''}});db.submissions.forEach(x=>{x.corrected??=false;x.correctionComment??='';x.status??=(x.submittedAt?'submitted':'draft');if(!Array.isArray(x.files))x.files=x.file?[x.file]:[];x.files=x.files.filter(Boolean);x.file??=x.files[0]||null;x.correctionFiles??=[]});db.evaluationTemplates=Array.isArray(db.evaluationTemplates)?db.evaluationTemplates.filter(t=>t&&typeof t==='object'&&Array.isArray(t.competencies)):[];db.evaluationCriteriaLibrary=Array.isArray(db.evaluationCriteriaLibrary)?db.evaluationCriteriaLibrary.filter(c=>c&&c.name):[];db.evaluationTemplates.forEach(t=>(t.criteria||[]).forEach(c=>{if(!db.evaluationCriteriaLibrary.some(x=>x.name===c.name&&Number(x.maxPoints)===Math.max(0,...(c.levels||[0]).map(Number))))db.evaluationCriteriaLibrary.push({...c,maxPoints:Math.max(0,...(c.levels||[0]).map(Number))})}));db.competencyLibrary=Array.isArray(db.competencyLibrary)?[...new Set(db.competencyLibrary.filter(x=>typeof x==='string'&&x.trim()).map(x=>x.trim()))]:[];db.evaluations.forEach(e=>(e.competencies||[]).forEach(c=>{if(!db.competencyLibrary.includes(c))db.competencyLibrary.push(c)}));db.messages??=[];db.messages=[];migrateTeacherIdentityV194()}

function v10MissingGrades(){return db.evaluations.reduce((n,e)=>n+(e.grades||[]).filter(g=>g.value==='').length,0)}
function v10Upcoming(){const today=iso(new Date());return db.lessons.filter(l=>l.homework?.due&&l.homework.due>=today).sort((a,b)=>a.homework.due.localeCompare(b.homework.due))}
function v10AttendanceStats(){let abs=0,late=0,just=0;for(const x of db.attendance)for(const r of x.rows||[]){if(r.status==='absent'){abs++;if(r.justified)just++}if(r.status==='retard')late++}return {calls:db.attendance.length,abs,late,just}}
function v10RecentEvaluations(){return [...db.evaluations].sort((a,b)=>(b.date||'').localeCompare(a.date||'')).slice(0,5)}
function dashboard(){const today=new Date(),ods=dayOcc(today),todo=v10Upcoming(),stats=v10AttendanceStats(),missing=v10MissingGrades(),submissions=db.submissions.length,recent=v10RecentEvaluations();return shell('Carnet de bord','Vue d’ensemble de votre activité pédagogique','Un centre de pilotage : cours, évaluations, rendus, appels et échéances au même endroit.',`<button class="btn primary" onclick="openAttendance()">Appel</button>`)+`<div class="v10hero"><div class="card focusCard"><div class="eyebrow" style="color:#bcd7ff">Aujourd’hui</div><h2 style="color:#fff;margin-top:5px">${esc(nowLabel())}</h2><div class="muted" style="margin-top:5px">${ods.length} créneau(x) prévu(s) · ${todo.length} travail(aux) à venir</div><div class="gradeStats" style="margin-top:18px"><div class="metric"><small>Cours aujourd’hui</small><b>${ods.length}</b></div><div class="metric"><small>Notes à saisir</small><b>${missing}</b></div><div class="metric"><small>Rendus</small><b>${submissions}</b></div><div class="metric"><small>Nouveaux mails</small><b>${unreadConversationCount('teacher')}</b></div></div></div><div class="card"><div class="sectionhead"><div><h2>À surveiller</h2><div class="muted">Les actions qui demandent une intervention</div></div></div>${missing?`<div class="alertRow"><span class="alertDot red"></span><div><b>${missing} note(s) manquante(s)</b><small class="muted">dans vos évaluations</small></div><button class="btn small" onclick="go('evaluations')">Saisir</button></div>`:''}${todo.length?`<div class="alertRow"><span class="alertDot"></span><div><b>${todo.length} travail(aux) à venir</b><small class="muted">prochaine échéance : ${fmtDate(todo[0].homework.due)}</small></div><button class="btn small" onclick="go('lessons')">Voir</button></div>`:''}${stats.abs?`<div class="alertRow"><span class="alertDot blue"></span><div><b>${stats.abs} absence(s) enregistrée(s)</b><small class="muted">${stats.just} justifiée(s)</small></div><button class="btn small" onclick="go('attendance')">Suivre</button></div>`:''}${!missing&&!todo.length&&!stats.abs?'<div class="empty" style="padding:18px">Rien d’urgent pour le moment.</div>':''}</div></div><div class="sectionTitle"><div><h2>Accès rapides</h2><div class="muted">Les espaces les plus utilisés</div></div></div><div class="quickGrid"><button class="btn quickAction" onclick="openAttendance()"><span class="qicon">☑</span><span><strong>Faire l’appel</strong><small>${stats.calls} appel(s) enregistré(s)</small></span></button><button class="btn quickAction" onclick="openEvaluation()"><span class="qicon">✓</span><span><strong>Nouvelle évaluation</strong><small>Saisir des notes et compétences</small></span></button><button class="btn quickAction" onclick="go('students')"><span class="qicon">♙</span><span><strong>Fiches élèves</strong><small>${db.students.length} élève(s)</small></span></button><button class="btn quickAction" onclick="go('schedule')"><span class="qicon">▦</span><span><strong>Emploi du temps</strong><small>Consulter la semaine</small></span></button></div><div class="card section"><div class="sectionhead"><div><h2>Les cours d’aujourd’hui</h2><div class="muted">Accès rapide aux créneaux prévus</div></div><button class="btn small" onclick="go('schedule')">Emploi du temps</button></div>${ods.map(o=>`<div class="alertRow"><span class="alertDot blue"></span><div><b>${esc(o.time||'')}–${esc(o.endTime||'')} · ${esc(o.subject||'Cours')}</b><small class="muted">${esc(cls(o.classId)?.name||'Classe non précisée')}${o.room?' · '+esc(o.room):''}</small></div><button class="btn small" onclick="go('lessons')">Séances</button></div>`).join('')||'<div class="empty" style="padding:14px">Aucun créneau prévu aujourd’hui.</div>'}</div><div class="grid g2 section"><div class="card"><div class="sectionhead"><div><h2>Prochains travaux</h2><div class="muted">Classés par date de rendu</div></div><button class="btn small" onclick="go('lessons')">Tout voir</button></div>${todo.slice(0,6).map(l=>`<div class="message"><b>${esc(l.homework.title||'Travail')}</b><small>${esc(cls(l.classId)?.name||'')} · ${esc(l.subject||'')} · à rendre le ${fmtDate(l.homework.due)}</small></div>`).join('')||'<div class="empty">Aucun travail à venir.</div>'}</div><div class="card"><div class="sectionhead"><div><h2>Dernières évaluations</h2><div class="muted">Accès direct au tableau de notes</div></div><button class="btn small" onclick="go('evaluations')">Ouvrir</button></div>${recent.map(e=>`<div class="message"><b>${esc(e.title)}</b><small>${esc(cls(e.classId)?.name||'')} · ${esc(e.subject||'')} · ${fmtDate(e.date)} · coef. ${e.coefficient||1}</small></div>`).join('')||'<div class="empty">Aucune évaluation.</div>'}</div></div><div class="card section"><div class="sectionhead"><div><h2>📬 Derniers mails</h2><div class="muted">Les derniers messages reçus</div></div><button class="btn small" onclick="go('messages')">Voir la boîte</button></div>${window.mailV2104Recent('teacher').slice(0,5).map(m=>`<button class="mailHomeRow" onclick="window.mailV2Selected='${m.id}';window.mailV2Folder='inbox';go('messages')"><span class="mailHomeUnread ${m.unread?'on':''}"></span><span class="grow"><b>${esc(m.sender?.name||'Message scolaire')}</b><small>${esc(m.subject||'(Sans objet)')} · ${messageDateTime(m.sentAt)}</small></span><span>›</span></button>`).join('')||'<div class="empty">Aucun mail récent.</div>'}</div><div class="card section"><div class="sectionhead"><div><h2>Vue statistique</h2><div class="muted">Données de suivi de l’année</div></div></div><div class="attendanceStats"><div class="statMini"><small>Élèves</small><b>${db.students.length}</b></div><div class="statMini"><small>Classes</small><b>${db.classes.length}</b></div><div class="statMini"><small>Absences</small><b>${stats.abs}</b></div><div class="statMini"><small>Retards</small><b>${stats.late}</b></div><div class="statMini"><small>Justifiées</small><b>${stats.just}</b></div></div></div>`}
function gradebookSubjects(classId){return [...new Set(db.evaluations.filter(e=>e.classId===classId).map(e=>e.subject).filter(Boolean))].sort((a,b)=>a.localeCompare(b))}
function gradebookEvaluations(classId,subject){return db.evaluations.filter(e=>e.classId===classId&&(!subject||e.subject===subject)).sort((a,b)=>(a.date||'').localeCompare(b.date||''))}
function gradebookMatrix(classId,subject){const es=gradebookEvaluations(classId,subject),ss=db.students.filter(s=>s.classId===classId);if(!classId)return '<div class="empty">Choisis une classe pour afficher le carnet de notes.</div>';if(!ss.length)return '<div class="notice warn">Cette classe ne contient aucun élève.</div>';if(!es.length)return '<div class="empty">Aucune évaluation pour cette sélection. Crée la première avec « Nouvelle évaluation ».</div>';return `<div class="tablewrap"><table class="table gradebookMatrix"><thead><tr><th>Élève</th>${es.map(e=>`<th title="${esc(e.title)}">${esc((e.title||'Éval.').slice(0,16))}<small style="display:block;color:var(--muted)">${fmtDate(e.date)} · ×${e.coefficient||1}</small></th>`).join('')}<th>Moyenne</th></tr></thead><tbody>${ss.map(s=>{const vals=es.map(e=>e.grades?.find(g=>g.studentId===s.id)?.value??'');const avg=weightedAverageForEvaluations(es,[s.id]);return `<tr><td class="gradebookName"><b>${esc(s.last.toUpperCase())} ${esc(s.first)}</b><small>${esc(s.group||'Classe entière')}</small></td>${es.map((e,i)=>{const gr=e.grades?.find(g=>g.studentId===s.id),ratings=gr?.competencyRatings||{},rated=(e.competencies||[]).filter(c=>Number(ratings[c])>=1&&Number(ratings[c])<=4),max=(e.criteria||[]).reduce((n,c)=>n+Math.max(0,...(c.levels||[0]).map(Number)),0),sum=(e.criteria||[]).reduce((n,c)=>n+(Number(gr?.criterionScores?.[c.id])||0),0);return `<td class="gradeCell ${vals[i]===''?'empty':''}"><input class="input" type="number" min="0" max="20" step="0.01" value="${esc(vals[i])}" placeholder="—" onchange="setGrade('${e.id}','${s.id}',this.value);v10RefreshGradebook()">${max?`<small class="muted" style="display:block;margin-top:3px">${sum} / ${max} pts</small>`:''}${rated.length?`<div class="gradebookCompetencies" style="display:flex;flex-wrap:wrap;gap:3px;margin-top:4px">${rated.map(c=>{const v=Number(ratings[c]),col={1:'#c62828',2:'#d6a400',3:'#16803c',4:'#1769d2'}[v];return `<span title="${esc(c)} — ${{1:'Insuffisant',2:'Fragile',3:'Bien',4:'Très bien'}[v]}" aria-label="${esc(c)} : niveau ${v}" style="display:inline-block;width:9px;height:9px;border-radius:50%;background:${col}"></span>`}).join('')}</div>`:''}</td>`}).join('')}<td><b>${avg==='—'?'—':avg+' /20'}</b></td></tr>`}).join('')}</tbody></table></div>`}
function gradebookSummary(classId,subject){if(!classId)return '';const es=gradebookEvaluations(classId,subject),ss=db.students.filter(s=>s.classId===classId),avg=weightedAverageForEvaluations(es,ss.map(s=>s.id)),missing=es.reduce((n,e)=>n+(e.grades||[]).filter(g=>ss.some(s=>s.id===g.studentId)&&g.value==='').length,0);return `<div class="gradeStats"><div class="metric"><small>Moyenne de la sélection</small><b>${avg} /20</b></div><div class="metric"><small>Élèves</small><b>${ss.length}</b></div><div class="metric"><small>Évaluations</small><b>${es.length}</b></div><div class="metric"><small>Notes manquantes</small><b>${missing}</b></div></div>`}
function v10RefreshGradebook(){const c=$('#gradebookClass')?.value||'',sub=$('#gradebookSubject')?.value||'';if($('#gradebookSummary'))$('#gradebookSummary').innerHTML=gradebookSummary(c,sub);if($('#gradebookMatrix'))$('#gradebookMatrix').innerHTML=gradebookMatrix(c,sub)}
function v10GradebookClassChanged(){const c=$('#gradebookClass')?.value||'',sel=$('#gradebookSubject');if(sel)sel.innerHTML='<option value="">Toutes les matières</option>'+gradebookSubjects(c).map(x=>`<option>${esc(x)}</option>`).join('');v10RefreshGradebook()}
function evaluations(){const first=db.classes[0]?.id||'',subjects=gradebookSubjects(first);return shell('Évaluations','Carnet de notes','Tableau de classe : toutes les évaluations en colonnes, coefficients et moyennes pondérées.',`<button class="btn primary" onclick="openEvaluation()">+ Nouvelle évaluation</button>`)+`<div class="card"><div class="gradebookToolbar"><div class="field" style="min-width:180px;flex:1"><label>Classe</label><select class="select" id="gradebookClass" onchange="v10GradebookClassChanged()"><option value="">Choisir une classe</option>${db.classes.map(c=>`<option value="${c.id}" ${c.id===first?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field" style="min-width:180px;flex:1"><label>Matière</label><select class="select" id="gradebookSubject" onchange="v10RefreshGradebook()"><option value="">Toutes les matières</option>${subjects.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div><button class="btn" onclick="openEvaluation()">Créer une évaluation</button></div><div id="gradebookSummary" class="section">${gradebookSummary(first,'')}</div><div id="gradebookMatrix" class="section">${gradebookMatrix(first,'')}</div></div><div class="card section"><div class="sectionhead"><div><h2>Évaluations enregistrées</h2><div class="muted">Modifier une évaluation ouvre son tableau complet.</div></div></div>${evalList()}</div>`}
function attendanceSummaryForClass(classId){const ss=db.students.filter(s=>s.classId===classId),map={};for(const s of ss)map[s.id]={abs:0,late:0,just:0};for(const a of db.attendance.filter(a=>a.classId===classId))for(const r of a.rows||[]){if(!map[r.studentId])continue;if(r.status==='absent'){map[r.studentId].abs++;if(r.justified)map[r.studentId].just++}if(r.status==='retard')map[r.studentId].late++}return map}
function attendance(){const stats=v10AttendanceStats();return shell('Vie de classe','Appels','Présences, absences, retards et justificatifs avec historique et synthèse par classe.',`<button class="btn primary" onclick="openAttendance()">+ Nouvel appel</button><button class="btn" onclick="go('attendanceFollowup')">Suivi des absences et retards</button><button class="btn" onclick="exportAttendanceCsv()">Exporter CSV</button>`)+`<div class="card"><div class="attendanceStats"><div class="statMini"><small>Appels</small><b>${stats.calls}</b></div><div class="statMini"><small>Absences</small><b>${stats.abs}</b></div><div class="statMini"><small>Retards</small><b>${stats.late}</b></div><div class="statMini"><small>Justifiées</small><b>${stats.just}</b></div><div class="statMini"><small>Non justifiées</small><b>${stats.abs-stats.just}</b></div></div></div><div class="card section"><div class="sectionhead"><div><h2>Historique des appels</h2><div class="muted">Clique sur un appel pour modifier les statuts et motifs.</div></div></div><div class="tablewrap"><table class="table"><thead><tr><th>Date</th><th>Classe</th><th>Créneau</th><th>Mode</th><th>Absents</th><th>Retards</th><th>Non justifiées</th><th></th></tr></thead><tbody>${db.attendance.sort((a,b)=>b.date.localeCompare(a.date)).map(a=>{const rows=a.rows||[];return `<tr><td>${fmtDate(a.date)}</td><td><b>${esc(cls(a.classId)?.name||'')}</b></td><td>${attendanceSlotLabel(a)}</td><td><span class="pill blue">${a.mode==='halfday'?'Demi-journée':'Par cours'}</span></td><td>${rows.filter(x=>x.status==='absent').length}</td><td>${rows.filter(x=>x.status==='retard').length}</td><td>${rows.filter(x=>x.status==='absent'&&!x.justified).length}</td><td><button class="btn small" onclick="openAttendance('${a.id}')">Ouvrir</button></td></tr>`}).join('')||'<tr><td colspan="8"><div class="empty">Aucun appel enregistré.</div></td></tr>'}</tbody></table></div></div><div class="grid g2 section">${db.classes.map(c=>{const m=attendanceSummaryForClass(c.id),ss=db.students.filter(s=>s.classId===c.id);return `<div class="card"><div class="sectionhead"><div><h3>${esc(c.name)}</h3><div class="muted">Suivi individuel</div></div><span class="pill blue">${ss.length} élève(s)</span></div><div class="tablewrap"><table class="table"><thead><tr><th>Élève</th><th>A</th><th>R</th><th>Just.</th></tr></thead><tbody>${ss.map(s=>`<tr><td>${esc(s.last.toUpperCase())} ${esc(s.first)}</td><td>${m[s.id]?.abs||0}</td><td>${m[s.id]?.late||0}</td><td>${m[s.id]?.just||0}</td></tr>`).join('')||'<tr><td colspan="4">Aucun élève</td></tr>'}</tbody></table></div></div>`}).join('')}</div>`}
function bulletinPrintSheet(b){const s=student(b.studentId),c=cls(b.classId),t=term(b.termId),subjects=bulletinSubjectsForClass(b.classId);return `<div class="printSheet"><header class="printHeader"><div class="printBrand">MA CLASSE <span>· BULLETIN SCOLAIRE</span></div><div class="printPeriod">${esc(t?.name||'Période')}</div></header><section class="printIdentity"><div><small>ÉLÈVE</small><h1>${esc(s?.first||'')} ${esc(s?.last||'')}</h1></div><div><small>CLASSE</small><b>${esc(c?.name||'—')}</b></div><div><small>PÉRIODE</small><b>${esc(t?.name||'—')}</b></div></section><section class="printAverage"><small>MOYENNE GÉNÉRALE</small><strong>${v101StudentAverage(b.studentId,b.termId)} <em>/ 20</em></strong><span>Moyenne de classe : ${classAverageForBulletin(b.classId,b.termId)} /20</span></section><h2>Résultats par matière</h2><table class="printSubjects"><thead><tr><th>Matière</th><th class="printGrade">Moyenne /20</th><th>Appréciation de l’enseignant</th></tr></thead><tbody>${subjects.map(sub=>`<tr><td><b>${esc(sub)}</b></td><td class="printGrade">${subjectAverage(b.studentId,b.classId,sub,b.termId)}</td><td class="printComment">${esc(b.subjectData?.[sub]?.comment||'')}</td></tr>`).join('')}</tbody></table><section class="printOverall"><h2>Appréciation générale</h2><div class="printComment">${esc(b.overall||'')}</div></section>${bulletinCompetencyBlock(b)}<footer class="printFooter">Document généré avec MaClasse${b.published?` · Bulletin publié le ${fmtDate(b.publishedAt)}`:''}</footer></div>`}
function openBulletin(id=null){let b=id?db.bulletins.find(x=>x.id===id):{studentId:'',classId:'',termId:db.settings.terms[0]?.id||'',subjectData:{},overall:''};if(!id)return openModal('Créer un bulletin',`<form onsubmit="createBulletin(event)"><div class="form"><div class="field"><label>Classe *</label><select class="select" name="classId" required><option value="">Choisir</option>${db.classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Période *</label><select class="select" name="termId">${db.settings.terms.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></div><div class="field full"><label>Élève *</label><select class="select" name="studentId" required><option value="">Choisir</option>${db.students.map(s=>`<option value="${s.id}">${esc(s.last.toUpperCase())} ${esc(s.first)} · ${esc(cls(s.classId)?.name||'')}</option>`).join('')}</select></div></div><div class="modalfoot"><button type="button" class="btn" onclick="closeModal()">Annuler</button><button class="btn primary">Créer</button></div></form>`);b.subjectData??={};let s=student(b.studentId),c=cls(b.classId),subjects=[...new Set(db.evaluations.filter(e=>e.classId===b.classId).map(e=>e.subject).filter(Boolean))];openModal('Bulletin',`<div class="bulletinScreen"><div class="bulletin"><div class="bulletinhead"><div><h2>Bulletin scolaire</h2><div class="muted">${esc(c?.name||'')} · ${esc(term(b.termId)?.name||'')}</div></div><div><b>${esc(s?.last?.toUpperCase()||'')} ${esc(s?.first||'')}</b><br><small>${fmtDate(s?.birth)}</small></div></div><div class="bulletinGrid"><div><b>Matière</b></div><div><b>Moyenne</b></div><div><b>Appréciation</b></div>${subjects.map(sub=>`<div>${esc(sub)}</div><div>${subjectAverage(b.studentId,b.classId,sub,b.termId)}</div><div><input class="input" value="${esc(b.subjectData?.[sub]?.comment||'')}" data-bulletin-id="${esc(b.id)}" data-bulletin-subject="${esc(sub)}" onchange="setBulletinCommentFromInput(this)"></div>`).join('')}</div><div class="section"><label class="field"><b>Appréciation générale</b><textarea onchange="setBulletinOverall('${b.id}',this.value)">${esc(b.overall||'')}</textarea></label></div></div></div><div class="bulletinPrint">${bulletinPrintSheet(b)}</div><div class="modalfoot"><button class="btn" onclick="printBulletin('${b.id}')">Imprimer le bulletin</button><button class="btn danger" onclick="deleteBulletin('${b.id}')">Supprimer</button><button class="btn primary" onclick="closeModal()">Fermer</button></div>`)}
function v101EvaluationStats(classId,subject){const es=gradebookEvaluations(classId,subject),ss=db.students.filter(s=>s.classId===classId);const rows=ss.map(s=>({s,avg:weightedAverageForEvaluations(es,[s.id])})).filter(x=>x.avg!=='—');const nums=rows.map(x=>Number(x.avg));const avg=nums.length?(nums.reduce((a,b)=>a+b,0)/nums.length).toFixed(2):'—';const best=nums.length?Math.max(...nums).toFixed(2):'—',low=nums.length?Math.min(...nums).toFixed(2):'—';return {es,ss,rows,avg,best,low}}
function evaluations(){const first=db.classes[0]?.id||'',subjects=gradebookSubjects(first);const st=v101EvaluationStats(first,'');return shell('Évaluations','Carnet de notes','Un véritable tableau de classe : saisie, moyennes pondérées, statistiques et gestion des évaluations.',`<button class="btn" onclick="openEvaluation()">+ Évaluation</button><button class="btn" onclick="exportGradebookCsv()">Exporter CSV</button>`)+`<div class="card"><div class="gradebookToolbar"><div class="field" style="min-width:180px;flex:1"><label>Classe</label><select class="select" id="gradebookClass" onchange="v10GradebookClassChanged()"><option value="">Choisir une classe</option>${db.classes.map(c=>`<option value="${c.id}" ${c.id===first?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field" style="min-width:180px;flex:1"><label>Matière</label><select class="select" id="gradebookSubject" onchange="v10RefreshGradebook()"><option value="">Toutes les matières</option>${subjects.map(x=>`<option>${esc(x)}</option>`).join('')}</select></div></div><div id="gradebookSummary" class="section">${gradebookSummary(first,'')}</div><div class="miniKpis section"><div class="miniKpi"><small>Moyenne de classe</small><b>${st.avg} /20</b></div><div class="miniKpi"><small>Plus haute moyenne</small><b>${st.best}</b></div><div class="miniKpi"><small>Plus basse moyenne</small><b>${st.low}</b></div><div class="miniKpi"><small>Évaluations</small><b>${st.es.length}</b></div></div><div id="gradebookMatrix" class="section">${gradebookMatrix(first,'')}</div></div><div class="card section"><div class="sectionhead"><div><h2>Évaluations enregistrées</h2><small class="muted">Ouvrir permet de modifier les métadonnées et les notes.</small></div></div>${evalList()}</div>`}

function createAllBulletins(classId,termId){const ss=db.students.filter(s=>s.classId===classId);let made=0;for(const s of ss){if(db.bulletins.some(b=>b.studentId===s.id&&b.termId===termId))continue;db.bulletins.push({id:uid(),studentId:s.id,classId,termId,subjectData:{},overall:'',published:false});made++}save();render();toast(`${made} bulletin(s) créé(s)`)}
function toggleBulletinPublished(id){const b=db.bulletins.find(x=>x.id===id);if(!b)return;b.published=!b.published;save();render();toast(b.published?'Bulletin finalisé':'Bulletin repassé en brouillon')}
function bulletins(){const terms=db.settings.terms||[],classes=db.classes||[];return shell('Évaluation','Bulletins','Créez, complétez, finalisez et imprimez les bulletins par période.',`<button class="btn" onclick="go('settings')">Périodes</button><button class="btn primary" onclick="openBulletin()">+ Bulletin</button>`)+`<div class="card"><div class="sectionhead"><div><h2>Génération par classe</h2><small class="muted">Crée tous les bulletins manquants d’une classe pour une période.</small></div></div><div class="bulletinBatch"><select class="select" id="batchClass"><option value="">Classe</option>${classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select><select class="select" id="batchTerm"><option value="">Période</option>${terms.map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select><button class="btn primary" onclick="const c=$('#batchClass').value,t=$('#batchTerm').value;if(c&&t)createAllBulletins(c,t);else toast('Choisis une classe et une période')">Générer les bulletins manquants</button></div></div><div class="card section"><div class="tablewrap"><table class="table"><thead><tr><th>Élève</th><th>Classe</th><th>Période</th><th>État</th><th>Moyenne</th><th></th></tr></thead><tbody>${db.bulletins.map(b=>{const s=student(b.studentId);return `<tr><td><b>${esc(s?.last||'')} ${esc(s?.first||'')}</b></td><td>${esc(cls(b.classId)?.name||'')}</td><td>${esc(term(b.termId)?.name||'')}</td><td><button class="pill ${b.published?'green':'orange'}" style="border:0;cursor:pointer" onclick="toggleBulletinPublished('${b.id}')">${b.published?'Finalisé':'Brouillon'}</button></td><td>${v101StudentAverage(b.studentId,b.termId)} /20</td><td><button class="btn small" onclick="openBulletin('${b.id}')">Ouvrir</button></td></tr>`}).join('')||'<tr><td colspan="6"><div class="empty">Aucun bulletin créé.</div></td></tr>'}</tbody></table></div></div>`}

function cloudContext(role,sid){
  const st=role==='student'?student(sid):null, space=window.cloudSpace||'personal';
  const classId=(space==='class'||space==='group')?(role==='student'?(st?.classId||''):(window.cloudClass||'')):'';
  const group=space==='group'?(role==='student'?(st?.group||''):(window.cloudGroup||'')):'';
  const ownerId=role==='student'?sid:(currentTeacherProfile()?.id||'teacher-local');
  return {space,classId,group,ownerId};
}
function cloudGrantMatches(x,role,sid){if(!x)return false;const grants=Array.isArray(x.shares)?x.shares:[];if(grants.some(g=>{const tid=role==='teacher'?(currentTeacherProfile()?.id||'teacher-local'):'';if(g.type==='teacher')return role==='teacher'&&g.id===tid;if(g.type==='student')return role==='student'&&g.id===sid;if(g.type==='class'){const st=student(sid);return !!st&&String(st.classId||'')===String(g.classId||'')}if(g.type==='group'){const st=student(sid);return !!st&&String(st.classId||'')===String(g.classId||'')&&String(st.group||'')===String(g.group||'')}return false}))return true;let parent=x.parentId,guard=0;while(parent&&guard++<100){const p=db.cloudItems.find(q=>q.id===parent);if(!p)break;if(cloudGrantMatchesDirect(p,role,sid))return true;parent=p.parentId||''}return false}
function cloudGrantMatchesDirect(x,role,sid){return (x.shares||[]).some(g=>{const tid=role==='teacher'?(currentTeacherProfile()?.id||'teacher-local'):'';if(g.type==='teacher')return role==='teacher'&&g.id===tid;if(g.type==='student')return role==='student'&&g.id===sid;if(g.type==='class'){const st=student(sid);return !!st&&String(st.classId||'')===String(g.classId||'')}if(g.type==='group'){const st=student(sid);return !!st&&String(st.classId||'')===String(g.classId||'')&&String(st.group||'')===String(g.group||'')}return false})}
function cloudAccessible(role,sid){const c=cloudContext(role,sid);return db.cloudItems.filter(x=>{const space=x.space||'personal';if(c.space==='shared')return cloudGrantMatches(x,role,sid);if(space!==c.space)return false;if(space==='personal')return x.ownerId===c.ownerId||cloudGrantMatches(x,role,sid);if(space==='class')return !!c.classId&&String(x.classId||'')===String(c.classId);if(space==='group')return !!c.classId&&String(x.classId||'')===String(c.classId)&&String(x.group||'')===String(c.group||'');return false})}
function getCloudPath(){return Array.isArray(window.cloudPath)?window.cloudPath:[]}
function cloudPathContextValid(role,sid){
  const all=cloudAccessible(role,sid), path=getCloudPath();
  if(!path.length)return true;
  for(let i=0;i<path.length;i++){
    const x=all.find(q=>q.id===path[i]);
    if(!x||x.type!=='folder')return false;
    if((x.parentId||'')!==(i?path[i-1]:''))return false;
  }
  return true;
}
function cloudCurrentItems(role,sid){
  const all=cloudAccessible(role,sid);
  if(!cloudPathContextValid(role,sid)){window.cloudPath=[];window.cloudSelected=''}
  const path=getCloudPath(), parent=path.length?path[path.length-1]:null;
  const q=String(window.cloudSearch||'').trim().toLowerCase(),sort=window.cloudSort||'name',type=window.cloudTypeFilter||'all';
  const accessibleIds=new Set(all.map(x=>x.id));let items=q?all.filter(x=>String(x.name||'').toLowerCase().includes(q)):all.filter(x=>{const p=x.parentId||null;if(window.cloudSpace==='shared'&&p&&!accessibleIds.has(p))return !parent;return p===parent});
  if(type==='folder')items=items.filter(x=>x.type==='folder');else if(type==='pdf')items=items.filter(x=>x.type!=='folder'&&(/\.pdf$/i.test(x.name||'')||String(x.mime||x.mimeType||'').toLowerCase()==='application/pdf'));else if(type==='image')items=items.filter(x=>x.type!=='folder'&&String(x.mime||x.mimeType||'').toLowerCase().startsWith('image/'));else if(type==='document')items=items.filter(x=>x.type!=='folder'&&/\.(docx?|odt|rtf|txt|md|csv|xlsx?)$/i.test(x.name||''));else if(type==='other')items=items.filter(x=>x.type!=='folder'&&!(/\.(pdf|docx?|odt|rtf|txt|md|csv|xlsx?)$/i.test(x.name||''))&&!String(x.mime||x.mimeType||'').toLowerCase().startsWith('image/'));
  return items.sort((a,b)=>sort==='size'?Number(b.size||0)-Number(a.size||0):sort==='date'?String(b.createdAt||'').localeCompare(String(a.createdAt||'')):sort==='type'?(a.type||'').localeCompare(b.type||'')||(a.name||'').localeCompare(b.name||'','fr',{sensitivity:'base'}):(a.name||'').localeCompare(b.name||'','fr',{sensitivity:'base'}));
}
function cloudSelect(id){window.cloudSelected=id;document.querySelectorAll('.cloudItem,.cloudListRow').forEach(x=>x.classList.remove('selected'));const el=document.querySelector(`[data-cloud-id="${CSS.escape(id)}"]`);if(el)el.classList.add('selected')}
function cloudSearchInput(input){const value=input.value,position=input.selectionStart??value.length;window.cloudSearch=value;render();const next=document.getElementById('cloudSearchInput');if(next){next.focus();try{next.setSelectionRange(position,position)}catch(e){}}}
function cloudCanWrite(role,sid,item){if(!item)return false;const teacherId=currentTeacherProfile()?.id||'teacher-local';const owner=role==='teacher'?(item.ownerId===teacherId||item.ownerId==='teacher-local'&&teacherId==='teacher-local'):(role==='student'&&item.ownerId===sid&&item.space==='personal');if(owner)return true;let cur=item,guard=0;while(cur&&guard++<100){if(cloudGrantMatchesDirect(cur,role,sid)&&(cur.shares||[]).some(g=>(g.role||'view')==='edit'))return true;cur=cur.parentId?db.cloudItems.find(q=>q.id===cur.parentId):null}return false}
function cloudOpen(id){const x=db.cloudItems.find(q=>q.id===id);if(!x)return;if(x.type==='file'){cloudPreview(id);return}const role=appSpace==='student'?'student':'teacher',sid=role==='student'?activeStudent():'';if(!cloudAccessible(role,sid).some(q=>q.id===id))return toast('Cet élément n’est pas accessible dans cet espace.');window.cloudPath=[...getCloudPath(),id];window.cloudSelected='';render()}
function cloudDragStart(e,id){e.dataTransfer.setData('text/plain',id);e.dataTransfer.effectAllowed='move';e.currentTarget.classList.add('dragging')}
function cloudDrop(e){e.preventDefault();const id=e.dataTransfer.getData('text/plain'),dest=getCloudPath().length?getCloudPath()[getCloudPath().length-1]:null;cloudMove(id,dest)}
function cloudDropTo(e,dest){e.preventDefault();e.stopPropagation();cloudMove(e.dataTransfer.getData('text/plain'),dest)}
function cloudSameScope(a,b){return !!a&&!!b&&a.space===b.space&&String(a.classId||'')===String(b.classId||'')&&String(a.group||'')===String(b.group||'')}
function cloudRootMatches(x,c){return !!x&&x.space===c.space&&(x.space==='personal'||(x.space==='class'&&String(x.classId||'')===String(c.classId||''))||(x.space==='group'&&String(x.classId||'')===String(c.classId||'')&&String(x.group||'')===String(c.group||''))) }
function cloudIsDescendant(id,parentId){let cur=parentId,guard=0;while(cur&&guard++<100){if(cur===id)return true;cur=db.cloudItems.find(x=>x.id===cur)?.parentId||''}return false}
function cloudValidateMove(role,sid,x,parent,c){if(!x)return 'Élément introuvable.';if(!cloudAccessible(role,sid).some(q=>q.id===x.id))return 'Cet élément n’est pas accessible ici.';if(!cloudCanWrite(role,sid,x))return 'Vous n’avez pas les droits pour déplacer cet élément.';if(parent){if(parent.type!=='folder')return 'La destination doit être un dossier.';if(!cloudSameScope(x,parent))return 'Les espaces Cloud sont séparés.';if(parent.id===x.id||cloudIsDescendant(x.id,parent.id))return 'Déplacement impossible dans son propre dossier.';if(!cloudCanWrite(role,sid,parent))return 'Vous n’avez pas les droits sur le dossier destination.';return ''}if(!cloudRootMatches(x,c))return 'La destination racine ne correspond pas à l’espace courant.';return ''}
async function cloudMove(id,dest){const role=appSpace==='student'?'student':'teacher',sid=role==='student'?activeStudent():'',c=cloudContext(role,sid);if(!id)return;const x=db.cloudItems.find(q=>q.id===id),parent=dest?db.cloudItems.find(q=>q.id===dest):null;const error=cloudValidateMove(role,sid,x,parent,c);if(error)return toast(error);try{const destPath=parent?.serverName||cloudRootPath(c);if(x.serverName&&destPath){const oldPath=String(x.serverName);const r=await api('/api/cloud-move',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source:oldPath,destination:destPath,name:x.name,type:x.type})});if(r.path){x.serverName=r.path;if(x.type==='file')x.url='/data/uploads/'+r.path;if(x.type==='folder'){const prefix=oldPath.endsWith('/')?oldPath:oldPath+'/';const next=String(r.path).endsWith('/')?String(r.path):String(r.path)+'/';db.cloudItems.forEach(y=>{if(y.serverName&&y.serverName.startsWith(prefix))y.serverName=next+y.serverName.slice(prefix.length)})}}}x.parentId=dest||'';window.cloudSelected='';save();render();toast('Élément déplacé')}catch(e){toast(e?.message||'Déplacement physique impossible')}}
function cloudRootPath(c){const safe=x=>String(x||'').replace(/[^a-zA-Z0-9_-]+/g,'_');if(c.space==='personal')return `cloud/personal/users/${safe(c.ownerId||'teacher-local')}`;let p=`cloud/${safe(c.space)}`;if(c.classId)p+=`/classes/${safe(c.classId)}`;if(c.group)p+=`/groups/${safe(c.group)}`;return p}
function cloudNewFolder(){const role=appSpace==='student'?'student':'teacher',sid=role==='student'?activeStudent():'',space=window.cloudSpace||'personal',st=student(sid),classId=(space==='class'||space==='group')?(role==='student'?st?.classId:(window.cloudClass||'')):'',group=space==='group'?(role==='student'?st?.group:(window.cloudGroup||'')):'',owner=role==='student'?sid:(currentTeacherProfile()?.id||'teacher-local');if(role==='student'&&space!=='personal')return toast('Cet espace est en lecture seule pour les élèves.');const parent=getCloudPath().length?getCloudPath()[getCloudPath().length-1]:'';openModal('Nouveau dossier',`<form onsubmit="event.preventDefault();const n=this.name.value.trim();if(!n)return;const p=db.cloudItems.find(q=>q.id==='${parent}');if(p&&(p.space!=='${space}'||String(p.classId||'')!==String('${classId}')||String(p.group||'')!==String('${group}')))return toast('Le dossier parent appartient à un autre espace.');const fid=uid();api('/api/cloud-mkdir',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({space:'${space}',ownerId:'${owner}',classId:'${classId}',group:'${group}',parentId:'${parent}',parentPath:'${db.cloudItems.find(q=>q.id==='${parent}')?.serverName||''}',name:n,id:fid})}).then(r=>{db.cloudItems.push({id:fid,type:'folder',name:n,space:'${space}',ownerId:'${owner}',classId:'${classId}',group:'${group}',parentId:'${parent}',serverName:r.path||'',createdAt:new Date().toISOString()});save();closeModal();render()}).catch(e=>toast(e?.message||'Impossible de créer le dossier.'))"><div class="field full"><label>Nom du dossier</label><input class="input" name="name" required></div><div class="modalfoot"><button type="button" class="btn" onclick="closeModal()">Annuler</button><button class="btn primary">Créer</button></div></form>`)}
async function cloudUpload(){const role=appSpace==='student'?'student':'teacher',sid=role==='student'?activeStudent():'',space=window.cloudSpace||'personal',st=student(sid),classId=(space==='class'||space==='group')?(role==='student'?st?.classId:(window.cloudClass||'')):'',group=space==='group'?(role==='student'?st?.group:(window.cloudGroup||'')):'',owner=role==='student'?sid:(currentTeacherProfile()?.id||'teacher-local');if(role==='student'&&space!=='personal')return toast('Cet espace est en lecture seule pour les élèves.');const parent=getCloudPath().length?getCloudPath()[getCloudPath().length-1]:'';const parentItem=parent?db.cloudItems.find(q=>q.id===parent):null;const folder=parentItem?.serverName||cloudRootPath({space,ownerId:owner,classId,group});const inp=document.createElement('input');inp.type='file';inp.multiple=true;inp.onchange=async()=>{for(const f of [...inp.files]){try{const x=await upload(f,folder);db.cloudItems.push({id:uid(),type:'file',name:f.name,size:f.size,mime:f.type,url:x.url||x.dataUrl||'',serverName:x.name||'',space,ownerId:owner,classId,group,parentId:parent,createdAt:new Date().toISOString()});}catch(e){toast('Échec du téléversement de '+f.name)}}save();render()};inp.click()}
async function cloudUploadFolder(){const role=appSpace==='student'?'student':'teacher',sid=role==='student'?activeStudent():'',space=window.cloudSpace||'personal',st=student(sid),classId=(space==='class'||space==='group')?(role==='student'?st?.classId:(window.cloudClass||'')):'',group=space==='group'?(role==='student'?st?.group:(window.cloudGroup||'')):'',owner=role==='student'?sid:(currentTeacherProfile()?.id||'teacher-local');if(role==='student'&&space!=='personal')return toast('Les élèves peuvent importer uniquement dans leur espace personnel.');const parent=getCloudPath().length?getCloudPath()[getCloudPath().length-1]:'',parentItem=parent?db.cloudItems.find(q=>q.id===parent):null,rootPath=parentItem?.serverName||cloudRootPath({space,ownerId:owner,classId,group});const inp=document.createElement('input');inp.type='file';inp.multiple=true;inp.setAttribute('webkitdirectory','');inp.setAttribute('directory','');inp.onchange=async()=>{const files=[...inp.files];if(!files.length)return;const folderIds=new Map([['',parent]]),folderPaths=new Map([['',rootPath]]);let ok=0,failed=0;for(const file of files){try{const rel=String(file.webkitRelativePath||file.name).split('/').filter(Boolean),dirs=rel.slice(0,-1);let key='',parentId=parent,pathNow=parentItem?.serverName||'';for(const part of dirs){key=key?key+'/'+part:part;if(!folderIds.has(key)){const id=uid(),r=await api('/api/cloud-mkdir',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({space,ownerId:owner,classId,group,parentId,parentPath:pathNow,name:part,id})});const physical=r.path||[pathNow,part].filter(Boolean).join('/');db.cloudItems.push({id,type:'folder',name:part,space,ownerId:owner,classId,group,parentId,serverName:physical,shares:[],createdAt:new Date().toISOString()});folderIds.set(key,id);folderPaths.set(key,physical)}parentId=folderIds.get(key);pathNow=folderPaths.get(key)}const uploaded=await upload(file,dirs.length?pathNow:rootPath);db.cloudItems.push({id:uid(),type:'file',name:file.name,size:file.size,mime:file.type||'',url:uploaded.url||'',serverName:uploaded.name||'',space,ownerId:owner,classId,group,parentId,shares:[],createdAt:new Date().toISOString()});ok++}catch(err){failed++;console.error('Cloud folder import failed',file.name,err)}}save();render();toast(`${ok} fichier(s) importé(s)${failed?` · ${failed} échec(s)`:''}`)};inp.click()}
function cloudPreview(id){const x=db.cloudItems.find(q=>q.id===id);if(!x||x.type!=='file')return;if(!x.url)return toast('Aucun aperçu disponible.');const mime=String(x.mime||'').toLowerCase();let body='';if(mime.startsWith('image/'))body=`<img src="${esc(x.url)}" style="max-width:100%;max-height:65vh;display:block;margin:auto;border-radius:10px">`;else if(mime==='application/pdf'||String(x.name).toLowerCase().endsWith('.pdf'))body=`<iframe src="${esc(x.url)}" style="width:100%;height:65vh;border:1px solid var(--line);border-radius:10px"></iframe>`;else if(mime.startsWith('text/')||/\.(txt|csv|md)$/i.test(x.name||''))body=`<iframe src="${esc(x.url)}" style="width:100%;height:55vh;border:1px solid var(--line);border-radius:10px;background:#fff"></iframe>`;else return window.open(x.url,'_blank','noopener');openModal(esc(x.name),body+`<div class="modalfoot"><a class="btn" href="${esc(x.url)}" target="_blank" rel="noopener">Ouvrir dans un nouvel onglet</a><button class="btn primary" onclick="closeModal()">Fermer</button></div>`)}
function cloudCopyLink(){const x=db.cloudItems.find(q=>q.id===window.cloudSelected);if(!x)return toast('Sélectionnez un élément.');if(!x.url)return toast('Aucun lien public disponible pour cet élément.');navigator.clipboard?.writeText(new URL(x.url,location.origin).href).then(()=>toast('Lien copié')).catch(()=>toast('Impossible de copier le lien.'))}
function cloudShare(){const id=window.cloudSelected,x=db.cloudItems.find(q=>q.id===id);if(!x)return toast('Sélectionnez un élément.');if(!cloudCanWrite('teacher','',x))return toast('Seul le propriétaire peut gérer le partage.');x.shares=Array.isArray(x.shares)?x.shares:[];const teachers=db.teachers.filter(t=>t.active!==false),classes=db.classes,students=db.students;openModal('Partager « '+esc(x.name)+' »',`<div class="section"><div class="field full"><label>Personnes</label><select class="select" id="shareStudent"><option value="">Choisir…</option>${teachers.map(t=>`<option value="teacher:${t.id}">Professeur · ${esc(teacherName(t))}</option>`).join('')}${students.map(s=>`<option value="student:${s.id}">${esc(s.first+' '+s.last)} · ${esc(cls(s.classId)?.name||'')}</option>`).join('')}</select></div><div class="field full"><label>Classes / groupes</label><select class="select" id="shareScope"><option value="">Choisir…</option>${classes.map(c=>`<option value="class:${c.id}">Classe · ${esc(c.name)}</option>${(c.groups||[]).map(g=>`<option value="group:${c.id}:${esc(g)}">Groupe · ${esc(c.name)} · ${esc(g)}</option>`).join('')}`).join('')}</select></div><div class="field full"><label>Droit</label><select class="select" id="shareRole"><option value="view">Lecture seule</option><option value="edit">Modification</option></select></div><button class="btn primary" onclick="applyCloudShare('${id}')">Ajouter le partage</button></div><div class="section"><h3>Accès actuels</h3>${x.shares.map((g,i)=>`<div class="message" style="display:flex;justify-content:space-between;gap:8px"><span><b>${esc(cloudGrantLabel(g))}</b><small>${g.role==='edit'?'Modification':'Lecture seule'}</small></span><button class="btn small danger" onclick="removeCloudShare('${id}',${i})">Retirer</button></div>`).join('')||'<div class="empty">Aucun partage.</div>'}</div><div class="modalfoot"><button class="btn" onclick="closeModal()">Fermer</button></div>`)}
function cloudGrantLabel(g){if(g.type==='student'){const s=student(g.id);return s?`${s.first} ${s.last}`:'Élève';}if(g.type==='teacher'){const t=db.teachers.find(x=>x.id===g.id);return 'Professeur · '+teacherName(t||{});}if(g.type==='class')return 'Classe · '+(cls(g.classId)?.name||g.classId);if(g.type==='group')return 'Groupe · '+(cls(g.classId)?.name||g.classId)+' · '+g.group;return 'Partage';}
function applyCloudShare(id){const x=db.cloudItems.find(q=>q.id===id),sv=$('#shareStudent')?.value||'',sc=$('#shareScope')?.value||'',role=$('#shareRole')?.value||'view';let g=null;if(sv)g={type:sv.split(':')[0],id:sv.split(':')[1],role};else if(sc){const a=sc.split(':');g=a[0]==='class'?{type:'class',classId:a[1],role}:{type:'group',classId:a[1],group:a.slice(2).join(':'),role};}if(!g)return toast('Choisissez un destinataire.');x.shares??=[];const key=JSON.stringify({...g,role:undefined});x.shares=x.shares.filter(q=>JSON.stringify({...q,role:undefined})!==key);x.shares.push(g);save();cloudShare();toast('Partage enregistré')}
function removeCloudShare(id,i){const x=db.cloudItems.find(q=>q.id===id);if(!x)return;x.shares??=[];x.shares.splice(i,1);save();cloudShare()}
async function cloudCopy(){const id=window.cloudSelected,x=db.cloudItems.find(q=>q.id===id);if(!x)return toast('Sélectionnez un élément.');const role=appSpace==='student'?'student':'teacher',sid=role==='student'?activeStudent():'';if(!cloudCanWrite(role,sid,x))return toast('Vous n’avez pas les droits pour copier cet élément.');openModal('Copier dans…',`<div class="field full"><label>Dossier de destination</label><select class="select" id="cloudCopyDest"><option value="">Racine de l’espace actuel</option>${cloudAccessible(role,sid).filter(q=>q.type==='folder').map(f=>`<option value="${f.id}">${esc(f.name)}</option>`).join('')}</select></div><div class="modalfoot"><button class="btn" onclick="closeModal()">Annuler</button><button class="btn primary" onclick="cloudCopyTo($('#cloudCopyDest').value)">Copier</button></div>`)}
async function cloudCopyTo(dest){const id=window.cloudSelected,x=db.cloudItems.find(q=>q.id===id),p=dest?db.cloudItems.find(q=>q.id===dest):null;if(!x)return;if(p&&!cloudSameScope(x,p))return toast('La destination appartient à un autre espace.');try{const r=await api('/api/cloud-copy',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({source:x.serverName||'',destination:p?.serverName||cloudRootPath(cloudContext('teacher','')),name:x.name,type:x.type})});const clone={...x,id:uid(),parentId:dest||'',name:x.name,serverName:r.path||'',shares:[]};db.cloudItems.push(clone);save();closeModal();render();toast('Copie créée')}catch(e){toast(e?.message||'Copie impossible')}}
function cloudInfo(id){const x=db.cloudItems.find(q=>q.id===id);if(!x)return;openModal('Informations',`<div class="grid g2"><div class="card"><small class="muted">Nom</small><b>${esc(x.name)}</b></div><div class="card"><small class="muted">Type</small><b>${x.type==='folder'?'Dossier':esc(x.mime||'Fichier')}</b></div><div class="card"><small class="muted">Taille</small><b>${x.type==='folder'?'—':Math.ceil((x.size||0)/1024)+' Ko'}</b></div><div class="card"><small class="muted">Créé le</small><b>${x.createdAt?new Date(x.createdAt).toLocaleString('fr-FR'):'—'}</b></div></div><div class="notice section">${x.serverName?'Emplacement physique synchronisé.':'Ancien élément sans emplacement physique associé.'}</div><div class="modalfoot"><button class="btn primary" onclick="closeModal()">Fermer</button></div>`)}
async function cloudRenamePhysical(id,newName){try{const r=await api('/api/cloud-rename',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path:db.cloudItems.find(q=>q.id===id)?.serverName||'',name:newName,type:db.cloudItems.find(q=>q.id===id)?.type||'file'})});return r}catch(e){throw e}}
function cloudSyncDescendantServerNames(oldPath,newPath){const oldPrefix=String(oldPath||'').replace(/\\/g,'/').replace(/\/$/,'')+'/',newPrefix=String(newPath||'').replace(/\\/g,'/').replace(/\/$/,'')+'/';if(oldPrefix==='/'||newPrefix==='/')return;db.cloudItems.forEach(y=>{if(y.serverName&&String(y.serverName).startsWith(oldPrefix)){y.serverName=newPrefix+String(y.serverName).slice(oldPrefix.length);if(y.type==='file')y.url='/data/uploads/'+y.serverName}})}
function cloudRename(){const id=window.cloudSelected;if(!id)return toast('Sélectionnez un élément.');const role=appSpace==='student'?'student':'teacher',sid=role==='student'?activeStudent():'',x=db.cloudItems.find(q=>q.id===id);if(!x)return;if(!cloudCanWrite(role,sid,x))return toast('Vous n’avez pas les droits pour renommer cet élément.');openModal('Renommer',`<form onsubmit="event.preventDefault();const n=this.elements.name.value.trim();if(!n)return;const y=db.cloudItems.find(q=>q.id==='${id}');if(!y)return; const oldName=y.name;const oldNamePath=String(y.serverName||'');const ext=y.type==='file'?(String(oldName).match(/\.[^.]+$/)?.[0]||''):'';const finalName=y.type==='file'&&ext&&!n.toLowerCase().endsWith(ext.toLowerCase())?n+ext:n;cloudRenamePhysical(id,finalName).then(r=>{y.name=finalName;if(r.path){const nextPath=String(r.path);y.serverName=nextPath;if(y.type==='file')y.url='/data/uploads/'+nextPath;else if(y.type==='folder')cloudSyncDescendantServerNames(oldNamePath,nextPath);}save();closeModal();render();toast('Nom modifié')}).catch(e=>toast(e?.message||'Impossible de renommer le fichier.'))"><div class="field full"><label>Nom</label><input class="input" name="name" value="${esc(x.name)}" required autofocus></div><div class="modalfoot"><button type="button" class="btn" onclick="closeModal()">Annuler</button><button class="btn primary">Enregistrer</button></div></form>`)}
function cloudDelete(){const id=window.cloudSelected;if(!id)return toast('Sélectionnez un élément.');const role=appSpace==='student'?'student':'teacher',sid=role==='student'?activeStudent():'',x=db.cloudItems.find(q=>q.id===id);if(!x)return;if(!cloudCanWrite(role,sid,x))return toast('Vous n’avez pas les droits pour supprimer cet élément.');confirmModal('Supprimer cet élément et son contenu ?','Supprimer',async()=>{const ids=new Set([id]);let again=true;while(again){again=false;for(const y of db.cloudItems)if(y.parentId&&ids.has(y.parentId)&&!ids.has(y.id)){ids.add(y.id);again=true}}try{if(x.serverName)await api('/api/cloud-delete',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path:x.serverName})})}catch(e){return toast(e?.message||'Suppression physique impossible : les informations restent dans MaClasse.')}db.cloudItems=db.cloudItems.filter(y=>!ids.has(y.id));window.cloudSelected='';save();render();toast('Élément supprimé')})}
function documents(role='teacher',sid=''){const cf=role==='teacher'?(window.classContext||''):'';if(cf){window.cloudSpace='class';window.cloudClass=cf;window.cloudGroup=window.classGroupContext||'';}
  window.cloudSpace??='personal';window.cloudPath=Array.isArray(window.cloudPath)?window.cloudPath:[];window.cloudView??='grid';
  const accessible=cloudAccessible(role,sid);
  if(!cloudPathContextValid(role,sid))window.cloudPath=[];
  const last=getCloudPath().at(-1);
  const spaces=[['personal','Mon espace'],['shared','Partagés avec moi'],['class','Espace classe'],['group','Espace groupe'],['documents','Documents']];
  if(window.cloudSpace==='documents'){
    const docs=documentInventory().filter(x=>role==='teacher'||x.classId===student(sid)?.classId);
    return shell('Ressources','Cloud','Documents issus des cours, devoirs et échanges auxquels vous avez accès.',`<div class="cloudTabs">${spaces.map(x=>`<button class="cloudTab ${window.cloudSpace===x[0]?'active':''}" onclick="window.cloudSpace='${x[0]}';window.cloudPath=[];window.cloudSelected='';window.cloudSearch='';render()">${x[1]}</button>`).join('')}</div><div class="card section">${docs.map(x=>docFileHtml(x.file,x.title||x.kind)).join('')||'<div class="empty">Aucun document accessible.</div>'}</div>`)
  }
  const st=role==='student'?student(sid):null,title=window.cloudSpace==='class'?'Espace classe':window.cloudSpace==='group'?'Espace groupe':'Mon espace';
  if(role==='student'&&window.cloudSpace==='class'&&st){window.cloudClass=st.classId||'';window.cloudGroup=''}
  if(role==='student'&&window.cloudSpace==='group'&&st){window.cloudClass=st.classId||'';window.cloudGroup=st.group||''}
  const items=cloudCurrentItems(role,sid);
  const folders=items.filter(x=>x.type==='folder'), files=items.filter(x=>x.type!=='folder');
  const cloudAll=cloudAccessible(role,sid),cloudFiles=cloudAll.filter(x=>x.type!=='folder'),cloudBytes=cloudFiles.reduce((n,x)=>n+Math.max(0,Number(x.size)||0),0),cloudShared=cloudAll.filter(x=>(x.shares||[]).length).length;
  const listItems=window.cloudView==='list' ? `<div class="cloudList">${items.map(x=>`<div class="cloudListRow ${(window.cloudSelectedIds||[window.cloudSelected]).includes(x.id)?'selected':''}" data-cloud-id="${x.id}" draggable="true" onclick="cloudSelect('${x.id}',event)" oncontextmenu="cloudSelect('${x.id}',event);cloudItemMenu(event,'${x.id}');return false" ondblclick="cloudOpen('${x.id}')" ondragstart="cloudDragStart(event,'${x.id}')" ondragover="${x.type==='folder'?'event.preventDefault();this.classList.add(\'dropTarget\')':'event.preventDefault()'}" ondragleave="this.classList.remove('dropTarget')" ondrop="${x.type==='folder'?`cloudDropTo(event,'${x.id}')`:''}"><span class="cloudIcon">${cloudFileVisual(x)}</span><span class="cloudName"><b>${esc(x.name)}</b><small>${x.type==='folder'?'Dossier':Math.ceil((x.size||0)/1024)+' Ko'}</small></span><span class="muted">${x.createdAt?fmtDate(x.createdAt.slice(0,10)):''}</span></div>`).join('')||'<div class="empty">Ce dossier est vide.</div>'}</div>`:
  `<div class="cloudGrid">${items.map(x=>`<div class="cloudItem ${(window.cloudSelectedIds||[window.cloudSelected]).includes(x.id)?'selected':''}" data-cloud-id="${x.id}" draggable="true" onclick="cloudSelect('${x.id}',event)" oncontextmenu="cloudSelect('${x.id}',event);cloudItemMenu(event,'${x.id}');return false" ondblclick="cloudOpen('${x.id}')" ondragstart="cloudDragStart(event,'${x.id}')" ondragover="${x.type==='folder'?'event.preventDefault();this.classList.add(\'dropTarget\')':'event.preventDefault()'}" ondragleave="this.classList.remove('dropTarget')" ondrop="${x.type==='folder'?`cloudDropTo(event,'${x.id}')`:''}"><span class="cloudIcon">${cloudFileVisual(x)}</span><span class="cloudName"><b>${esc(x.name)}</b><small>${x.type==='folder'?'Dossier':Math.ceil((x.size||0)/1024)+' Ko'}</small></span></div>`).join('')||'<div class="empty">Ce dossier est vide.</div>'}</div>`;
  const classNav=(window.cloudSpace==='class'||window.cloudSpace==='group')?`<div class="cloudSideSection"><small class="muted">Classe</small>${role==='teacher'?db.classes.map(c=>`<button class="cloudSideItem ${window.cloudClass===c.id?'active':''}" onclick="window.cloudClass='${c.id}';window.cloudGroup='';window.cloudPath=[];window.cloudSelected='';window.cloudSearch='';render()">▣ ${esc(c.name)}</button>`).join(''):`<div class="cloudSideCurrent">▣ ${esc(st?.classId?cls(st.classId)?.name:'Ma classe')}</div>`}${window.cloudSpace==='group'?`<small class="muted" style="display:block;margin-top:10px">Groupe</small>${role==='teacher'?(cls(window.cloudClass)?.groups||[]).map(g=>`<button class="cloudSideItem ${window.cloudGroup===g?'active':''}" onclick="window.cloudGroup='${g}';window.cloudPath=[];window.cloudSelected='';window.cloudSearch='';render()">◌ ${esc(g)}</button>`).join('')||'<span class="muted">Aucun groupe.</span>':`<div class="cloudSideCurrent">◌ ${esc(st?.group||'Tous les documents du groupe')}</div>`}`:''}</div>`:'';
  return shell('Ressources','Cloud','Vos espaces de stockage, séparés par classe et groupe.',`<div class="cloudTopActions">${window.cloudSpace!=='shared'&&role==='teacher'?'<button class="btn primary" onclick="cloudNewFolder()">+ Nouveau dossier</button><button class="btn" onclick="cloudUpload()">Importer des fichiers</button><button class="btn" onclick="cloudUploadFolder()">Importer un dossier</button>':''}${window.cloudSpace==='shared'?'<span class="muted">Fichiers et dossiers partagés avec vous · lecture ou modification selon les droits</span>':''}</div><div class="cloudTabs">${spaces.map(x=>`<button class="cloudTab ${window.cloudSpace===x[0]?'active':''}" onclick="window.cloudSpace='${x[0]}';window.cloudPath=[];window.cloudSelected='';window.cloudSearch='';window.cloudTypeFilter='all';render()">${x[1]}</button>`).join('')}</div><div class="miniKpis section"><div class="miniKpi"><small>Fichiers accessibles</small><b>${cloudFiles.length}</b></div><div class="miniKpi"><small>Dossiers</small><b>${cloudAll.filter(x=>x.type==='folder').length}</b></div><div class="miniKpi"><small>Espace utilisé connu</small><b>${cloudBytes>=1048576?(cloudBytes/1048576).toFixed(1)+' Mo':Math.ceil(cloudBytes/1024)+' Ko'}</b></div><div class="miniKpi"><small>Éléments partagés</small><b>${cloudShared}</b></div></div><div class="cloudLayout"><aside class="card"><b>${title}</b>${classNav}</aside><section class="card"><div class="cloudCrumbs cloudMainCrumbs"><button class="cloudCrumb" onclick="window.cloudPath=[];render()">Racine</button>${getCloudPath().map((id,i)=>{const x=db.cloudItems.find(q=>q.id===id);return `<span>›</span><button class="cloudCrumb" onclick="window.cloudPath=window.cloudPath.slice(0,${i+1});render()">${esc(x?.name||'Dossier')}</button>`}).join('')}</div><div class="cloudActions"><input class="input" style="max-width:220px" id="cloudSearchInput" placeholder="Rechercher dans cet espace…" value="${esc(window.cloudSearch||'')}" oninput="cloudSearchInput(this)"><select class="select" style="max-width:150px" aria-label="Filtrer les fichiers par type" onchange="window.cloudTypeFilter=this.value;render()"><option value="all" ${(window.cloudTypeFilter||'all')==='all'?'selected':''}>Tous les types</option><option value="folder" ${window.cloudTypeFilter==='folder'?'selected':''}>Dossiers</option><option value="pdf" ${window.cloudTypeFilter==='pdf'?'selected':''}>PDF</option><option value="image" ${window.cloudTypeFilter==='image'?'selected':''}>Images</option><option value="document" ${window.cloudTypeFilter==='document'?'selected':''}>Documents</option><option value="other" ${window.cloudTypeFilter==='other'?'selected':''}>Autres fichiers</option></select><select class="select" style="max-width:150px" onchange="window.cloudSort=this.value;render()"><option value="name" ${(window.cloudSort||'name')==='name'?'selected':''}>Nom</option><option value="type" ${window.cloudSort==='type'?'selected':''}>Type</option><option value="date" ${window.cloudSort==='date'?'selected':''}>Plus récent</option><option value="size" ${window.cloudSort==='size'?'selected':''}>Taille</option></select><button class="btn small ${window.cloudView==='grid'?'active':''}" onclick="window.cloudView='grid';render()">▦ Icônes</button><button class="btn small ${window.cloudView==='list'?'active':''}" onclick="window.cloudView='list';render()">☷ Liste</button><button class="btn small" onclick="window.cloudSort='date';render()">Récents</button><span id="cloudContextActions">${(window.cloudSelectedIds||[]).length>1?`<button class="btn small" onclick="cloudMoveSelected()">Déplacer la sélection</button><button class="btn small danger" onclick="cloudDeleteSelected()">Supprimer la sélection</button>`:(window.cloudSelected?`<button class="btn small" onclick="cloudPreview(window.cloudSelected)">Aperçu</button><button class="btn small" onclick="cloudInfo(window.cloudSelected)">Infos</button><button class="btn small" onclick="cloudShare()">Partager</button><button class="btn small" onclick="cloudCopyLink()">Lien</button><button class="btn small" onclick="cloudCopy()">Copier</button><button class="btn small" onclick="cloudRename()">Renommer</button><button class="btn small" onclick="cloudMoveSelected()">Déplacer</button><button class="btn small danger" onclick="cloudDelete()">Supprimer</button>`:`<button class="btn small" onclick="cloudSelectAll()">Tout sélectionner</button>`) }</span></div>${listItems}</section></div>`)
}
function docFinderData(items){const root=new Map();for(const x of items){const m=docLabel(x),kind=x.kind,cl=m.className,sub=m.subject||'Sans matière',key=`${m.date}|${m.title}|${x.key}`;if(!root.has(kind))root.set(kind,new Map());if(!root.get(kind).has(cl))root.get(kind).set(cl,new Map());if(!root.get(kind).get(cl).has(sub))root.get(kind).get(cl).set(sub,new Map());if(!root.get(kind).get(cl).get(sub).has(key))root.get(kind).get(cl).get(sub).set(key,{name:m.title,date:m.date,items:[]});root.get(kind).get(cl).get(sub).get(key).items.push(x)}return root}
function documentFinderHtml(items){const data=docFinderData(items),p=window.docFinderPath||[];if(!p.length)return finderFolders([...data.keys()].sort((a,b)=>a.localeCompare(b,'fr')).map(k=>({name:k,count:[...data.get(k).values()].reduce((n,m)=>n+[...m.values()].reduce((z,s)=>z+[...s.values()].reduce((q,w)=>q+w.items.length,0),0),0),path:['root',k]})));if(p[0]==='root'){const m=data.get(p[1]);if(!m)return '<div class="empty">Dossier introuvable.</div>';return finderFolders([...m.keys()].sort((a,b)=>a.localeCompare(b,'fr')).map(k=>({name:k,count:[...m.get(k).values()].reduce((n,s)=>n+[...s.values()].reduce((z,w)=>z+w.items.length,0),0),path:['class',p[1],k]})))}if(p[0]==='class'){const m=data.get(p[1])?.get(p[2]);if(!m)return '<div class="empty">Dossier introuvable.</div>';return finderFolders([...m.keys()].sort((a,b)=>a.localeCompare(b,'fr')).map(k=>({name:k,count:[...m.get(k).values()].reduce((n,w)=>n+w.items.length,0),path:['subject',p[1],p[2],k]})))}const m=data.get(p[1])?.get(p[2])?.get(p[3]);if(!m)return '<div class="empty">Dossier introuvable.</div>';const works=[...m.values()].sort((a,b)=>b.date.localeCompare(a.date));return `<div class="finder${window.docFinderView==='grid'?'Grid':'List'}">${works.map((w,i)=>{const key='w'+i+'_'+uid().slice(-6);window._finderWorks=window._finderWorks||{};window._finderWorks[key]=w.items;return `<div class="finderWork"><button class="finderWorkMain" onclick="openDocumentWorkKey('${key}')"><span class="finderIcon">📂</span><span><b>${esc(fmtDate(w.date))} — ${esc(w.name)}</b><small>${w.items.length} fichier(s)${w.items.some(x=>x.studentId)?' · rendus élèves':''}</small></span></button>${window.docFinderView==='list'?w.items.map(x=>docFileHtml(x.file,x.studentName||'')).join(''):''}</div>`}).join('')||'<div class="empty">Ce dossier est vide.</div>'}</div>`}
function finderFolders(items){return `<div class="finderGrid">${items.map((x,i)=>{const key='f'+i+'_'+uid().slice(-6);window._finderPaths=window._finderPaths||{};window._finderPaths[key]=x.path;return `<button class="finderItem" onclick="docFinderOpenKey('${key}')"><span class="finderIcon">📁</span><span class="finderName">${esc(x.name)}</span><small>${x.count} fichier(s)</small></button>`}).join('')||'<div class="empty">Aucun document ne correspond à ces critères.</div>'}</div>`}
function docFinderOpenKey(key){const p=window._finderPaths?.[key];if(!p)return;docFinderOpen(p)}
function docFinderOpen(path){window.docFinderPath=[...path];filterDocuments(true)}function docFinderBack(){const p=window.docFinderPath||[];if(!p.length)return;window.docFinderPath=p.slice(0,-1);filterDocuments(true)}function docFinderHome(){window.docFinderPath=[];filterDocuments(true)}function docFinderCollapse(){window.docFinderPath=[];filterDocuments(true)}function toggleDocView(){window.docFinderView=window.docFinderView==='grid'?'list':'grid';filterDocuments(true)}
function openDocumentWorkKey(key){const items=window._finderWorks?.[key]||[];openDocumentWork(items)}
function openDocumentWork(items){openModal('Dossier de travail',`<div class="actionList">${items.map(x=>docFileHtml(x.file,x.studentName||'')).join('')||'<div class="empty">Aucun fichier.</div>'}</div><div class="modalfoot"><button class="btn primary" onclick="closeModal()">Fermer</button></div>`)}

function filterDocuments(internal=false){const q=($('#docSearch')?.value||'').toLowerCase(),kind=$('#docKind')?.value||'',cl=$('#docClass')?.value||'',sub=$('#docSubject')?.value||'',stu=$('#docStudent')?.value||'',from=$('#docFrom')?.value||'',to=$('#docTo')?.value||'';let items=documentInventory().filter(x=>(!q||JSON.stringify(x).toLowerCase().includes(q))&&(!kind||x.kind===kind)&&(!cl||x.classId===cl)&&(!sub||x.subject===sub)&&(!stu||x.studentId===stu)&&(!from||x.date>=from)&&(!to||x.date<=to));const p=window.docFinderPath||[];if(p[0]==='root')items=items.filter(x=>x.kind===p[1]);else if(p[0]==='class')items=items.filter(x=>x.kind===p[1]&&docLabel(x).className===p[2]);else if(p[0]==='subject')items=items.filter(x=>x.kind===p[1]&&docLabel(x).className===p[2]&&(docLabel(x).subject||'Sans matière')===p[3]);if($('#docList'))$('#docList').innerHTML=documentFinderHtml(items);if($('#docCount'))$('#docCount').textContent=`${items.length} fichier(s)`;if($('#docBreadcrumbs'))$('#docBreadcrumbs').innerHTML=docBreadcrumbHtml()}
function docBreadcrumbHtml(){const p=window.docFinderPath||[];if(!p.length)return '<b>Documents</b>';window._finderPaths=window._finderPaths||{};const rootKey='b'+uid().slice(-7);window._finderPaths[rootKey]=['root',p[1]];if(p[0]==='root')return `<button class="crumb" onclick="docFinderHome()">Documents</button> › <b>${esc(p[1])}</b>`;const classKey='b'+uid().slice(-7);window._finderPaths[classKey]=['class',p[1],p[2]];if(p[0]==='class')return `<button class="crumb" onclick="docFinderHome()">Documents</button> › <button class="crumb" onclick="docFinderOpenKey('${rootKey}')">${esc(p[1])}</button> › <b>${esc(p[2])}</b>`;return `<button class="crumb" onclick="docFinderHome()">Documents</button> › <button class="crumb" onclick="docFinderOpenKey('${rootKey}')">${esc(p[1])}</button> › <button class="crumb" onclick="docFinderOpenKey('${classKey}')">${esc(p[2])}</button> › <b>${esc(p[3])}</b>`}


