function saveEvaluationTemplate(ev){ev.preventDefault();const f=ev.target,o=Object.fromEntries(new FormData(f));const name=String(o.name||'').trim(),level=String(o.level||'').trim(),competencies=[...(f.querySelector('#gridCompetencies')?.selectedOptions||[])].map(x=>x.value),criteria=v206ReadCriteria();if(!name)return toast('Donnez un nom à la grille.');if(!competencies.length&&!criteria.length)return toast('Ajoutez au moins une compétence ou un critère noté.');db.evaluationTemplates??=[];db.competencyLibrary??=[];db.evaluationCriteriaLibrary??=[];const t={id:uid(),name,title:String(o.title||name).trim(),subject:String(o.subject||'').trim(),level,competencies,criteria,createdAt:new Date().toISOString()};db.evaluationTemplates.push(t);competencies.forEach(c=>{if(!db.competencyLibrary.includes(c))db.competencyLibrary.push(c)});criteria.forEach(c=>{const existing=db.evaluationCriteriaLibrary.find(x=>x.name.toLocaleLowerCase('fr')===c.name.toLocaleLowerCase('fr')&&Number(x.maxPoints)===Number(c.maxPoints));if(existing){c.libraryId=existing.id;}else db.evaluationCriteriaLibrary.push({...c,id:uid()})});db.competencyLibrary.sort((a,b)=>a.localeCompare(b,'fr'));save();manageEvaluationGrids();toast('Grille enregistrée');}


