function gradebookMatrix(classId,subject){const es=gradebookEvaluations(classId,subject),ss=db.students.filter(s=>s.classId===classId);if(!classId)return '<div class="empty">Choisis une classe pour afficher le carnet de notes.</div>';if(!ss.length)return '<div class="notice warn">Cette classe ne contient aucun élève.</div>';if(!es.length)return '<div class="empty">Aucune évaluation pour cette sélection. Crée la première avec « Nouvelle évaluation ».</div>';return `<div class="tablewrap"><table class="table gradebookMatrix"><thead><tr><th>Élève</th>${es.map(e=>`<th title="${esc(e.title)}">${esc((e.title||'Éval.').slice(0,16))}<small style="display:block;color:var(--muted)">${fmtDate(e.date)} · /${v207EvaluationMax(e)} · ×${e.coefficient||1}</small></th>`).join('')}<th>Moyenne /20</th></tr></thead><tbody>${ss.map(s=>{const vals=es.map(e=>e.grades?.find(g=>g.studentId===s.id)?.value??''),avg=weightedAverageForEvaluations(es,[s.id]);return `<tr><td class="gradebookName"><b>${esc(s.last.toUpperCase())} ${esc(s.first)}</b><small>${esc(s.group||'Classe entière')}</small></td>${es.map((e,i)=>{const gr=e.grades?.find(g=>g.studentId===s.id),ratings=gr?.competencyRatings||{},rated=(e.competencies||[]).filter(c=>Number(ratings[c])>=1&&Number(ratings[c])<=4),max=(e.criteria||[]).reduce((n,c)=>n+Math.max(0,Number(c.maxPoints)||Math.max(0,...(c.levels||[]).map(Number))),0),sum=(e.criteria||[]).reduce((n,c)=>n+(Number(gr?.criterionScores?.[c.id])||0),0),bar=v207EvaluationMax(e);return `<td class="gradeCell ${vals[i]===''?'empty':''}"><input class="input" type="number" min="0" max="${bar}" step="0.01" value="${esc(vals[i])}" placeholder="—" aria-label="Note de ${esc(s.first)} sur ${bar}" onchange="setGrade('${e.id}','${s.id}',this.value);v10RefreshGradebook()">${max?`<small class="muted" style="display:block;margin-top:3px">Critères : ${sum} / ${max} pts</small>`:''}${rated.length?`<div class="gradebookCompetencies" style="display:flex;flex-wrap:wrap;gap:3px;margin-top:4px">${rated.map(c=>{const v=Number(ratings[c]),col={1:'#c62828',2:'#d6a400',3:'#16803c',4:'#1769d2'}[v];return `<span title="${esc(c)} — ${{1:'Insuffisant',2:'Fragile',3:'Bien',4:'Très bien'}[v]}" aria-label="${esc(c)} : niveau ${v}" style="display:inline-block;width:9px;height:9px;border-radius:50%;background:${col}"></span>`}).join('')}</div>`:''}</td>`}).join('')}<td><b>${avg==='—'?'—':avg+' /20'}</b></td></tr>`}).join('')}</tbody></table></div>`}
function evaluationStats(){const c=$('#evalClassFilter')?.value||'',sub=$('#evalSubjectFilter')?.value||'';if(!c)return '<div class="notice">Sélectionne une classe pour afficher ses statistiques.</div>';const es=db.evaluations.filter(e=>e.classId===c&&(!sub||e.subject===sub)),ids=db.students.filter(s=>s.classId===c).map(s=>s.id),vals=es.flatMap(e=>e.grades.filter(g=>ids.includes(g.studentId)&&g.value!=='').map(g=>Number(g.value))).filter(Number.isFinite),overall=weightedAverageForEvaluations(es,ids),groupsList=groups(c),subjects=[...new Set(es.map(e=>e.subject).filter(Boolean))];const evalRows=es.map(e=>{const max=v207EvaluationMax(e),v=e.grades.filter(g=>ids.includes(g.studentId)&&g.value!==''&&g.value!=null).map(g=>Number(g.value)).filter(Number.isFinite).map(n=>n/max*20),av=v.length?(v.reduce((a,b)=>a+b,0)/v.length).toFixed(2):'—';return `<tr><td><b>${esc(e.title)}</b><small class="muted" style="display:block">${esc(e.subject)}</small></td><td>${fmtDate(e.date)}</td><td>${av} /20 <small class="muted">(barème /${max})</small></td><td>${v.length?Math.min(...v).toFixed(2):'—'}</td><td>${v.length?Math.max(...v).toFixed(2):'—'}</td></tr>`}).join('');return `<div class="gradeStats" style="margin-bottom:12px"><div class="metric"><small>Moyenne pondérée de la classe</small><b>${overall} /20</b></div><div class="metric"><small>Élèves</small><b>${ids.length}</b></div><div class="metric"><small>Évaluations</small><b>${es.length}</b></div><div class="metric"><small>Notes saisies</small><b>${vals.length}</b></div></div>${groupsList.length?`<div class="sectionhead"><h3>Par sous-groupe</h3></div><div class="tablewrap"><table class="table"><thead><tr><th>Sous-groupe</th><th>Élèves</th><th>Moyenne</th></tr></thead><tbody>${groupsList.map(g=>`<tr><td><b>${esc(g)}</b></td><td>${db.students.filter(s=>s.classId===c&&s.group===g).length}</td><td><b>${groupAverage(c,g,sub)} /20</b></td></tr>`).join('')}</tbody></table></div>`:''}${subjects.length?`<div class="section"><div class="sectionhead"><h3>Par matière</h3></div><div class="tablewrap"><table class="table"><thead><tr><th>Matière</th><th>Moyenne</th><th>Évaluations</th></tr></thead><tbody>${subjects.map(x=>`<tr><td><b>${esc(x)}</b></td><td>${classAverage(c,x)} /20</td><td>${es.filter(e=>e.subject===x).length}</td></tr>`).join('')}</tbody></table></div></div>`:''}${evalRows?`<div class="section"><div class="sectionhead"><h3>Détail des évaluations</h3><small class="muted">Moyennes, minimums et maximums sont ramenés sur 20 pour être comparables.</small></div><div class="tablewrap"><table class="table"><thead><tr><th>Évaluation</th><th>Date</th><th>Moyenne /20</th><th>Min. /20</th><th>Max. /20</th></tr></thead><tbody>${evalRows}</tbody></table></div></div>`:''}`}
const v207EvalListBase=evalList;evalList=function(){let html=v207EvalListBase();for(const e of db.evaluations||[]){const title=esc(e.title||'');const at=html.indexOf(`<b>${title}</b>`);if(at<0)continue;const subject=esc(e.subject||''),needle=`${subject}</small>`;const p=html.indexOf(needle,at);if(p>=0)html=html.slice(0,p)+`${needle}<small class="muted" style="display:block">Barème : /${v207EvaluationMax(e)}</small>`+html.slice(p+needle.length)}return html};
const v207GradeTableDecorBase=gradeTable;gradeTable=function(e){let html=v207GradeTableDecorBase(e);const max=v207EvaluationMax(e);html=html.replace('<small>Note max</small>',`<small>Note max /${max}</small>`).replace('<small>Note min</small>',`<small>Note min /${max}</small>`);return html};

