  window.mailV2104NewFolder=function(){const role=page==='studentMessages'?'student':'teacher',sid=role==='student'?activeStudent():'',u=me(role,sid);openModal('Créer un dossier',`<form class="v2104Compose" onsubmit="window.mailV2104CreateFolder(event,'${role}','${sid}')"><div class="v2104Field"><label class="v2104FieldLabel">Nom du dossier</label><input class="input" name="name" required maxlength="40" placeholder="Ex. Parents à contacter"></div><div class="modalfoot"><button type="button" class="btn" onclick="closeModal()">Annuler</button><button class="btn primary" type="submit">Créer</button></div></form>`)};
