    const rows=list.map(m=>{const draft=!!m.draft,st=draft?{}:state(m,u),from=draft?'Brouillon':m.sender?.key===u?'Vous':m.sender?.name||labelFor(m.sender?.key),preview=plain(m.body||m.quoted?.body||'');return `<button class="v2104Row ${selected?.id===m.id?'selected':''} ${!draft&&!st.read?'unread':''}" onclick="${draft?`window.mailV2104Open('${m.id}','${role}','${sid}')`:`window.mailV2104Open('${m.id}','${role}','${sid}')`}"><span class="v2104Dot"></span><span class="v2104RowMain"><span class="v2104RowTop"><b>${h(from)}</b><time>${h(date(m.sentAt))}</time></span><strong>${h(m.subject||'(Sans objet)')}</strong><small>${h(preview||'Aucun aperçu disponible')}</small></span>${!draft?`<span class="v2104Star" role="button" title="${st.starred?'Retirer des favoris':'Ajouter aux favoris'}" onclick="event.stopPropagation();window.mailV2104Star('${m.id}','${role}','${sid}')">${st.starred?'★':'☆'}</span>`:''}</button>`}).join('')||`<div class="v2104Blank"><span>✉</span><b>${folder==='drafts'?'Aucun brouillon':'Aucun message ici'}</b><small>${folder==='drafts'?'Les messages enregistrés pour plus tard apparaîtront ici.':'Les messages de ce dossier apparaîtront ici.'}</small></div>`;
