  function mailSafeHtml(value){const raw=String(value||'');if(!raw)return '';if(!/[<>]/.test(raw))return h(raw).replace(/\n/g,'<br>');const tpl=document.createElement('template');tpl.innerHTML=raw;const allowed=new Set(['B','STRONG','I','EM','U','S','P','BR','UL','OL','LI','BLOCKQUOTE','DIV','SPAN','A']);const walk=node=>{for(const child of [...node.childNodes]){if(child.nodeType===1){if(child.tagName==='FONT'){const sizeMap={'1':'0.75em','2':'0.875em','3':'1em','4':'1.125em','5':'1.5em','6':'2em','7':'2.5em'};const span=document.createElement('span');if(sizeMap[child.getAttribute('size')])span.style.fontSize=sizeMap[child.getAttribute('size')];span.innerHTML=child.innerHTML;child.replaceWith(span);walk(span);continue}if(!allowed.has(child.tagName)){child.replaceWith(document.createTextNode(child.textContent||''));continue}for(const a of [...child.attributes]){if(child.tagName==='A'&&a.name==='href'&&/^https?:\/\//i.test(a.value)){child.setAttribute('target','_blank');child.setAttribute('rel','noopener noreferrer')}else if(child.tagName==='SPAN'&&a.name==='style'){const color=(child.style.color||'').trim(),bg=(child.style.backgroundColor||'').trim();child.removeAttribute('style');if(/^#[0-9a-f]{3,8}$/i.test(color)||/^rgb\(/i.test(color))child.style.color=color;if(/^#[0-9a-f]{3,8}$/i.test(bg)||/^rgb\(/i.test(bg))child.style.backgroundColor=bg}else child.removeAttribute(a.name)}walk(child)}else if(child.nodeType!==3)child.remove()}};walk(tpl.content);return tpl.innerHTML}
  window.mailV2104PreviewAttachment=function(name,url,mime=''){if(!url)return toast('Aucun aperçu disponible.');const ext=String(name||'').split('.').pop().toLowerCase(),type=String(mime||'').toLowerCase();let body='';if(type.startsWith('image/')||['png','jpg','jpeg','gif','webp','avif','bmp'].includes(ext))body=`<img src="${h(url)}" alt="${h(name)}" style="display:block;max-width:100%;max-height:68vh;margin:auto;object-fit:contain">`;else if(type==='application/pdf'||ext==='pdf')body=`<iframe title="${h(name)}" src="${h(url)}" style="width:100%;height:68vh;border:1px solid var(--line);border-radius:10px"></iframe>`;else if(type.startsWith('video/')||['mp4','webm','mov'].includes(ext))body=`<video controls playsinline src="${h(url)}" style="display:block;max-width:100%;max-height:68vh;margin:auto"></video>`;else if(type.startsWith('audio/')||['mp3','wav','m4a','ogg'].includes(ext))body=`<audio controls src="${h(url)}" style="width:100%"></audio>`;else if(['txt','csv','md'].includes(ext)||type.startsWith('text/'))body=`<iframe title="${h(name)}" src="${h(url)}" style="width:100%;height:55vh;border:1px solid var(--line);border-radius:10px;background:#fff"></iframe>`;else return window.open(url,'_blank','noopener');openModal(h(name||'Aperçu du fichier'),body+`<div class="modalfoot"><a class="btn" href="${h(url)}" target="_blank" rel="noopener">Ouvrir dans un nouvel onglet</a><button class="btn primary" onclick="closeModal()">Fermer</button></div>`)};
  window.mailV2Model={store,activate,sendOne,state,threadFor,allVisible,folderMessages,user,recipients,canSee,copyOriginalForReply};
  // Compatibilité des widgets historiques (accueil élève / centre d'activité) avec le nouveau modèle.
  window.filteredConversations=function(role='student',sid=''){return (window.mailV2104Recent?window.mailV2104Recent(role,sid):[]).map(m=>({id:m.id,subject:m.subject,createdAt:m.sentAt,type:'mail',_mail:m,teacherId:m.sender?.role==='teacher'?m.sender.id:'',participantIds:[sid]}))};
  window.lastConversationMessage=function(c){const m=c?._mail;if(!m)return null;return {id:m.id,date:m.sentAt,senderName:m.sender?.name||'Message',body:m.body,subject:m.subject}};
