  window.mailV2104Recent=function(role='teacher',sid=''){const u=me(role,sid),groups=new Map();for(const m of allVisible(role,sid)){const st=state(m,u);if(st.folder!=='inbox'||m.sender?.key===u)continue;const key=m.threadId||m.id,old=groups.get(key);if(!old||String(m.sentAt)>String(old.sentAt))groups.set(key,m)}return [...groups.values()].sort((a,b)=>String(b.sentAt).localeCompare(String(a.sentAt))).map(m=>({...m,unread:threadFor(m,role,sid).some(x=>state(x,u).folder==='inbox'&&!state(x,u).read)}))};
  const oldFeed=notificationFeed;window.notificationFeed=function(role='teacher',sid=''){const out=oldFeed(role,sid).filter(n=>n.type!=='mail');const u=me(role,sid),unread=allVisible(role,sid).filter(m=>recipients(m).includes(u)&&!state(m,u).read&&state(m,u).folder==='inbox');const latest=new Map();for(const m of unread){const k=m.threadId||m.id,old=latest.get(k);if(!old||String(m.sentAt)>String(old.sentAt))latest.set(k,m)}for(const m of latest.values())out.push({id:m.id,type:'mail',date:m.sentAt,title:'Nouveau message',label:m.subject,detail:'Un message non lu',action:`window.mailV2Selected='${m.id}';window.mailV2Folder='inbox';go('${role==='student'?'studentMessages':'messages'}')`});return out.sort((a,b)=>String(b.date||'').localeCompare(String(a.date||'')))};
