/* V21.09 — Refonte du module Bulletins */
function term(id){const all=[...(db.settings.terms||[])];if(typeof periodsForMode==='function'){all.push(...periodsForMode('trimestres'),...periodsForMode('semestres'))}return all.find(x=>x.id===id)}
function bulletinTermsForClass(classId){return typeof classPeriods==='function'?classPeriods(classId):(db.settings.terms||[])}
function bulletinSubjectsForClass(classId){return [...new Set([...db.evaluations.filter(e=>e.classId===classId).map(e=>e.subject),...db.schedule.filter(x=>x.classId===classId).map(x=>x.subject)].filter(Boolean))].sort((a,b)=>a.localeCompare(b,'fr'))}
function bulletinFor(studentId,classId,termId){return db.bulletins.find(b=>b.studentId===studentId&&b.classId===classId&&b.termId===termId)}
function createAllBulletins(classId,termId){const ss=db.students.filter(s=>s.classId===classId);let made=0;for(const s of ss){if(bulletinFor(s.id,classId,termId))continue;db.bulletins.push({id:uid(),studentId:s.id,classId,termId,subjectData:{},overall:'',published:false,validated:false});made++}save();render();toast(`${made} bulletin(s) créé(s)`)}
function bulletinSetView(view){const sel=window._bulletinSelection||{};window._bulletinSelection={...sel,view};render()}
function setBulletinCommentFromInput(el){const b=el?.dataset?.bulletinId,sub=el?.dataset?.bulletinSubject;if(b&&sub!==undefined)setBulletinComment(b,sub,el.value)}
function setBulletinCommentForStudentFromInput(el){const d=el?.dataset;if(d?.studentId&&d.classId&&d.termId&&d.bulletinSubject!==undefined)setBulletinCommentForStudent(d.studentId,d.classId,d.termId,d.bulletinSubject,el.value,true)}
function setBulletinComment(id,sub,v){const b=db.bulletins.find(x=>x.id===id);if(!b||b.published)return;if(!canEditBulletinSubject(b.classId,sub))return toast('Tu ne peux modifier que les appréciations de tes matières.');b.subjectData??={};b.subjectData[sub]??={};b.subjectData[sub].comment=v;b.validated=false;save()}
function setBulletinCommentForStudent(sid,cid,tid,sub,v,silent=false){if(!canEditBulletinSubject(cid,sub))return toast('Tu ne peux modifier que les appréciations de tes matières.');let b=bulletinFor(sid,cid,tid);if(!b){b={id:uid(),studentId:sid,classId:cid,termId:tid,subjectData:{},overall:'',published:false,validated:false};db.bulletins.push(b)}if(b.published)return;b.subjectData??={};b.subjectData[sub]??={};b.subjectData[sub].comment=v;b.validated=false;const el=document.querySelector(`[data-bulletin-save="${sid}"]`);if(el)el.textContent='Enregistrement…';save(silent);if(!silent&&el)el.textContent='Enregistré'}
function setBulletinOverall(id,v){const b=db.bulletins.find(x=>x.id===id);if(!b||b.published)return;const c=cls(b.classId),tid=currentTeacherProfile()?.id||'teacher-local';if(authUser?.role!=='admin'&&(!c?.principalTeacherId||c.principalTeacherId!==tid))return toast('Seul le professeur principal peut modifier l’appréciation générale.');b.overall=v;b.validated=false;save()}
function deleteBulletin(id){const b=db.bulletins.find(x=>x.id===id);if(b?.published)return toast('Un bulletin publié ne peut pas être supprimé ici.');confirmModal('Supprimer ce bulletin ?', 'Supprimer',()=>{db.bulletins=db.bulletins.filter(x=>x.id!==id);save();closeModal();render()})}
function subjectAverage(sid,cid,sub,tid){const t=term(tid),st=student(sid),today=iso(new Date());if(!st||st.classId!==cid)return '—';let weighted=0,coef=0;for(const e of (db.evaluations||[])){if(e.classId!==cid||e.subject!==sub||!evaluationModelPublished(e,today)||e.published!==true)continue;if(e.group&&String(e.group)!==String(st.group||''))continue;if(t&&((t.start&&e.date<t.start)||(t.end&&e.date>t.end)))continue;const g=evaluationModelGrade(e,sid),v=evaluationModelOn20(e,g);if(v===null)continue;const c=evaluationModelCoefficient(e);weighted+=v*c;coef+=c}return coef?(weighted/coef).toFixed(2):'—'}
function bulletinAttendance(sid,tid){const t=term(tid);const rows=db.attendance.filter(a=>{if(t&&t.start&&a.date<t.start)return false;if(t&&t.end&&a.date>t.end)return false;return true}).flatMap(a=>a.rows||[]).filter(r=>r.studentId===sid);return {abs:rows.filter(r=>r.status==='absent').length,late:rows.filter(r=>r.status==='retard').length}}
function bulletinStatus(b,subjects){if(!b)return 'À créer';const comments=subjects.filter(s=>String(b.subjectData?.[s]?.comment||'').trim()).length;if(b.published)return 'Publié';if(b.validated)return 'Validé';if(comments===subjects.length&&subjects.length&&String(b.overall||'').trim())return 'Prêt à vérifier';if(comments||String(b.overall||'').trim())return 'En cours';return 'À compléter'}
function toggleBulletinPublished(id){const b=db.bulletins.find(x=>x.id===id);if(!b)return;if(!b.validated)return toast('Le professeur principal doit valider ce bulletin avant publication.');if(!b.published){b.published=true;b.publishedAt=new Date().toISOString();recordBulletinPublicationNotification(b)}save();render();toast('Bulletin publié officiellement')}
function validateBulletin(id){const b=db.bulletins.find(x=>x.id===id);if(!b)return;const c=cls(b.classId),tid=currentTeacherProfile()?.id||'teacher-local';if(authUser?.role!=='admin'&&!c?.principalTeacherId)return toast('Attribue un professeur principal dans les paramètres de la classe.');if(c?.principalTeacherId&&c.principalTeacherId!==tid&&authUser?.role!=='admin')return toast('Seul le professeur principal peut valider ce bulletin.');const subjects=bulletinSubjectsForClass(b.classId),missing=subjects.filter(s=>!String(b.subjectData?.[s]?.comment||'').trim());if(missing.length||!String(b.overall||'').trim())return toast('Complète les appréciations manquantes avant validation.');b.validated=true;b.validatedAt=new Date().toISOString();save();render();toast('Bulletin validé')}
function validateClassBulletins(cid,tid){const c=cls(cid);if(!c)return;const teacher=currentTeacherProfile()?.id||'teacher-local';if(authUser?.role!=='admin'&&!c.principalTeacherId)return toast('Attribue un professeur principal dans les paramètres de la classe.');if(c.principalTeacherId&&c.principalTeacherId!==teacher&&authUser?.role!=='admin')return toast('Seul le professeur principal peut valider cette classe.');const subjects=bulletinSubjectsForClass(cid),ss=db.students.filter(s=>s.classId===cid);if(!ss.length)return toast('Cette classe ne contient aucun élève.');const missing=ss.filter(s=>{const b=bulletinFor(s.id,cid,tid);return !b||!String(b.overall||'').trim()||subjects.some(sub=>!String(b.subjectData?.[sub]?.comment||'').trim())});if(missing.length)return toast(`${missing.length} bulletin(s) incomplet(s) : vérifie les appréciations.`);ss.forEach(s=>{const b=bulletinFor(s.id,cid,tid);if(b&&!b.published){b.validated=true;b.validatedAt=new Date().toISOString()}});save();render();toast('Bulletins validés par le professeur principal')}
function publishClassBulletins(cid,tid){const c=cls(cid),teacher=currentTeacherProfile()?.id||'teacher-local';if(authUser?.role!=='admin'&&!c?.principalTeacherId)return toast('Attribue un professeur principal dans les paramètres de la classe.');if(c?.principalTeacherId&&c.principalTeacherId!==teacher&&authUser?.role!=='admin')return toast('Seul le professeur principal peut publier cette classe.');const ss=db.students.filter(s=>s.classId===cid),bs=ss.map(s=>bulletinFor(s.id,cid,tid));if(!ss.length)return toast('Cette classe ne contient aucun élève.');if(bs.some(b=>!b||!b.validated))return toast('Tous les bulletins doivent être validés avant publication.');const now=new Date().toISOString();bs.forEach(b=>{if(!b.published){b.published=true;b.publishedAt=now;recordBulletinPublicationNotification(b)}});save();render();toast('Publication officielle effectuée')}
function openBulletin(id=null){let b=id?db.bulletins.find(x=>x.id===id):null;if(!id)return openModal('Créer les bulletins d’une classe',`<form onsubmit="createBulletin(event)"><div class="form"><div class="field"><label>Classe *</label><select class="select" name="classId" required><option value="">Choisir</option>${db.classes.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Période *</label><select class="select" name="termId" required>${(db.settings.terms||[]).map(t=>`<option value="${t.id}">${esc(t.name)}</option>`).join('')}</select></div></div><div class="notice section">Cette action crée les bulletins manquants pour tous les élèves de la classe sélectionnée, sans supprimer les bulletins existants.</div><div class="modalfoot"><button type="button" class="btn" onclick="closeModal()">Annuler</button><button class="btn primary">Créer les bulletins manquants</button></div></form>`);if(!b)return;const s=student(b.studentId),c=cls(b.classId),subjects=bulletinSubjectsForClass(b.classId),att=bulletinAttendance(b.studentId,b.termId);const readonly=!!b.published;openModal('Bulletin individuel',`<div class="bulletin"><div class="bulletinhead"><div><h2>Bulletin scolaire</h2><div class="muted">${esc(c?.name||'')} · ${esc(term(b.termId)?.name||'')}</div></div><div><b>${esc(s?.last?.toUpperCase()||'')} ${esc(s?.first||'')}</b><br><small>${fmtDate(s?.birth)}</small></div></div><div class="gradeStats section"><div class="metric"><small>Moyenne générale</small><b>${v101StudentAverage(b.studentId,b.termId)} /20</b></div><div class="metric"><small>Moyenne de classe</small><b>${classAverageForBulletin(b.classId,b.termId)} /20</b></div><div class="metric"><small>Absences</small><b>${att.abs}</b></div><div class="metric"><small>Retards</small><b>${att.late}</b></div></div><div class="bulletinGrid"><div><b>Matière</b></div><div><b>Moyenne</b></div><div><b>Appréciation</b></div>${subjects.map(sub=>`<div>${esc(sub)}</div><div>${subjectAverage(b.studentId,b.classId,sub,b.termId)}</div><div>${readonly?`<div class="printComment">${esc(b.subjectData?.[sub]?.comment||'')}</div>`:`<textarea class="input" rows="2" style="min-height:64px" data-bulletin-id="${esc(b.id)}" data-bulletin-subject="${esc(sub)}" onchange="setBulletinCommentFromInput(this)" placeholder="Appréciation de ${esc(sub)}">${esc(b.subjectData?.[sub]?.comment||'')}</textarea>`}</div>`).join('')}</div><div class="section"><label class="field"><b>Appréciation générale</b>${readonly?`<div class="notice">${esc(b.overall||'')}</div>`:`<textarea onchange="setBulletinOverall('${b.id}',this.value)" placeholder="Bilan général de l’élève…">${esc(b.overall||'')}</textarea>`}</label></div>${b.published?`<div class="notice">Publié officiellement le ${fmtDate(b.publishedAt)}.</div>`:''}</div><div class="modalfoot">${!b.published?`<button class="btn" onclick="validateBulletin('${b.id}')">Valider</button>`:`<button class="btn danger" onclick="unpublishBulletin('${b.id}')">Dépublier</button>`}<button class="btn" onclick="printBulletin('${b.id}')">Aperçu / PDF</button><button class="btn primary" onclick="closeModal();render()">Fermer</button></div>`)}
function classAverageForBulletin(cid,tid){const ss=db.students.filter(s=>s.classId===cid);const vals=ss.map(s=>Number(v101StudentAverage(s.id,tid))).filter(Number.isFinite);return vals.length?(vals.reduce((a,b)=>a+b,0)/vals.length).toFixed(2):'—'}
function createBulletin(e){e.preventDefault();const o=Object.fromEntries(new FormData(e.target));if(!o.classId||!o.termId)return toast('Choisis une classe et une période.');closeModal();createAllBulletins(o.classId,o.termId)}
function bulletinSubjectEntry(){const cid=$('#bulletinClass')?.value||db.classes[0]?.id||'',tid=$('#bulletinTerm')?.value||db.settings.terms[0]?.id||'',sub=$('#bulletinSubject')?.value||bulletinSubjectsForClass(cid)[0]||'';window._bulletinSelection={cid,tid,sub};render()}
