/* MaClasse V21.16 — moteur unique des résultats élèves */
function studentReportToday(today){
  if(today instanceof Date)return iso(today);
  const raw=String(today||'').trim();
  return raw||iso(new Date());
}
function studentReportTerms(sourceDb){
  return [...(sourceDb?.settings?.terms||[])].filter(Boolean).map(t=>({id:t.id,name:t.name||'Période',start:t.start||'',end:t.end||''}));
}
function studentReportEvaluationInTerm(e,selectedTerm){
  if(!selectedTerm)return true;
  const date=String(e?.date||'');
  return (!selectedTerm.start||date>=selectedTerm.start)&&(!selectedTerm.end||date<=selectedTerm.end);
}
function studentReportIsPublished(e,today){
  if(e?.published!==true)return false;
  const publishedAt=String(e.publishAt||'');
  return !publishedAt||publishedAt<=today;
}
function studentReportGradeHasContent(g){
  if(!g)return false;
  if(g.value!==''&&g.value!==null&&g.value!==undefined&&gradeNumber(g.value)!==null)return true;
  return Object.keys(g.criterionScores||{}).length>0||Object.keys(g.competencyRatings||{}).length>0||String(g.comment||'').trim()!=='';
}
function studentReportCoefficient(e){
  const n=Number(e?.coefficient);
  return Number.isFinite(n)&&n>0?n:1;
}
function studentReportItem(e,g){
  const max=v207EvaluationMax(e),raw=gradeNumber(g?.value),coef=studentReportCoefficient(e);
  return {
    evaluationId:e.id,
    title:e.title||'Évaluation',
    raw,
    rawDisplay:g?.value??'',
    max,
    on20:raw===null?null:(raw/max)*20,
    coef,
    date:e.date||'',
    published:e.published===true,
    publishAt:e.publishAt||'',
    comment:g?.comment||'',
    criterionScores:g?.criterionScores||{},
    competencyRatings:g?.competencyRatings||{},
    criteria:e.criteria||[],
    competencies:e.competencies||[],
    subject:e.subject||'Autres'
  };
}
function studentReportAverage(items){
  let sum=0,weight=0;
  for(const item of items||[]){
    if(item.on20===null||!Number.isFinite(item.on20))continue;
    const coef=Number(item.coef)>0?Number(item.coef):1;
    sum+=item.on20*coef;weight+=coef;
  }
  return weight?Number((sum/weight).toFixed(2)):null;
}
function buildStudentReport(sourceDb,studentId,termId='',today){
  const terms=studentReportTerms(sourceDb),selectedTerm=terms.find(t=>t.id===termId)||null,asOf=studentReportToday(today);
  const evaluations=(sourceDb?.evaluations||[]).filter(e=>studentReportIsPublished(e,asOf)&&studentReportEvaluationInTerm(e,selectedTerm));
  const subjectsMap=new Map(),items=[];
  for(const e of evaluations){
    const g=(e.grades||[]).find(x=>x.studentId===studentId);
    if(!studentReportGradeHasContent(g))continue;
    const item=studentReportItem(e,g);items.push(item);
    const subject=item.subject||'Autres';
    if(!subjectsMap.has(subject))subjectsMap.set(subject,[]);
    subjectsMap.get(subject).push(item);
  }
  const subjects=[...subjectsMap.entries()].sort((a,b)=>a[0].localeCompare(b[0],'fr')).map(([name,subjectItems])=>({name,items:subjectItems.sort((a,b)=>String(a.date).localeCompare(String(b.date))),average:studentReportAverage(subjectItems)}));
  const numericItems=items.filter(x=>x.on20!==null&&Number.isFinite(x.on20));
  return {
    studentId,
    termId:selectedTerm?.id||'',
    term:selectedTerm,
    terms,
    subjects,
    items,
    overall:studentReportAverage(items),
    counts:{published:items.length,numeric:numericItems.length,qualitative:items.length-numericItems.length},
    asOf
  };
}
function studentReportFormatAverage(value){return value===null?'—':Number(value).toFixed(2)}
function studentReportTermState(studentId){
  window.v216StudentTermByStudent??={};
  const terms=db.settings?.terms||[],stored=window.v216StudentTermByStudent[studentId];
  return stored&&terms.some(t=>t.id===stored)?stored:(terms[0]?.id||'');
}
function setStudentResultsTerm(studentId,termId){
  window.v216StudentTermByStudent??={};
  window.v216StudentTermByStudent[studentId]=termId||'';
  render();
}
function studentReportDetail(evaluationId,sid){
  const e=db.evaluations.find(x=>x.id===evaluationId),g=e?.grades?.find(x=>x.studentId===sid);if(!e||!g)return;
  const labels={1:'Insuffisant',2:'Fragile',3:'Bien',4:'Très bien'},raw=gradeNumber(g.value),max=v207EvaluationMax(e),normalized=raw===null?null:(raw/max*20).toFixed(2),criteria=e.criteria||[],competencies=e.competencies||[];
  openModal(esc(e.title||'Détail de l’évaluation'),`<div class="v209DetailHead"><div class="v209DetailMeta"><span class="pill blue">${esc(e.subject||'Matière')}</span><p class="muted">${fmtDate(e.date)}${studentReportCoefficient(e)!==1?' · Coefficient '+esc(studentReportCoefficient(e)):''}</p></div><div class="v209DetailScore"><b>${raw===null?'Grille qualitative':esc(g.value)+' / '+max}</b>${raw===null?'':`<small>Équivalent : ${normalized} /20</small>`}</div></div>${g.comment?`<div class="notice" style="margin:12px 0"><b>Appréciation du professeur</b><p>${esc(g.comment)}</p></div>`:''}${criteria.length?`<section class="v209DetailSection"><h3>Détail des critères</h3><div class="tablewrap"><table class="table"><thead><tr><th>Critère</th><th>Résultat</th><th>Descriptif du niveau</th></tr></thead><tbody>${criteria.map(c=>{const score=g.criterionScores?.[c.id],cmax=Math.max(0,Number(c.maxPoints)||Math.max(0,...(c.levels||[]).map(Number))),level=(c.levelDetails||[]).find(x=>Number(x.points)===Number(score));return `<tr><td><b>${esc(c.name)}</b></td><td>${score===undefined?'—':esc(score)+' / '+cmax+' pts'}</td><td>${esc(level?.description||'—')}</td></tr>`}).join('')}</tbody></table></div></section>`:''}${competencies.length?`<section class="v209DetailSection"><h3>Compétences évaluées</h3><div class="v209CompetencyList">${competencies.map(c=>{const v=String(g.competencyRatings?.[c]||''),label=labels[v]||'Non évaluée';return `<div class="v209CompetencyItem"><span class="v209CompetencyName">${esc(c)}</span><b class="v205Level lv${v}">${label}</b></div>`}).join('')}</div></section>`:''}${!criteria.length&&!competencies.length&&!g.comment?'<p class="muted">Aucun détail complémentaire n’a été renseigné pour cette évaluation.</p>':''}<div class="modalfoot"><button class="btn primary" onclick="closeModal()">Fermer</button></div>`);
}
function studentResults(){
  const sid=activeStudent(),s=student(sid);if(!s)return studentHome();
  const termId=studentReportTermState(sid),report=buildStudentReport(db,sid,termId,new Date()),selected=report.term;
  const publishedBulletins=(db.bulletins||[]).filter(b=>b.studentId===sid&&b.published).sort((a,b)=>String(term(b.termId)?.start||'').localeCompare(String(term(a.termId)?.start||'')));
  const bulletinHtml=`<div class="card v14Section"><div class="sectionhead"><div><h2>Mes bulletins officiels</h2><div class="muted">Disponibles après publication officielle par l’équipe enseignante.</div></div><span class="pill ${publishedBulletins.length?'green':'orange'}">${publishedBulletins.length} publié(s)</span></div>${publishedBulletins.map(b=>`<div class="file"><div><b>${esc(term(b.termId)?.name||'Bulletin')}</b><small style="display:block;color:var(--muted)">${esc(cls(b.classId)?.name||'')} · publié le ${fmtDate(b.publishedAt)}</small></div><button class="btn small primary" onclick="printBulletin('${b.id}')">Aperçu / PDF</button></div>`).join('')||'<div class="empty">Aucun bulletin officiel disponible pour le moment.</div>'}</div>`;
  const rows=report.subjects.map(subject=>`<tr class="v209SubjectRow"><th scope="row">${esc(subject.name)}</th><td><div class="v209GradeList">${subject.items.map(item=>{const score=item.raw===null?'Compétences':`${esc(item.rawDisplay)}/${item.max}${item.max!==20?` <small>(base ${item.max})</small>`:''}${item.coef!==1?` <small>(coef. ${item.coef})</small>`:''}`;return `<button type="button" class="v209GradeButton" aria-label="Consulter ${esc(item.title)} du ${fmtDate(item.date)}" onclick="studentReportDetail('${String(item.evaluationId).replaceAll("\\", "\\\\").replaceAll("'", "\\'")}','${String(sid).replaceAll("\\", "\\\\").replaceAll("'", "\\'")}')"><span class="v209GradeTitle"><strong>${esc(item.title)}</strong><small>${fmtDate(item.date)}</small></span><b class="v209GradeScore">${score}</b><span class="v209GradeOpen" aria-hidden="true">›</span></button>`}).join('')}</div></td><td class="v209AverageCell"><b>${studentReportFormatAverage(subject.average)}</b><small>/20</small></td></tr>`).join('');
  return shell('Ma scolarité','Mes résultats','Relevé de notes par période : sélectionnez une note pour consulter le détail des critères et des compétences.',`<button class="btn" onclick="go('studentLife')">Voir ma vie scolaire</button>`)+
  `<div class="v209ResultsToolbar"><div><label for="v216TermSelect">Période scolaire</label><select id="v216TermSelect" class="select" onchange="setStudentResultsTerm('${String(sid).replaceAll("\\", "\\\\").replaceAll("'", "\\'")}',this.value)">${report.terms.map(t=>`<option value="${esc(t.id)}" ${t.id===termId?'selected':''}>${esc(t.name)}</option>`).join('')}</select></div><div class="v209Overall"><small>Moyenne générale de la période</small><strong>${studentReportFormatAverage(report.overall)}<small> /20</small></strong></div></div>
  <div class="card v209ReportCard"><div class="v209ReportHeader"><div><h2>Relevé de notes</h2><p class="muted">${esc(s.first+' '+s.last)} · ${esc(selected?.name||'Toutes les périodes')}</p></div><span class="pill blue">${report.counts.numeric} note${report.counts.numeric>1?'s':''}${report.counts.qualitative?` · ${report.counts.qualitative} résultat${report.counts.qualitative>1?'s':''} qualitatif${report.counts.qualitative>1?'s':''}`:''}</span></div><div class="tablewrap"><table class="table v209ReportTable"><thead><tr><th>Matière</th><th>Notes et évaluations <small>Cliquer sur une note pour voir le détail</small></th><th>Moyenne</th></tr></thead><tbody>${rows||'<tr><td colspan="3"><div class="empty">Aucun résultat publié pour cette période.</div></td></tr>'}<tr class="v209GeneralRow"><th scope="row">Moyenne générale</th><td><span class="muted">Calcul pondéré des notes chiffrées publiées</span></td><td><b>${studentReportFormatAverage(report.overall)}</b><small>/20</small></td></tr></tbody></table></div><div class="v209ReportFoot">Les notes sont affichées sur leur barème d’origine. Le détail indique leur équivalent sur 20. Les évaluations en brouillon ou non encore publiées restent masquées.</div></div>`+bulletinHtml;
}

/* V21.11 — robust dates, direct PDF generation and bulletin unpublication */
function fmtDate(x){if(!x)return '—';const raw=String(x);const d=/^\d{4}-\d{2}-\d{2}$/.test(raw)?new Date(raw+'T12:00:00'):new Date(raw);return Number.isNaN(d.getTime())?'—':d.toLocaleDateString('fr-FR')}
function printBulletin(id){generateBulletinPdf(id,'preview')}
async function generateBulletinPdf(id,action='preview'){const b=db.bulletins.find(x=>x.id===id);if(!b)return;const s=student(b.studentId),c=cls(b.classId),t=term(b.termId),subjects=bulletinSubjectsForClass(b.classId);const stats=vals=>{const a=vals.map(Number).filter(Number.isFinite);return {avg:a.length?a.reduce((x,y)=>x+y,0)/a.length:null,min:a.length?Math.min(...a):null,max:a.length?Math.max(...a):null}};const rows=subjects.map(sub=>({subject:sub,studentAverage:subjectAverage(b.studentId,b.classId,sub,b.termId),classStats:stats(db.students.filter(x=>x.classId===b.classId).map(x=>subjectAverage(x.id,b.classId,sub,b.termId))),comment:b.subjectData?.[sub]?.comment||''}));const overallStats=stats(db.students.filter(x=>x.classId===b.classId).map(x=>v101StudentAverage(x.id,b.termId)));const competencies=(()=>{const summary=competencySummaryForPeriod(b.classId,'',b.termId),labels={1:'Insuffisant',2:'Fragile',3:'Bien',4:'Très bien'};return summary.map(c=>({name:c.name,level:labels[c.ratings.filter(r=>r.studentId===b.studentId).sort((a,z)=>String(z.date).localeCompare(String(a.date)))[0]?.value]||'—'}))})();try{const res=await fetch('/api/bulletin-pdf',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({bulletinId:id,student:{name:[s?.first,s?.last].filter(Boolean).join(' ')},className:c?.name||'—',termName:t?.name||'Période',publishedAt:b.publishedAt||'',published:!!b.published,overall:b.overall||'',average:v101StudentAverage(b.studentId,b.termId),overallStats,rows,competencies,absences:bulletinAttendance(b.studentId,b.termId).abs,late:bulletinAttendance(b.studentId,b.termId).late})});if(!res.ok)throw new Error('PDF');const blob=await res.blob(),url=URL.createObjectURL(blob),filename='Bulletin_'+(s?.last||'eleve')+'_'+(t?.name||'periode').replace(/[^a-z0-9_-]/gi,'_')+'.pdf';if(action==='download'){const a=document.createElement('a');a.href=url;a.download=filename;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);closeModal();return}if(window._bulletinPdfUrl)URL.revokeObjectURL(window._bulletinPdfUrl);window._bulletinPdfUrl=url;openModal('Aperçu du bulletin',`<iframe title="Aperçu du bulletin PDF" src="${url}" style="display:block;width:100%;height:70vh;border:1px solid var(--line);border-radius:8px;background:white"></iframe><div class="modalfoot"><button class="btn primary" style="background:#2563eb;color:white" onclick="generateBulletinPdf('${id}','download')">Télécharger</button><button class="btn" onclick="closeModal()">Fermer</button></div>`)}catch(e){console.error(e);toast('Impossible de générer le PDF. Vérifie que MaClasse est lancé depuis son serveur local.')}}
function unpublishBulletin(id){const b=db.bulletins.find(x=>x.id===id);if(!b||!b.published)return;const c=cls(b.classId),teacher=currentTeacherProfile()?.id||'teacher-local';if(authUser?.role!=='admin'&&c?.principalTeacherId&&c.principalTeacherId!==teacher)return toast('Seul le professeur principal ou un administrateur peut dépublier ce bulletin.');confirmModal('Dépublier ce bulletin ? Il ne sera plus visible par l’élève.','Dépublier',()=>{b.published=false;delete b.publishedAt;b.validated=true;save();closeModal();render();toast('Bulletin dépublié')})}

